-- CCN Council Prep Pro: question bank batch 9 (uploaded study files, October 2026)
-- Run this once in the Supabase SQL Editor. It is safe to run again: questions already
-- in the bank (same wording) are skipped, and new IDs are taken after the current highest ID.
--
-- 745 new questions from 10 uploaded files. Every question has exactly 4 options,
-- one correct answer and an explanation. Text with missing spaces was re-spaced, answers were
-- supplied where the source had none, and 3-option questions got a 4th option.
-- Wrong answer keys found in the sources were corrected; items that were unclear, had no clearly
-- correct option, or were not multiple choice (true/false, select-all, matching) were left out or
-- rewritten as single-best-answer questions. Questions already in the bank were skipped.
--
-- Per source (topic):
--   CCNP Exam Paper II: 18
--   General Neurology MCQs: 58
--   Critical Care Nursing Study Guide: 39
--   UMTH Pre-Professional Paper II, Aug 2023: 121
--   UMTH Pre-Professional Paper I, Aug 2023: 139
--   Post Basic CCN School Questions: 110
--   Nursing Mock Examination: 84
--   Principles of Management MCQs: 139
--   Oxygen Delivery & Cardiac Function: 25
--   Anaesthetic Agents: 12
--
-- New rows are paid content (is_legacy = false, the column default).
-- Also fixes 3 wrong answer keys in existing questions (see the end of this file).

insert into public.questions (id, topic, source, q, opts, ans_idx, exp, category, category_icon, is_active)
select (select coalesce(max(id), 0) from public.questions) + row_number() over (order by v.n),
       v.topic, v.source, v.q, v.opts, v.ans_idx, v.exp, v.category, v.category_icon, true
from (values
(1, 'CCNP Exam Paper II', 'CCNP Exam, Paper II (uploaded past paper)', 'What are the symptoms of premature rupture of membranes?', '["Feeling a gush of fluid from the vagina", "Slow leak or trickle of fluid", "The fluid is clear and odourless", "All of the options"]'::jsonb, 3, 'PROM may present as a sudden gush or a slow trickle of clear, odourless fluid from the vagina.', 'Obstetric & Neonatal', '🤱'),
(2, 'CCNP Exam Paper II', 'CCNP Exam, Paper II (uploaded past paper)', 'Which of these genotypes is most susceptible to severe malaria?', '["AA (normal homozygote)", "AS (sickle-cell trait)", "SS", "SC"]'::jsonb, 0, 'People with normal haemoglobin (HbAA) lack the partial protection against severe falciparum malaria that sickle trait (HbAS) gives.', 'Laboratory Sciences & Haematology', '🔬'),
(3, 'CCNP Exam Paper II', 'CCNP Exam, Paper II (uploaded past paper)', 'The life span of sickled red blood cells is about:', '["120 days", "90 days", "60 days", "20 days"]'::jsonb, 3, 'Sickled red cells are rigid and are destroyed early, surviving only about 10–20 days compared with 120 days for normal red cells.', 'Laboratory Sciences & Haematology', '🔬'),
(4, 'CCNP Exam Paper II', 'CCNP Exam, Paper II (uploaded past paper)', 'A urine output of 0.5 to 1 mL/kg/hour is:', '["Anuria", "Polyuria", "Normal urine output", "Oliguria"]'::jsonb, 2, 'Adult urine output of 0.5–1 mL/kg/hour is normal. Below 0.5 mL/kg/hour is oliguria.', 'Renal & Fluid Balance', '💧'),
(5, 'CCNP Exam Paper II', 'CCNP Exam, Paper II (uploaded past paper)', 'Who was the first to systematically describe management behaviour and pioneer the identification of the principles and skills that underlie effective management?', '["Henri Fayol", "Max Weber", "Frederick Taylor", "Peter Drucker"]'::jsonb, 0, 'Henri Fayol first systematically described management functions and principles (1916).', 'Ethics, Law & Management', '⚖️'),
(6, 'CCNP Exam Paper II', 'CCNP Exam, Paper II (uploaded past paper)', 'A woman who has never been pregnant before is described as:', '["Nulligravida", "Primigravida", "Primipara", "Multigravida"]'::jsonb, 0, 'Nulligravida: a woman who has never been pregnant. Primigravida: pregnant for the first time.', 'Obstetric & Neonatal', '🤱'),
(7, 'CCNP Exam Paper II', 'CCNP Exam, Paper II (uploaded past paper)', 'Mr John, a post-operative patient in ICU, developed a severe fever 4 days after surgery. This is typical of:', '["Primary infection", "Secondary infection", "Malnutrition", "Normal surgical process"]'::jsonb, 1, 'A fever several days after surgery suggests a newly acquired (secondary or nosocomial) infection such as wound infection, pneumonia or UTI.', 'Infection Prevention', '🦠'),
(8, 'CCNP Exam Paper II', 'CCNP Exam, Paper II (uploaded past paper)', 'Premature rupture of membranes is when the membranes rupture:', '["During labour", "Before labour begins", "After labour", "All of the options"]'::jsonb, 1, 'PROM is rupture of the membranes before labour begins.', 'Obstetric & Neonatal', '🤱'),
(9, 'CCNP Exam Paper II', 'CCNP Exam, Paper II (uploaded past paper)', 'A baby delivered at 34 to 37 weeks following premature rupture of membranes is cared for in the:', '["Adult ICU", "Neonatal ICU (NICU)", "Obstetric ward", "Postnatal ward"]'::jsonb, 1, 'A preterm baby (34–37 weeks) after PROM is observed in the neonatal intensive care / special care baby unit.', 'Obstetric & Neonatal', '🤱'),
(10, 'CCNP Exam Paper II', 'CCNP Exam, Paper II (uploaded past paper)', 'What are the risk factors for premature rupture of membranes?', '["History of premature rapture of membrane", "Vaginal bleeding", "History of premature labour", "All of the options"]'::jsonb, 3, 'Previous PROM, previous preterm labour and antepartum bleeding are all risk factors.', 'Obstetric & Neonatal', '🤱'),
(11, 'CCNP Exam Paper II', 'CCNP Exam, Paper II (uploaded past paper)', 'What is the best thing one can do to prevent premature rupture of membranes?', '["Avoid smoking cigarettes", "Maintain a healthy pregnancy", "Attend all prenatal clinic", "All of the options"]'::jsonb, 3, 'Avoiding smoking, attending antenatal clinic and keeping the pregnancy healthy all lower the risk of PROM.', 'Obstetric & Neonatal', '🤱'),
(12, 'CCNP Exam Paper II', 'CCNP Exam, Paper II (uploaded past paper)', 'Goal for a child with respiratory infection: "The child will exhibit adequate oxygenation and a ___ airway" (keep SpO2 >92–93%).', '["Patent", "Potent", "Cleared", "Pertinent"]'::jsonb, 0, 'The goal is a patent (open, clear) airway with SpO2 above about 92%.', 'Respiratory', '🫁'),
(13, 'CCNP Exam Paper II', 'CCNP Exam, Paper II (uploaded past paper)', 'All of the following are Fayol''s elements (functions) of management EXCEPT:', '["Foresight", "Organization", "Equity", "Coordination"]'::jsonb, 2, 'Fayol''s five elements (functions) are forecasting/foresight, organising, commanding, coordinating and controlling. Equity is one of his 14 principles, not an element.', 'Ethics, Law & Management', '⚖️'),
(14, 'CCNP Exam Paper II', 'CCNP Exam, Paper II (uploaded past paper)', 'The method and process of facilitating the peaceful ending of a conflict is called:', '["Conflict", "Psychological trauma", "Conflict resolution", "Fight"]'::jsonb, 2, 'Conflict resolution is the process of bringing a conflict to a peaceful end.', 'Mixed Revision', '📚'),
(15, 'CCNP Exam Paper II', 'CCNP Exam, Paper II (uploaded past paper)', 'The following are common symptoms of eclampsia EXCEPT:', '["Seizures", "Loss of consciousness", "Agitations", "Diabetes"]'::jsonb, 3, 'Eclampsia causes seizures, loss of consciousness and agitation. Diabetes is not a symptom.', 'Obstetric & Neonatal', '🤱'),
(16, 'CCNP Exam Paper II', 'CCNP Exam, Paper II (uploaded past paper)', 'The three types of eclampsia include the following EXCEPT:', '["Antepartum", "Intrapartum", "Pre-partum", "Postpartum"]'::jsonb, 2, 'Eclampsia is classified by timing as antepartum, intrapartum or postpartum. "Pre-partum" is not a category.', 'Obstetric & Neonatal', '🤱'),
(17, 'CCNP Exam Paper II', 'CCNP Exam, Paper II (uploaded past paper)', 'Which is one of the criteria for diagnosing severe pre-eclampsia?', '["Systolic BP of 110 mmHg or diastolic BP of 60 mmHg", "Systolic BP ≥160 mmHg or diastolic BP ≥110 mmHg on 2 occasions at least 4–6 hours apart on bed rest", "Systolic BP of 130 mmHg or diastolic BP of 80 mmHg on 2 occasions", "All of the options"]'::jsonb, 1, 'Severe pre-eclampsia: systolic ≥160 mmHg or diastolic ≥110 mmHg on two occasions at least 4–6 hours apart, or end-organ features.', 'Obstetric & Neonatal', '🤱'),
(18, 'CCNP Exam Paper II', 'CCNP Exam, Paper II (uploaded past paper)', 'All of the following are examples of sickle cell disease EXCEPT:', '["Hb SS", "Hb SC", "Hb AS", "Hb S/β-thalassaemia"]'::jsonb, 2, 'HbSS, HbSC and HbS/β-thalassaemia are sickle-cell diseases. HbAS is sickle-cell trait, a carrier state.', 'Laboratory Sciences & Haematology', '🔬'),
(19, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'Upper motor neuron impairment produces which change in muscle tone?', '["Flaccidity", "Spasticity", "\"Cog-wheel\" rigidity", "Myoclonus"]'::jsonb, 1, 'Upper motor neuron lesions cause spasticity (velocity-dependent increased tone), brisk reflexes and an extensor plantar response.', 'Neurology', '🧠'),
(20, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'Muscle wasting (hypotrophy) usually develops with disease of the:', '["Upper motor neuron", "Lower motor neuron", "Cerebellum", "Caudate nucleus"]'::jsonb, 1, 'Marked muscle wasting is a lower motor neuron sign, caused by loss of the trophic nerve supply to the muscle.', 'Neurology', '🧠'),
(21, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'Loss of temperature and pinprick sensation usually develops with disease of the:', '["Anterior horns of the spinal cord", "Posterior horns of the spinal cord", "Lateral horns of the spinal cord", "Posterior columns of the spinal cord"]'::jsonb, 1, 'Pain and temperature fibres synapse in the posterior (dorsal) horn before crossing to the spinothalamic tract. The posterior columns carry proprioception and vibration.', 'Neurology', '🧠'),
(22, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'A glove-and-stocking pattern of sensory disturbance usually develops with disease of the:', '["Peripheral nerves", "Spinal cord", "Brainstem", "Thalamus"]'::jsonb, 0, 'Glove-and-stocking sensory loss is typical of length-dependent peripheral polyneuropathy, such as diabetic neuropathy.', 'Neurology', '🧠'),
(23, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'A Babinski response usually develops with damage to the:', '["Upper motor neuron", "Lower motor neuron", "Cerebellum", "Thalamus"]'::jsonb, 0, 'An extensor plantar (Babinski) response is a sign of upper motor neuron (pyramidal tract) damage.', 'Neurology', '🧠'),
(24, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'The presence of ataxia suggests damage to any of the following EXCEPT:', '["Cerebellum", "Thalamus", "Vestibular nucleus", "Vagus nerve"]'::jsonb, 3, 'Ataxia comes from cerebellar, sensory (thalamic/posterior column) or vestibular lesions. The vagus nerve does not control coordination.', 'Neurology', '🧠'),
(25, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'The ability to walk along a straight line is most often impaired with:', '["cerebellar dysfunction", "parietal lobe damage", "temporal lobe damage", "ocular motor disturbances"]'::jsonb, 0, 'Tandem (heel-to-toe) walking along a straight line is a sensitive test of cerebellar, especially midline vermis, function.', 'Neurology', '🧠'),
(26, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'Parkinsonism includes combination of the following:', '["Tremor, bradykinesia and muscle rigidity", "Paresis, anaesthesia and muscle spasticity", "Chorea and muscle hypotonia", "Tremor, ataxia and muscle hypotonia"]'::jsonb, 0, 'Parkinsonism is the triad of resting tremor, bradykinesia and rigidity, plus postural instability.', 'Neurology', '🧠'),
(27, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'Hemiplegia, hemianaesthesia and hemianopia occurring together suggest disease of the:', '["spinal cord", "internal capsule", "thalamus", "brainstem"]'::jsonb, 1, 'The internal capsule carries motor, sensory and optic radiation fibres close together, so one lesion can cause hemiplegia, hemianaesthesia and hemianopia (the "three hemis").', 'Neurology', '🧠'),
(28, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'Cerebellar damage may produce any of the following EXCEPT:', '["Positive Romberg''s test", "Abnormal finger-to-nose test", "Abnormal heel-to-knee (heel–shin) test", "Abnormal Rinne and Weber tests"]'::jsonb, 3, 'Rinne and Weber are hearing (tuning fork) tests and do not test the cerebellum. Romberg, finger–nose and heel–shin tests do.', 'Neurology', '🧠'),
(29, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'Brown-Séquard syndrome develops with which type of spinal cord damage?', '["Complete transection", "Anterior horns", "Hemisection (half of the cord)", "Posterior horns"]'::jsonb, 2, 'Brown-Séquard syndrome is hemisection of the cord: ipsilateral weakness and loss of proprioception, contralateral loss of pain and temperature.', 'Neurology', '🧠'),
(30, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'The presence of ptosis suggests damage to cranial nerve:', '["IV", "V", "III", "VII"]'::jsonb, 2, 'The oculomotor nerve (III) supplies levator palpebrae superioris, so a III palsy causes ptosis.', 'Neurology', '🧠'),
(31, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'The presence of dysphagia suggests damage to cranial nerves:', '["V-VII", "IX-X", "VII-XI", "III-VI"]'::jsonb, 1, 'The glossopharyngeal (IX) and vagus (X) nerves supply the pharynx and larynx, so damage causes dysphagia.', 'Neurology', '🧠'),
(32, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'The presence of dysarthria (from tongue weakness) suggests damage to cranial nerve:', '["V", "XI", "XII", "VIII"]'::jsonb, 2, 'The hypoglossal nerve (XII) moves the tongue; tongue weakness produces dysarthria.', 'Neurology', '🧠'),
(33, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'Damage to cranial nerves IX, X and XII produces:', '["Bulbar palsy", "Pseudobulbar palsy", "Brown-Séquard syndrome", "Argyll Robertson pupil"]'::jsonb, 0, 'A lower motor neuron lesion of cranial nerves IX, X and XII, or their medullary nuclei, causes bulbar palsy.', 'Neurology', '🧠'),
(34, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'Dysphasia suggests the impairment of:', '["speech", "gait", "swallowing", "movement"]'::jsonb, 0, 'Dysphasia is a disorder of language (speech) production or comprehension. Dysphagia is difficulty swallowing.', 'Neurology', '🧠'),
(35, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'Broca''s area is located in which lobe?', '["Frontal", "Parietal", "Temporal", "Occipital"]'::jsonb, 0, 'Broca''s (motor speech) area lies in the inferior frontal gyrus of the dominant frontal lobe.', 'Neurology', '🧠'),
(36, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'The patient with apraxia cannot:', '["Name his fingers", "Carry out an imagined (mimed) act", "Draw simple diagrams", "Speak fluently"]'::jsonb, 1, 'Apraxia is inability to carry out learned purposeful movements, such as miming an imagined act, despite intact strength and coordination.', 'Neurology', '🧠'),
(37, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'Which of the following is a meningeal sign?', '["Babinski", "Kernig", "Lasègue", "Romberg"]'::jsonb, 1, 'Kernig''s sign (pain or resistance when extending the knee with the hip flexed) is a meningeal sign.', 'Neurology', '🧠'),
(38, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'Any of the following syndromes is the involuntary movement EXCEPT:', '["Chorea", "Tic", "Tremor", "Paresis"]'::jsonb, 3, 'Chorea, tics and tremor are involuntary movements. Paresis is weakness.', 'Neurology', '🧠'),
(39, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'Which pathological reflex occurs in central paralysis (upper motor neuron lesion)?', '["Brudzinski", "Neri", "Babinski", "Brown-Séquard"]'::jsonb, 2, 'The Babinski reflex is the classic pathological reflex of upper motor neuron (central) paralysis.', 'Neurology', '🧠'),
(40, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'Fasciculations may develop with disease of the:', '["Lateral column of the spinal cord", "Posterior horn of the spinal cord", "Anterior horn of the spinal cord", "Internal capsule"]'::jsonb, 2, 'Fasciculations come from lower motor neuron disease, especially of the anterior horn cells (e.g. motor neuron disease, polio).', 'Neurology', '🧠'),
(41, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'Bilateral damage to the spinal cord at the cervical level may produce:', '["hemiplegia", "paraplegia", "tetraplegia", "monoplegia"]'::jsonb, 2, 'Bilateral cervical cord damage affects all four limbs: tetraplegia (quadriplegia).', 'Neurology', '🧠'),
(42, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'Central paresis and loss of proprioception on one side with loss of pain and temperature sensation on the opposite side form which syndrome?', '["Lambert–Eaton", "Strümpell–Lorrain", "Argyll Robertson", "Brown-Séquard"]'::jsonb, 3, 'Ipsilateral central paresis and proprioceptive loss with contralateral loss of pain and temperature is Brown-Séquard (cord hemisection) syndrome.', 'Neurology', '🧠'),
(43, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'A polyneuropathic pattern of sensory loss presents as:', '["Numbness and pain in the distal parts of the extremities", "Numbness and analgesia in half of the body", "Pain and sensory ataxia in half of the body", "Analgesia and sensory ataxia in the proximal parts of the extremities"]'::jsonb, 0, 'Polyneuropathy causes symmetrical distal numbness, pain and paraesthesia in the hands and feet.', 'Neurology', '🧠'),
(44, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'Hemianaesthesia, hemianopia and sensory hemiataxia together suggest damage to the:', '["Internal capsule", "Thalamus", "Spinal cord", "Substantia nigra"]'::jsonb, 1, 'A thalamic lesion causes contralateral hemianaesthesia, sensory hemiataxia and sometimes hemianopia (thalamic syndrome).', 'Neurology', '🧠'),
(45, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'A positive Lasègue sign (straight-leg raise) suggests damage to:', '["Meninges of the brain", "Spinal roots C5–C8 or radial nerve", "Spinal roots L5–S1 or sciatic nerve", "Anterior horns at the level L5–S1"]'::jsonb, 2, 'Lasègue''s sign (straight-leg raising pain) indicates irritation of the L5–S1 roots or sciatic nerve, e.g. a disc prolapse.', 'Neurology', '🧠'),
(46, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'Dysdiadochokinesia suggests damage to the:', '["Substantia nigra", "Spinal cord", "Cerebellum", "Occipital lobe"]'::jsonb, 2, 'Dysdiadochokinesia, inability to perform rapid alternating movements, is a cerebellar sign.', 'Neurology', '🧠'),
(47, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'Parkinsonism suggests damage to the:', '["Caudate nucleus", "Substantia nigra", "Cerebellum", "Frontal lobe"]'::jsonb, 1, 'Parkinsonism results from loss of dopaminergic neurons in the substantia nigra ("black substance").', 'Neurology', '🧠'),
(48, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'In the initial stage of Parkinson''s disease the most typical involuntary movement is:', '["Chorea", "Athetosis", "Tremor", "Dystonia"]'::jsonb, 2, 'A unilateral resting "pill-rolling" tremor is the commonest first sign of Parkinson''s disease.', 'Neurology', '🧠'),
(49, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'The autonomic nervous system includes any of the following EXCEPT:', '["Hypothalamus", "Paravertebral sympathetic trunk", "Vagus nerve", "Cerebral cortex"]'::jsonb, 3, 'The ANS includes the hypothalamus (its control centre), the sympathetic chain and parasympathetic nerves such as the vagus. The cerebral cortex is not part of it.', 'Neurology', '🧠'),
(50, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'One of the most important functions of the autonomic nervous system is the following:', '["Regulation of homeostasis", "Voluntary movements", "Coordination of movements", "Involuntary movements"]'::jsonb, 0, 'The ANS keeps homeostasis by regulating heart rate, BP, temperature, digestion and other functions.', 'Neurology', '🧠'),
(51, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'All of the following cranial nerves have a parasympathetic nucleus EXCEPT:', '["Vagus", "Oculomotor", "Glossopharyngeal", "Olfactory"]'::jsonb, 3, 'Cranial nerves III, VII, IX and X carry parasympathetic fibres. The olfactory nerve (I) does not.', 'Neurology', '🧠'),
(52, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'Anosmia suggests damage to which cranial nerve?', '["II", "I", "III", "V"]'::jsonb, 1, 'Anosmia (loss of smell) suggests damage to the olfactory nerve (CN I).', 'Neurology', '🧠'),
(53, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'Trigeminal nerve impairment typically produces:', '["Paralysis of half of the face", "Paroxysms of pain in half of the face", "Disturbance of swallowing", "Ache in half of the head"]'::jsonb, 1, 'Trigeminal neuralgia causes paroxysms of severe stabbing pain in the trigeminal distribution on one side of the face. Facial paralysis is a CN VII lesion.', 'Neurology', '🧠'),
(54, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'Bell''s palsy suggests damage to which cranial nerve?', '["Facial", "Optic", "Olfactory", "Vestibulocochlear"]'::jsonb, 0, 'Bell''s palsy is an idiopathic lower motor neuron palsy of the facial nerve (CN VII).', 'Neurology', '🧠'),
(55, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'Dysphagia, dysphonia and dysarthria with tongue atrophy and a depressed gag reflex is called:', '["Bulbar palsy", "Bell''s palsy", "Pseudobulbar palsy", "Olfactory bulb syndrome"]'::jsonb, 0, 'Dysphagia, dysphonia, dysarthria, tongue wasting and an absent gag reflex are lower motor neuron bulbar palsy. Pseudobulbar palsy is upper motor neuron, with a spastic tongue and a brisk jaw jerk.', 'Neurology', '🧠'),
(56, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'Disturbance of purposeful movement in the absence of paresis and incoordination suggests:', '["Dyslexia", "Dysgnosia", "Dyspraxia", "Dysphasia"]'::jsonb, 2, 'Dyspraxia (apraxia) is impaired purposeful movement without weakness or incoordination.', 'Neurology', '🧠'),
(57, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'Meningeal syndrome includes all of the following EXCEPT:', '["Neck stiffness", "Headache", "Photophobia", "Babinski response"]'::jsonb, 3, 'Meningism causes neck stiffness, headache and photophobia. A Babinski response is a pyramidal sign, not a meningeal one.', 'Neurology', '🧠'),
(58, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'The signs of a lower motor neuron lesion include all of the following EXCEPT:', '["Muscular flaccidity", "Depressed deep tendon reflexes", "Muscle wasting", "Muscular spasticity"]'::jsonb, 3, 'Lower motor neuron lesions cause flaccidity, reduced reflexes, wasting and fasciculation/EMG changes. Spasticity is an upper motor neuron sign.', 'Neurology', '🧠'),
(59, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'The signs of an upper motor neuron lesion include all of the following EXCEPT:', '["Muscular spasticity", "Brisk deep tendon reflexes", "Positive Babinski response", "Fibrillations"]'::jsonb, 3, 'Upper motor neuron lesions cause spasticity, brisk reflexes, depressed superficial (abdominal) reflexes and a positive Babinski. Fibrillations are lower motor neuron signs.', 'Neurology', '🧠'),
(60, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'Cauda equina lesions commonly cause all of the following EXCEPT:', '["Burning pain in the legs", "Saddle (perineal) anaesthesia", "Bladder dysfunction", "Spastic paraplegia"]'::jsonb, 3, 'Cauda equina lesions (lower motor neuron roots) cause flaccid, not spastic, leg weakness with saddle anaesthesia, radicular pain and bladder dysfunction.', 'Neurology', '🧠'),
(61, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'Midbrain damage may produce all of the following EXCEPT:', '["Oculomotor nerve palsy", "Ptosis", "Contralateral hemiplegia", "Atrophy of the tongue"]'::jsonb, 3, 'Midbrain lesions affect the oculomotor nucleus (ptosis, diplopia) and the cerebral peduncle (contralateral hemiplegia, as in Weber syndrome). Tongue atrophy is a medullary (CN XII) sign.', 'Neurology', '🧠'),
(62, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'Bulbar palsy typically causes all of the following EXCEPT:', '["Dysphagia", "Dysarthria", "Atrophy of the tongue", "Ptosis"]'::jsonb, 3, 'Bulbar palsy affects cranial nerves IX, X and XII: dysphagia, dysarthria, dysphonia and tongue atrophy. Ptosis is a CN III or sympathetic sign.', 'Neurology', '🧠'),
(63, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'Facial nerve damage typically causes all of the following EXCEPT:', '["Lagophthalmos (inability to close the eye)", "Bell''s phenomenon", "Inability to whistle", "Paresis of the tongue"]'::jsonb, 3, 'Facial nerve palsy causes lagophthalmos, Bell''s phenomenon and inability to whistle. Tongue paresis is a CN XII lesion.', 'Neurology', '🧠'),
(64, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'Optic nerve damage may cause all of the following EXCEPT:', '["Blindness", "Scotoma", "Depressed pupillary light reaction", "Ptosis"]'::jsonb, 3, 'Optic nerve damage causes visual loss, scotomas and an impaired pupillary light reflex (RAPD). Ptosis is not an optic nerve sign.', 'Neurology', '🧠'),
(65, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'Cerebellar disease typically causes all of the following EXCEPT:', '["Gait ataxia", "Hypotonia", "Nystagmus", "Dysphasia"]'::jsonb, 3, 'Cerebellar lesions cause ataxia, hypotonia, limb incoordination and nystagmus. Dysphasia is a cortical language disorder.', 'Neurology', '🧠'),
(66, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'Polyneuropathy typically causes all of the following EXCEPT:', '["Pain and numbness in the extremities", "Distal sensory loss", "Depressed ankle jerks", "Hemianaesthesia"]'::jsonb, 3, 'Polyneuropathy causes distal (glove-and-stocking) sensory loss, pain and numbness, and depressed ankle jerks. Hemianaesthesia points to a central lesion.', 'Neurology', '🧠'),
(67, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'Hemianopia may develop with damage to any of the following EXCEPT:', '["Optic chiasm", "Optic tract", "Occipital lobe", "Frontal lobe"]'::jsonb, 3, 'Hemianopia arises from lesions of the chiasm, optic tract, optic radiation, occipital cortex or lateral geniculate body of the thalamus. Frontal lobe lesions do not cause it.', 'Neurology', '🧠'),
(68, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'Dysphasia may develop with damage to the:', '["Frontal or temporal lobe cortex", "Cerebellar cortex", "Pons", "Hypoglossal nerve"]'::jsonb, 0, 'Dysphasia is a cortical language disorder from dominant frontal (Broca) or temporal (Wernicke) damage. Cerebellar damage gives dysarthria, not dysphasia.', 'Neurology', '🧠'),
(69, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'All of the following are higher cortical (cognitive) dysfunctions EXCEPT:', '["Dysphasia", "Dyslexia", "Dysmnesia (memory disturbance)", "Dysmetria"]'::jsonb, 3, 'Higher cortical functions include language, reading and memory, so dysphasia, dyslexia and dysmnesia are cognitive disorders. Dysmetria is a cerebellar sign.', 'Neurology', '🧠'),
(70, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'Hypothalamic damage may cause all of the following EXCEPT:', '["Sweating disorders", "Blood pressure disturbance", "Cardiac rhythm disturbance", "Facial paresis"]'::jsonb, 3, 'The hypothalamus controls autonomic function, so damage can cause sweating, BP and cardiac rhythm disturbances and panic-like episodes. Facial paresis is not a hypothalamic sign.', 'Neurology', '🧠'),
(71, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'Signs of raised intracranial pressure include all of the following EXCEPT:', '["Early-morning headache", "Nausea and vomiting", "Papilloedema", "Loss of hearing"]'::jsonb, 3, 'Raised ICP causes early-morning headache, vomiting, papilloedema and, late, Cushing''s bradycardia. Hearing loss is not a typical sign.', 'Neurology', '🧠'),
(72, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'All of the following are general (non-focal) brain symptoms EXCEPT:', '["Headache", "Vomiting", "Loss of consciousness", "Hemiparesis"]'::jsonb, 3, 'General (non-focal) brain symptoms are headache, vomiting and altered consciousness. Hemiparesis is a focal sign.', 'Neurology', '🧠'),
(73, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'Which of the following is a FOCAL neurological sign?', '["Headache", "Vomiting", "Hemiparesis", "Generalised drowsiness"]'::jsonb, 2, 'Focal signs point to a specific site, e.g. hemiparesis, ptosis or incoordination. Headache is a general symptom.', 'Neurology', '🧠'),
(74, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'All of the following are meningeal signs EXCEPT:', '["Neck stiffness", "Kernig''s sign", "Brudzinski''s sign", "Babinski sign"]'::jsonb, 3, 'Meningeal signs are neck stiffness and Kernig''s and Brudzinski''s signs. Babinski is a pyramidal sign.', 'Neurology', '🧠'),
(75, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'All of the following are typical of parkinsonism EXCEPT:', '["Resting tremor", "\"Cog-wheel\" rigidity", "Mask-like face", "Intention tremor"]'::jsonb, 3, 'Parkinsonism causes resting tremor, cog-wheel rigidity, a mask-like face and bradykinesia. Intention tremor is cerebellar.', 'Neurology', '🧠'),
(76, 'General Neurology MCQs', 'General Neurology MCQ bank, 2013 (uploaded)', 'All of the following are hyperkinetic involuntary movement disorders EXCEPT:', '["Chorea", "Athetosis", "Torsion dystonia", "Bradykinesia"]'::jsonb, 3, 'Hyperkinesias (excess involuntary movements) include chorea, athetosis and dystonia. Bradykinesia is slowness of movement (hypokinesia).', 'Neurology', '🧠'),
(77, 'Critical Care Nursing Study Guide', 'Critical Care Nursing study guide questions (uploaded)', 'During electronic health documentation, which computer part allows a critical care nurse to enter patient data?', '["Input device", "Software", "Output device", "Operating system"]'::jsonb, 0, 'Input devices (keyboard, mouse, touchscreen, scanner) put data into the computer. Output devices (monitor, printer) display it.', 'Nursing Informatics & ICT', '💻'),
(78, 'Critical Care Nursing Study Guide', 'Critical Care Nursing study guide questions (uploaded)', 'To provide rapid pain relief in the ICU, which of the following routes of opioid administration is most appropriate?', '["Intradermal", "Intraspinal", "Sublingual", "Intravenous"]'::jsonb, 3, 'IV opioids act within minutes and can be titrated, which makes IV the route for rapid pain relief in ICU.', 'ICU Pharmacology', '💊'),
(79, 'Critical Care Nursing Study Guide', 'Critical Care Nursing study guide questions (uploaded)', 'Which of the following is a procedure that enables the researcher to organise, interpret, and communicate numerical information?', '["Means", "Descriptive", "Statistics", "Inferential"]'::jsonb, 2, 'Statistics is the set of procedures for organising, summarising, interpreting and communicating numerical data.', 'Research & Nursing Process', '📊'),
(80, 'Critical Care Nursing Study Guide', 'Critical Care Nursing study guide questions (uploaded)', 'In patients with respiratory distress, damage to type II alveolar cells can impair which of the following key functions?', '["Immunity", "Capacitation", "Gaseous exchange", "Secretion of surfactant"]'::jsonb, 3, 'Type II pneumocytes secrete surfactant, which lowers alveolar surface tension and prevents collapse. Damage leads to atelectasis, as in ARDS.', 'Respiratory', '🫁'),
(81, 'Critical Care Nursing Study Guide', 'Critical Care Nursing study guide questions (uploaded)', 'Most of the body cells'' energy is derived from chemical reactions, which can only take place in the presence of:', '["Oxygen", "ATP", "Carbon dioxide", "Blood"]'::jsonb, 0, 'Aerobic metabolism (oxidative phosphorylation) needs oxygen and produces most of the cell''s ATP.', 'Anatomy & Physiology', '🧬'),
(82, 'Critical Care Nursing Study Guide', 'Critical Care Nursing study guide questions (uploaded)', 'What is the body''s first metabolic pathway for breaking down glucose to release energy?', '["Glycosides", "Glycolysis", "Glucosides", "Glycogenolysis"]'::jsonb, 1, 'Glycolysis, in the cytoplasm, is the first pathway of glucose breakdown, giving pyruvate and 2 ATP.', 'Anatomy & Physiology', '🧬'),
(83, 'Critical Care Nursing Study Guide', 'Critical Care Nursing study guide questions (uploaded)', 'In applying the principle of pain management, which of the following is the first consideration?', '["A multidisciplinary approach is needed", "The client must believe in the perception of their own pain", "Treatment is based on the client''s goals", "Drug side effects must be prevented"]'::jsonb, 1, 'Pain is whatever the patient says it is. Believing the patient''s report of their pain is the first principle of pain management.', 'Mixed Revision', '📚'),
(84, 'Critical Care Nursing Study Guide', 'Critical Care Nursing study guide questions (uploaded)', 'A patient undergoes pulmonary function testing. The following are static lung volumes that can be evaluated EXCEPT:', '["Inspiratory reserve volume", "Inspiratory capacity", "Expiratory reserve volume", "Tidal volume"]'::jsonb, 1, 'IRV, ERV and tidal volume are single volumes. Inspiratory capacity (TV + IRV) is a capacity, the sum of two volumes.', 'Respiratory', '🫁'),
(85, 'Critical Care Nursing Study Guide', 'Critical Care Nursing study guide questions (uploaded)', 'The following glial cells are located in the central nervous system EXCEPT:', '["Ependymal cell", "Astrocyte", "Microglia", "Schwann cell"]'::jsonb, 3, 'Schwann cells myelinate peripheral nerves (PNS). Astrocytes, microglia, ependymal cells and oligodendrocytes are CNS glia.', 'Anatomy & Physiology', '🧬'),
(86, 'Critical Care Nursing Study Guide', 'Critical Care Nursing study guide questions (uploaded)', 'Which of the following is an example of an Internet browser?', '["Internet Navigator", "Notepad", "Microsoft Word", "Internet Explorer"]'::jsonb, 3, 'A web browser (Internet Explorer, Chrome, Firefox, Edge) is software for viewing websites. Notepad and Word are text editors.', 'Nursing Informatics & ICT', '💻'),
(87, 'Critical Care Nursing Study Guide', 'Critical Care Nursing study guide questions (uploaded)', 'Which of the following statements is correct about operational definitions?', '["Specify methods of observing the variables in a study", "Do not vary from study to study", "Apply to every study whenever used", "Dictionary meaning is adequate"]'::jsonb, 0, 'An operational definition states exactly how a variable will be observed or measured in that particular study.', 'Research & Nursing Process', '📊'),
(88, 'Critical Care Nursing Study Guide', 'Critical Care Nursing study guide questions (uploaded)', 'Which of the following does the oxygen-haemoglobin dissociation curve demonstrate?', '["Relationship between tidal volume and vital capacity", "Amount of oxygen transported by blood", "Thermodynamic activity of oxygen", "Relationship between partial pressure of oxygen and percentage of haemoglobin saturation"]'::jsonb, 3, 'The oxyhaemoglobin dissociation curve plots PaO2 against haemoglobin oxygen saturation (SaO2). Its sigmoid shape shifts left or right with pH, temperature, CO2 and 2,3-DPG.', 'Respiratory', '🫁'),
(89, 'Critical Care Nursing Study Guide', 'Critical Care Nursing study guide questions (uploaded)', 'Which of the following measures the pressure necessary for adequate perfusion of the organs?', '["Pulse rate", "Hydrostatic pressure", "Blood pressure", "Mean arterial pressure"]'::jsonb, 3, 'MAP (normally 70–100 mmHg, target ≥65 in shock) reflects organ perfusion pressure. MAP = DBP + ⅓(SBP − DBP).', 'Cardiovascular', '🫀'),
(90, 'Critical Care Nursing Study Guide', 'Critical Care Nursing study guide questions (uploaded)', 'Which of the following is typically NOT a complication of enteral feeding via nasogastric tube?', '["Dehydration", "Blood clots", "Digestive complication", "Aspiration"]'::jsonb, 1, 'NG feeding complications include aspiration, diarrhoea or other GI upset, and fluid or electrolyte problems. Blood clots are not typical.', 'GI, Endocrine & Metabolic', '🍽️'),
(91, 'Critical Care Nursing Study Guide', 'Critical Care Nursing study guide questions (uploaded)', 'In data transfer process, what does FTP stand for?', '["File transfer program", "File transmission protocol", "File transfer Protocol", "File transfer protection"]'::jsonb, 2, 'FTP is File Transfer Protocol, a standard way of moving files between computers over a network.', 'Nursing Informatics & ICT', '💻'),
(92, 'Critical Care Nursing Study Guide', 'Critical Care Nursing study guide questions (uploaded)', 'The short period that occurs during the transmission of impulses through the synapses is:', '["Synaptic simulation", "Synaptic junction", "Synaptic cleft", "Synaptic delay"]'::jsonb, 3, 'Synaptic delay (about 0.5 ms) is the time taken for neurotransmitter release, diffusion and receptor binding at a synapse.', 'Anatomy & Physiology', '🧬'),
(93, 'Critical Care Nursing Study Guide', 'Critical Care Nursing study guide questions (uploaded)', 'What is the appropriate amount of time to suction a patient in a single interval?', '["No more than 20 – 30 seconds", "No more than 10 – 20 seconds", "No more than 5 – 10 seconds", "No more than 10 – 15 seconds"]'::jsonb, 3, 'Apply suction for no more than 10–15 seconds per pass to limit hypoxaemia, bradycardia and mucosal trauma. Pre-oxygenate first.', 'Respiratory', '🫁'),
(94, 'Critical Care Nursing Study Guide', 'Critical Care Nursing study guide questions (uploaded)', 'Which principle is an obligation to tell the truth and not lie or deceive the patient?', '["Fidelity", "Veracity", "Confidentiality", "Justice"]'::jsonb, 1, 'Veracity is the duty to tell the truth. Fidelity means keeping promises.', 'Ethics, Law & Management', '⚖️'),
(95, 'Critical Care Nursing Study Guide', 'Critical Care Nursing study guide questions (uploaded)', 'Which condition involves rapid air accumulation in the pleural space leading to mediastinal shift?', '["Tension pneumothorax", "Open pneumothorax", "Spontaneous pneumothorax", "Iatrogenic pneumothorax"]'::jsonb, 0, 'In tension pneumothorax a one-way valve traps air, raising pressure, collapsing the lung and shifting the mediastinum. It needs immediate decompression.', 'Respiratory', '🫁'),
(96, 'Critical Care Nursing Study Guide', 'Critical Care Nursing study guide questions (uploaded)', 'Negative pressure transmitted by a self-contained disposable chest drain is assessed by:', '["Wall vacuum regulator", "High negative pressure relief valve", "Level of water in water seal", "Dial setting on the suction control chamber"]'::jsonb, 3, 'In dry-suction drains, the suction level is set and checked on the suction control chamber dial.', 'Respiratory', '🫁'),
(97, 'Critical Care Nursing Study Guide', 'Critical Care Nursing study guide questions (uploaded)', 'Trauma patient with stab wound and BP 85 mmHg, lung fields clear. Next line of action?', '["Tube thoracostomy", "FAST examination", "CT scan of chest", "Pelvic X-ray"]'::jsonb, 1, 'A hypotensive trauma patient with clear lung fields needs a FAST scan to look for intra-abdominal or pericardial bleeding.', 'Burns & Trauma', '🔥'),
(98, 'Critical Care Nursing Study Guide', 'Critical Care Nursing study guide questions (uploaded)', 'Primary difference between morning sickness and hyperemesis gravidarum?', '["Hyperemesis typically requires medical treatment", "Hyperemesis resolves after 1st trimester", "Morning sickness is more severe", "Morning sickness occurs only in the evening"]'::jsonb, 0, 'Hyperemesis gravidarum is severe, persistent vomiting causing dehydration, ketosis and weight loss (over 5%), and usually needs medical treatment such as IV fluids and antiemetics.', 'Obstetric & Neonatal', '🤱'),
(99, 'Critical Care Nursing Study Guide', 'Critical Care Nursing study guide questions (uploaded)', 'Initial effect of insulin deficiency in DKA pathophysiology?', '["Acetone accumulation", "Serum levels of glycerol and free fatty acids increase", "Glucagon excess", "Triglycerides metabolised for energy"]'::jsonb, 1, 'Without insulin, lipolysis rises first, increasing serum glycerol and free fatty acids. The liver then turns these into ketones.', 'GI, Endocrine & Metabolic', '🍽️'),
(100, 'Critical Care Nursing Study Guide', 'Critical Care Nursing study guide questions (uploaded)', 'Type of burn from accidentally placing hand in a pot of hot soup?', '["Blister burns", "Contact burns", "Accidental burns", "Scald burns"]'::jsonb, 3, 'A scald is a burn from hot liquid or steam, such as hot soup.', 'Burns & Trauma', '🔥'),
(101, 'Critical Care Nursing Study Guide', 'Critical Care Nursing study guide questions (uploaded)', 'Fasciitis is commonly characterised as which type of infection?', '["Mono-microbial", "Entity microbial", "Polymicrobial", "Gram-negative microbial"]'::jsonb, 2, 'Necrotising fasciitis type I, the commonest form, is polymicrobial (mixed aerobes and anaerobes). Type II is usually group A strep.', 'Infection Prevention', '🦠'),
(102, 'Critical Care Nursing Study Guide', 'Critical Care Nursing study guide questions (uploaded)', 'Purpose of erythromycin ointment in neonates?', '["Ophthalmia neonatorum", "Strabismus", "Cataracts", "Diabetes retinopathy"]'::jsonb, 0, 'Erythromycin (or tetracycline) eye ointment at birth prevents ophthalmia neonatorum from gonococcal or chlamydial infection.', 'Obstetric & Neonatal', '🤱'),
(103, 'Critical Care Nursing Study Guide', 'Critical Care Nursing study guide questions (uploaded)', 'Which patient can safely receive AB-negative blood?', '["O-negative", "B-negative", "AB-negative", "A-negative"]'::jsonb, 2, 'AB-negative red cells carry A and B antigens, so of these recipients only an AB-negative patient can receive them safely.', 'Laboratory Sciences & Haematology', '🔬'),
(104, 'Critical Care Nursing Study Guide', 'Critical Care Nursing study guide questions (uploaded)', 'What describes the ''dawn phenomenon''?', '["Late evening hypoglycemia", "Late evening hyperglycaemia", "Early morning hyperglycemia", "Early morning hypoglycemia"]'::jsonb, 2, 'The dawn phenomenon is early-morning hyperglycaemia caused by overnight surges of growth hormone and cortisol. (Somogyi is rebound after night-time hypoglycaemia.)', 'GI, Endocrine & Metabolic', '🍽️'),
(105, 'Critical Care Nursing Study Guide', 'Critical Care Nursing study guide questions (uploaded)', 'Parameters consistent with safe early mobilization EXCEPT:', '["SpO2 < 88%", "FiO2 < 60%", "HR < 130 bpm", "MAP 60-100 mmHg"]'::jsonb, 0, 'Safe early mobilisation needs SpO2 ≥88–90%, FiO2 <60%, HR <130 bpm and MAP 60–100 mmHg. SpO2 below 88% is a reason to hold off.', 'Rehabilitation & Mobilization', '🏃'),
(106, 'Critical Care Nursing Study Guide', 'Critical Care Nursing study guide questions (uploaded)', 'Patient deep breathing and coughing during suctioning is positive because:', '["Provides an oxygenator", "Deep breathing has zero effect", "Impossible with respiratory disease", "Deep breathing oxygenates, coughing loosens secretions"]'::jsonb, 3, 'Deep breathing improves oxygenation and lung expansion, and coughing helps move secretions up for suctioning.', 'Respiratory', '🫁'),
(107, 'Critical Care Nursing Study Guide', 'Critical Care Nursing study guide questions (uploaded)', 'First action in a precipitous delivery?', '["Establish an airway for the newborn", "Arrange transport", "Ascertain condition of fundus", "Tie and cut cord"]'::jsonb, 0, 'In a precipitous birth the first priority is the newborn''s airway: clear the mouth and nose, then dry and keep warm.', 'Obstetric & Neonatal', '🤱'),
(108, 'Critical Care Nursing Study Guide', 'Critical Care Nursing study guide questions (uploaded)', 'Justice in healthcare ethics is primarily concerned with:', '["Good and fairness", "Equality and fairness", "Treating everyone the same", "The law"]'::jsonb, 1, 'Justice is about fairness and equity: fair, equal distribution of care and resources.', 'Ethics, Law & Management', '⚖️'),
(109, 'Critical Care Nursing Study Guide', 'Critical Care Nursing study guide questions (uploaded)', 'Stool that is pale, oily, and foul-smelling is called:', '["Melaena", "Currant-jelly stool", "Steatorrhoea", "Haematochezia"]'::jsonb, 2, 'Steatorrhoea is pale, bulky, greasy, foul-smelling stool from fat malabsorption (e.g. pancreatic insufficiency).', 'GI, Endocrine & Metabolic', '🍽️'),
(110, 'Critical Care Nursing Study Guide', 'Critical Care Nursing study guide questions (uploaded)', 'Most appropriate treatment for clotted haemodialysis shunt?', '["Broad-spectrum antibiotics", "Systemic urokinase", "Consult a vascular surgeon", "Irrigate with heparinized saline"]'::jsonb, 2, 'A clotted shunt or fistula needs urgent referral to the vascular surgeon (or interventional radiology) for thrombectomy. Do not force-irrigate it.', 'Renal & Fluid Balance', '💧'),
(111, 'Critical Care Nursing Study Guide', 'Critical Care Nursing study guide questions (uploaded)', 'A nurse loves caring for the elderly. This represents her:', '["Respect", "Dignity", "Fidelity", "Values"]'::jsonb, 3, 'Values are a person''s deeply held beliefs about what is worthwhile, such as a love of caring for older people.', 'Ethics, Law & Management', '⚖️'),
(112, 'Critical Care Nursing Study Guide', 'Critical Care Nursing study guide questions (uploaded)', 'Objective of the principle of ''order'' in healthcare management?', '["Framework for giving orders", "Orderly arrangement for resources", "Framework for receiving top management orders", "Receiving orders from bottom to top"]'::jsonb, 1, 'Fayol''s principle of order means "a place for everything and everything in its place", the orderly arrangement of people and materials.', 'Ethics, Law & Management', '⚖️'),
(113, 'Critical Care Nursing Study Guide', 'Critical Care Nursing study guide questions (uploaded)', 'Which of the following is in contrast with the guiding principles of trauma care?', '["Safety", "Reliability", "Collaboration", "Choice"]'::jsonb, 1, 'Trauma-informed care principles are safety, trustworthiness and transparency, peer support, collaboration, empowerment/voice/choice and cultural sensitivity. "Reliability" is not one of them.', 'Ethics, Law & Management', '⚖️'),
(114, 'Critical Care Nursing Study Guide', 'Critical Care Nursing study guide questions (uploaded)', 'Which blood cells are destroyed in a delayed haemolytic transfusion reaction?', '["White blood cells", "Red blood cells", "Platelets", "Plasma cells"]'::jsonb, 1, 'A delayed haemolytic transfusion reaction is immune destruction of the transfused red cells (RBCs) days after transfusion, usually from an anamnestic antibody response.', 'Laboratory Sciences & Haematology', '🔬'),
(115, 'Critical Care Nursing Study Guide', 'Critical Care Nursing study guide questions (uploaded)', 'The first 60 minutes after the onset of an injury is called the:', '["Golden hour", "Miracle hour", "Precious hour", "Critical hour"]'::jsonb, 0, 'The "golden hour" is the first 60 minutes after injury, when prompt resuscitation and definitive care most improve survival.', 'Burns & Trauma', '🔥'),
(116, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'The controlling function finds out how far __________ deviates from standards.', '["Actual performance", "Improvement", "Corrective actions", "Cost"]'::jsonb, 0, 'Controlling compares actual performance with the set standards to find deviations, then corrects them.', 'Ethics, Law & Management', '⚖️'),
(117, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Which of the following is NOT a step in the process of controlling?', '["Analysing deviations", "Integrating employees'' efforts", "Taking corrective measures", "Setting performance standards"]'::jsonb, 1, 'Controlling means setting standards, measuring performance, analysing deviations and taking corrective action. Integrating employees'' efforts is coordinating/directing.', 'Ethics, Law & Management', '⚖️'),
(118, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Remedial actions taken to prevent deviation in future are called:', '["Measurement of actual performance", "Taking corrective actions", "Analysing deviations", "Setting performance standards"]'::jsonb, 1, 'Corrective (remedial) action fixes the cause of a deviation so it does not happen again.', 'Ethics, Law & Management', '⚖️'),
(119, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'The process of attracting qualified persons to apply for jobs that are open is referred to as:', '["Training", "Recruitment", "Human resource management", "Transfer"]'::jsonb, 1, 'Recruitment is attracting qualified people to apply for vacant jobs. Selection then picks the best applicant.', 'Ethics, Law & Management', '⚖️'),
(120, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Which of the following is NOT a step in the selection process?', '["Testing", "Checking references", "Attitude formation", "Medical examination"]'::jsonb, 2, 'Selection includes tests, interviews, reference checks and medical examination. Attitude formation is not a selection step.', 'Ethics, Law & Management', '⚖️'),
(121, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Which of the following is NOT a performance appraisal factor?', '["Attendance", "Attitude", "Quality of work", "Number of social media handles"]'::jsonb, 3, 'Appraisal looks at job-related factors such as attendance, attitude and quality of work, not personal social-media activity.', 'Ethics, Law & Management', '⚖️'),
(122, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Controlling in management is of which type?', '["Preventive only", "Corrective only", "Both preventive and corrective", "Neither preventive nor corrective"]'::jsonb, 2, 'Controlling is both preventive (anticipating problems) and corrective (fixing deviations).', 'Ethics, Law & Management', '⚖️'),
(123, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Which of the following is an element of directing?', '["Motivation", "Leadership", "Communication", "All of these"]'::jsonb, 3, 'Directing combines motivation, leadership, communication and supervision.', 'Ethics, Law & Management', '⚖️'),
(124, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'The process of converting a message into words, pictures or gestures is known as:', '["Decoding", "Encoding", "Feedback", "Medium"]'::jsonb, 1, 'Encoding turns an idea into symbols (words, pictures, gestures) to send. Decoding is how the receiver interprets them.', 'Ethics, Law & Management', '⚖️'),
(125, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'A production manager contacting the division manager to discuss the schedule of product delivery and quality is an example of:', '["Lateral communication", "Upward communication", "Downward communication", "Grapevine communication"]'::jsonb, 0, 'Lateral (horizontal) communication happens between people at the same level, such as two managers coordinating delivery schedules.', 'Ethics, Law & Management', '⚖️'),
(126, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'The history of the Nigerian legal system can be linked to the arrival of the colonial masters as merchants in:', '["1961–1963", "1861–1863", "1971–1973", "1900–1903"]'::jsonb, 1, 'British influence in Nigeria began formally with the annexation of Lagos in 1861 and English law was introduced in 1863, the start of the Nigerian legal system.', 'Ethics, Law & Management', '⚖️'),
(127, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'In order of superiority (highest first), the Nigerian courts can be arranged as:', '["Supreme Court, Court of Appeal, High Court, Magistrate Court, Area Court", "Area Court, Supreme Court, Court of Appeal, High Court, Magistrate Court", "Supreme Court, Area Court, High Court, Magistrate Court, Court of Appeal", "Magistrate Court, Supreme Court, Court of Appeal, High Court, Area Court"]'::jsonb, 0, 'The hierarchy runs Supreme Court, Court of Appeal, High Court, then Magistrate and Area/Customary Courts.', 'Ethics, Law & Management', '⚖️'),
(128, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Which is one of the twin Latin maxims applied in the principles of fair hearing?', '["Nemo dat quod non habet", "Ubi jus ibi remedium", "Nemo judex in causa sua", "Res ipsa loquitur"]'::jsonb, 2, 'Fair hearing rests on two maxims: audi alteram partem (hear the other side) and nemo judex in causa sua (no one should judge their own case).', 'Ethics, Law & Management', '⚖️'),
(129, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'The following are among the patients'' bill of rights EXCEPT:', '["Right to access care when and as due", "Right to get married before discharge", "Right to prompt attention and attendance", "Right to dignity and personality"]'::jsonb, 1, 'The patients'' bill of rights covers prompt attention, dignity and access to care. Getting married before discharge is not a patient right.', 'Ethics, Law & Management', '⚖️'),
(130, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'A patient''s confidential information may be disclosed in which instance?', '["In order to take him to the hospital", "To prevent harm or grievous injury", "To pay the patient''s hospital bill", "To tell the doctor the truth"]'::jsonb, 1, 'Confidential information may be disclosed without consent when needed to prevent serious harm to the patient or others, or when required by law.', 'Ethics, Law & Management', '⚖️'),
(131, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'These are duties of care the defendant (nurse) owes the plaintiff (patient) EXCEPT:', '["Not to breach his right to privacy", "Not to disclose his condition without consent", "To treat him free of charge", "Prompt attention at the time of need"]'::jsonb, 2, 'Duty of care includes privacy, confidentiality and prompt attention. Free treatment is not part of the legal duty of care.', 'Ethics, Law & Management', '⚖️'),
(132, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Damage in law means:', '["Injury sustained on the football pitch", "Loss of a wrist watch in the market", "Loss or injury to person or property", "Loss of money in an armed robbery"]'::jsonb, 2, 'In law, damage is loss or injury to a person or their property, for which damages (compensation) may be awarded.', 'Ethics, Law & Management', '⚖️'),
(133, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Autonomy in Greek means:', '["Come close to me", "Automatic brain charger", "Automatic brake system", "Self-rule"]'::jsonb, 3, 'Autonomy comes from the Greek autos (self) and nomos (rule): self-rule or self-determination.', 'Ethics, Law & Management', '⚖️'),
(134, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Beneficence is akin to:', '["Doing well or good", "Doing an extraordinary duty", "Coming to work punctually", "Coming to work late"]'::jsonb, 0, 'Beneficence is the duty to do good and act in the patient''s best interest.', 'Ethics, Law & Management', '⚖️'),
(135, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'The patients'' bill of rights may include:', '["Explaining procedures to the patient before commencing them", "Visiting patients at home", "Teaching a patient how to dance", "Paying the patient''s hospital bill"]'::jsonb, 0, 'Explaining a procedure before starting it respects the patient''s right to information and informed consent.', 'Ethics, Law & Management', '⚖️'),
(136, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'FOIA means:', '["Free of Injuries Always", "Father of Indigenous Actors", "Freedom of Information Act", "Fear of Indian Antelopes"]'::jsonb, 2, 'FOIA is the Freedom of Information Act, 2011 in Nigeria, which gives the public a right of access to public records.', 'Ethics, Law & Management', '⚖️'),
(137, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Chest physiotherapy includes the following EXCEPT:', '["Closed-chain exercises", "Diaphragmatic breathing exercises", "Pursed-lip breathing exercises", "None of the above"]'::jsonb, 0, 'Chest physiotherapy includes breathing exercises (diaphragmatic, pursed-lip), percussion, vibration and postural drainage. Closed-chain exercises are musculoskeletal (limb) exercises.', 'Rehabilitation & Mobilization', '🏃'),
(138, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'The right lung consists of which lobes?', '["Upper and lower lobes", "Lower lobe and lingula", "Only a posterior lobe", "Upper, middle and lower lobes"]'::jsonb, 3, 'The right lung has three lobes (upper, middle, lower). The left has two (upper with lingula, and lower).', 'Anatomy & Physiology', '🧬'),
(139, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Electrotherapy equipment includes:', '["MRI", "Mammogram", "Transcutaneous electrical nerve stimulation (TENS)", "Spirometer"]'::jsonb, 2, 'TENS (transcutaneous electrical nerve stimulation) is electrotherapy equipment. MRI, mammography and spirometers are diagnostic.', 'Rehabilitation & Mobilization', '🏃'),
(140, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'A contraindication to chest physiotherapy in critically ill patients is:', '["Chest secretions", "Difficulty in breathing", "Rib fractures", "Ineffective coughing"]'::jsonb, 2, 'Rib fractures are a contraindication to chest percussion and vibration. Secretions and poor cough are indications for physiotherapy.', 'Rehabilitation & Mobilization', '🏃'),
(141, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'The following are therapeutic techniques used in critically ill patients EXCEPT:', '["Manual hyperinflation", "Manual hyperoxygenation", "Jogging", "Airway clearance techniques"]'::jsonb, 2, 'ICU therapeutic techniques include manual hyperinflation, hyperoxygenation and airway clearance. Jogging is not appropriate for the critically ill.', 'Rehabilitation & Mobilization', '🏃'),
(142, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Manual hyperinflation is carried out using:', '["Water''s circuit or Ambu bag", "Ambu bag only", "Suction machine", "None of the above"]'::jsonb, 0, 'Manual hyperinflation uses a Water''s (Mapleson C) circuit or a self-inflating (Ambu) bag.', 'Rehabilitation & Mobilization', '🏃'),
(143, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Which of the following is the most common cause of COPD?', '["Cigar and pipe smoking", "Cigarette smoking", "Smoking marijuana", "Working in an environment polluted by chemical fumes or dust"]'::jsonb, 1, 'Cigarette smoking causes most COPD. Occupational dust, fumes and biomass smoke also contribute.', 'Respiratory', '🫁'),
(144, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Under normal conditions, intrapleural pressure is:', '["Always positive", "Negative during inhalation and positive during exhalation", "Positive during inhalation and negative during exhalation", "Always negative"]'::jsonb, 3, 'Normal intrapleural pressure is sub-atmospheric (negative) throughout quiet breathing, about −5 cmH2O at rest and more negative on inspiration. This keeps the lungs expanded.', 'Respiratory', '🫁'),
(145, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'The maximum score on the Glasgow Coma Scale is:', '["3", "12", "14", "15"]'::jsonb, 3, 'GCS ranges from 3 (deep coma) to 15 (fully alert): eyes 4 + verbal 5 + motor 6.', 'Neurology', '🧠'),
(146, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Which is a characteristic cardiac change in advanced emphysema?', '["Enlargement of the right side of the heart", "Enlargement of the left side of the heart", "Decreased pulmonary artery pressure", "Enlarged aorta"]'::jsonb, 0, 'Chronic hypoxic pulmonary vasoconstriction in emphysema/COPD raises pulmonary pressure and enlarges the right heart (cor pulmonale).', 'Respiratory', '🫁'),
(147, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Hypothermia is classified as a core body temperature below ___ °F.', '["100", "98.6", "95", "105"]'::jsonb, 2, 'Hypothermia is a core temperature below 35°C (95°F).', 'Mixed Revision', '📚'),
(148, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'A patient with an opening in the chest wall (e.g. from a gunshot or stab wound) resulting in a "sucking chest wound" has:', '["An open pneumothorax", "A closed pneumothorax", "A haemothorax", "A pleural effusion"]'::jsonb, 0, 'A penetrating chest wall defect that lets air move in and out ("sucking chest wound") is an open pneumothorax. Cover it with a three-sided occlusive dressing.', 'Respiratory', '🫁'),
(149, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Coma (head injury) is classified as severe when the Glasgow Coma Scale is:', '["≤8", "≤10", "≤12", "≤14"]'::jsonb, 0, 'GCS ≤8 means severe brain injury/coma, and usually that the airway needs protecting (intubation).', 'Neurology', '🧠'),
(150, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Which is a symptom of hypothermia?', '["Shivering", "Shaking", "Confusion", "All of the above"]'::jsonb, 3, 'Hypothermia causes shivering, shaking, then confusion, drowsiness and arrhythmias as it worsens.', 'Mixed Revision', '📚'),
(151, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'During the early stages of hypothermia, heart rate will:', '["Increase", "Decrease", "Stay the same", "Stop"]'::jsonb, 0, 'In mild (early) hypothermia, catecholamine release causes tachycardia and shivering. Bradycardia follows as cooling continues.', 'Mixed Revision', '📚'),
(152, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Which investigation confirms the diagnosis of COPD?', '["Spirometry", "ECG", "Chest X-ray", "Full blood count"]'::jsonb, 0, 'Spirometry confirms COPD: a post-bronchodilator FEV1/FVC below 0.70 shows persistent airflow obstruction.', 'Respiratory', '🫁'),
(153, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'The general adaptation syndrome of stress includes all of the following EXCEPT:', '["An alarm reaction (fight-or-flight)", "A resistance phase", "A period of fast recovery", "A period of exhaustion"]'::jsonb, 2, 'Selye''s general adaptation syndrome has three stages: alarm, resistance and exhaustion. There is no "fast recovery" stage.', 'Mixed Revision', '📚'),
(154, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Physical signs of the alarm stage of stress include the following EXCEPT:', '["Dilated pupils", "Tachycardia", "Hypoventilation", "Trembling"]'::jsonb, 2, 'The alarm (sympathetic) stage causes dilated pupils, tachycardia, rapid breathing (hyperventilation, not hypoventilation) and trembling.', 'Mixed Revision', '📚'),
(155, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'All of the following could be stressors for patients in the ICU EXCEPT:', '["Loss of privacy", "Artificial lighting for only 2 hours per day", "Constant noise from monitors and life-support machines", "Lack of meaningful stimuli such as a family member''s touch"]'::jsonb, 1, 'ICU stressors include loss of privacy, constant noise, round-the-clock (24-hour) artificial lighting and lack of meaningful touch. Two hours of light a day is not a stressor.', 'Mixed Revision', '📚'),
(156, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'When assessing a client at risk of pressure ulcers, the nurse should do the following EXCEPT:', '["Assess skin condition at least twice a day", "Inspect each pressure site", "Palpate the skin for increased coldness", "Inspect for dry skin, moist skin and breaks in the skin"]'::jsonb, 2, 'Pressure-ulcer assessment checks the skin at least twice daily, inspects every pressure site, and palpates for warmth (not coldness), induration and moisture.', 'Rehabilitation & Mobilization', '🏃'),
(157, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'All of the following are risk factors for pressure ulcers EXCEPT:', '["Friction", "Shear", "Impaired sensory perception", "Faecal and urinary continence"]'::jsonb, 3, 'Friction, shear, impaired sensory perception and faecal or urinary INcontinence are pressure-ulcer risk factors. Continence is not.', 'Rehabilitation & Mobilization', '🏃'),
(158, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Which confirmed value meets the diagnostic threshold for diabetes?', '["Fasting blood glucose ≥110 mg/dL", "Random glucose >160 mg/dL", "2-hour OGTT glucose ≥140 mg/dL", "Fasting blood glucose ≥126 mg/dL"]'::jsonb, 3, 'Diabetes is diagnosed by fasting glucose ≥126 mg/dL (7.0 mmol/L), random glucose ≥200 mg/dL with symptoms, 2-h OGTT ≥200 mg/dL, or HbA1c ≥6.5%.', 'GI, Endocrine & Metabolic', '🍽️'),
(159, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Which of the following statements is correct?', '["Insulin suppresses the activity of glycogen synthase", "Insulin mediates glucose uptake in the brain", "Prediabetes is a condition with an increased risk of future type 2 diabetes", "The post-meal rise in insulin is reduced in type 1 but not in type 2 diabetes"]'::jsonb, 2, 'Prediabetes (impaired fasting glucose or impaired glucose tolerance) predicts later type 2 diabetes. Insulin activates glycogen synthase, and brain glucose uptake does not depend on insulin.', 'GI, Endocrine & Metabolic', '🍽️'),
(160, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Risk factors for type 2 diabetes mellitus include:', '["Family history", "Being overweight", "Physical inactivity", "All of the above"]'::jsonb, 3, 'Family history, overweight/obesity, physical inactivity and age are major type 2 diabetes risk factors.', 'GI, Endocrine & Metabolic', '🍽️'),
(161, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Which statement best describes a difference between type 1 and type 2 diabetes?', '["People with type 2 always need lower insulin doses because their diabetes is mild", "People with type 1 develop chronic complications rapidly", "Autoimmune factors are involved in type 1 but not type 2 diabetes", "People with type 1 can increase their own insulin by taking oral hypoglycaemics"]'::jsonb, 2, 'Type 1 diabetes is autoimmune beta-cell destruction. Type 2 involves insulin resistance with relative deficiency and no autoimmunity.', 'GI, Endocrine & Metabolic', '🍽️'),
(162, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'What is the first-line drug for a patient with type 2 diabetes and obesity?', '["Acarbose", "Metformin", "Sulphonylureas", "Insulin"]'::jsonb, 1, 'Metformin is first-line for type 2 diabetes, especially with obesity: it does not cause weight gain or hypoglycaemia.', 'GI, Endocrine & Metabolic', '🍽️'),
(163, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'In which type of burn does healing NOT occur without scarring?', '["First-degree burns", "Superficial second-degree burns", "Third-degree burns", "None of these"]'::jsonb, 2, 'First- and superficial second-degree burns heal by regeneration without scarring. Third-degree (full-thickness) burns destroy the dermis and need grafting, leaving scars.', 'Burns & Trauma', '🔥'),
(164, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Pain is greater in first- and second-degree burns because:', '["The brain releases high levels of prostaglandins", "Nerve endings are injured and exposed", "Sebaceous glands are destroyed", "Perspiration increases"]'::jsonb, 1, 'Superficial and partial-thickness burns are very painful because nerve endings are injured and exposed. Full-thickness burns destroy the nerve endings.', 'Burns & Trauma', '🔥'),
(165, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Chemical burns are caused by:', '["Heat", "Solids", "Acids and alkalis", "Nitrogen gas"]'::jsonb, 2, 'Chemical burns come from acids or alkalis (and some other chemicals). Irrigate with copious water.', 'Burns & Trauma', '🔥'),
(166, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'ARDS is an abbreviation for:', '["Advanced respiratory disease signs", "Acute renal disease syndrome", "Acute respiratory depression syndrome", "Acute respiratory distress syndrome"]'::jsonb, 3, 'ARDS is Acute Respiratory Distress Syndrome: acute non-cardiogenic pulmonary oedema with refractory hypoxaemia.', 'Respiratory', '🫁'),
(167, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'All of the following are synonyms for (or terms linked to) ARDS EXCEPT:', '["Shock lung syndrome", "Diffuse alveolar damage", "Acute lung injury", "Acute liver injury"]'::jsonb, 3, 'Other names for ARDS are shock lung, diffuse alveolar damage (its histology) and, in milder form, acute lung injury. "Acute liver injury" is unrelated.', 'Respiratory', '🫁'),
(168, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'ARDS results from damage to all of the following EXCEPT:', '["Capillary endothelium", "Type I pneumocytes", "Type II pneumocytes", "Type III pneumocytes"]'::jsonb, 3, 'ARDS damages the capillary endothelium and the type I and type II pneumocytes. There are no "type III pneumocytes".', 'Respiratory', '🫁'),
(169, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'ARDS may be caused by the following EXCEPT:', '["Trauma", "Multiple blood transfusions", "Severe burns", "Smoking"]'::jsonb, 3, 'Common ARDS triggers are sepsis, pneumonia, trauma, massive transfusion, burns, pancreatitis and aspiration. Smoking is not a direct acute cause.', 'Respiratory', '🫁'),
(170, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'The proportion of blunt chest injuries that require operative intervention is:', '["15–30%", "30–40%", "Less than 10%", "100%"]'::jsonb, 2, 'Fewer than 10% of blunt chest injuries need surgery. Most are managed with chest drains, analgesia and respiratory support.', 'Burns & Trauma', '🔥'),
(171, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Chest injury accounts for what proportion of all trauma deaths?', '["10%", "20%", "25%", "100%"]'::jsonb, 2, 'Chest trauma causes about 25% of all trauma deaths (ATLS).', 'Burns & Trauma', '🔥'),
(172, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'The contents of the thoracic cavity include the following EXCEPT:', '["Lungs and pleura", "Tracheobronchial tree", "Cervical oesophagus", "Heart"]'::jsonb, 2, 'The thoracic cavity holds the lungs and pleura, tracheobronchial tree, heart, great vessels and thoracic oesophagus. The cervical oesophagus is in the neck.', 'Anatomy & Physiology', '🧬'),
(173, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Tissue hypoxia and metabolic acidosis in chest trauma may result from the following EXCEPT:', '["Decreased cardiac output", "Pulmonary shunting", "Cardiac tamponade", "Fracture of a thoracic vertebra"]'::jsonb, 3, 'Chest trauma causes hypoxia and acidosis through low cardiac output, shunting, tamponade and hypovolaemia. An isolated thoracic vertebral fracture does not.', 'Burns & Trauma', '🔥'),
(174, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'The following chest injuries are an IMMEDIATE threat to life EXCEPT:', '["Tension pneumothorax", "Open pneumothorax", "Massive haemothorax", "Pulmonary contusion"]'::jsonb, 3, 'Immediately life-threatening chest injuries (primary survey) include tension pneumothorax, open pneumothorax, massive haemothorax, flail chest and tamponade. Pulmonary contusion is potentially life-threatening and found in the secondary survey.', 'Burns & Trauma', '🔥'),
(175, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Causes of traumatic circulatory arrest include the following EXCEPT:', '["Severe hypoxia", "Profound hypovolaemia", "Cardiac herniation", "Simple rib fracture"]'::jsonb, 3, 'Traumatic cardiac arrest is caused by hypoxia, hypovolaemia, tension pneumothorax, tamponade and cardiac injury. A simple rib fracture does not cause arrest.', 'Burns & Trauma', '🔥'),
(176, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'The commonest side for traumatic diaphragmatic herniation is the:', '["Right side", "Left side", "Lateral side", "Central side"]'::jsonb, 1, 'Traumatic diaphragmatic rupture is commoner on the left; the liver protects the right side.', 'Burns & Trauma', '🔥'),
(177, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'The following are indications for tube thoracostomy EXCEPT:', '["Simple rib fracture", "Pneumothorax", "Haemothorax", "Haemopneumothorax"]'::jsonb, 0, 'Tube thoracostomy (chest drain) treats pneumothorax, haemothorax and haemopneumothorax. A simple rib fracture alone is not an indication.', 'Burns & Trauma', '🔥'),
(178, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'The following are adjuncts to the primary survey EXCEPT:', '["CT scan", "Chest X-ray", "Pelvic X-ray", "FAST"]'::jsonb, 0, 'Primary-survey adjuncts are chest X-ray, pelvic X-ray, FAST, ECG, ABG and catheters. CT belongs to the secondary survey, once the patient is stable.', 'Burns & Trauma', '🔥'),
(179, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'In elderly trauma patients, certain drugs may interfere with resuscitation. These include the following EXCEPT:', '["Beta blockers", "Antibiotics", "Anticoagulants", "Diuretics"]'::jsonb, 1, 'Beta blockers (mask tachycardia), anticoagulants (worsen bleeding) and diuretics (volume depletion) all complicate resuscitation in older people. Antibiotics generally do not.', 'Burns & Trauma', '🔥'),
(180, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'The following are manifestations of SIRS EXCEPT:', '["Temperature >38 °C", "Temperature <36 °C", "Heart rate >90 beats/min", "Systolic blood pressure >90 mmHg"]'::jsonb, 3, 'SIRS criteria: temperature >38 or <36 °C, HR >90, RR >20 (or PaCO2 <32), WBC >12 or <4 ×10⁹/L. Systolic BP >90 is normal.', 'Shock & Haemorrhage', '⚡'),
(181, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Perfusion abnormalities associated with septic shock include the following EXCEPT:', '["Lactic acidosis", "Oliguria", "Altered mental status", "Cough"]'::jsonb, 3, 'Hypoperfusion in septic shock shows as lactic acidosis, oliguria and altered mental status. Cough is not a perfusion sign.', 'Shock & Haemorrhage', '⚡'),
(182, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'The following are cytokines EXCEPT:', '["Lysosomes", "Tumour necrosis factor (TNF)", "Interleukins", "Interferons"]'::jsonb, 0, 'Cytokines are signalling proteins such as TNF, interleukins and interferons. Lysosomes are cell organelles.', 'Infection Prevention', '🦠'),
(183, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Early (warm) septic shock differs from hypovolaemic shock by all of the following EXCEPT:', '["Warm extremities", "Flushed skin", "Well-perfused extremities", "Tachycardia"]'::jsonb, 3, 'Early ("warm") septic shock gives warm, flushed, well-perfused extremities, unlike the cold clammy skin of hypovolaemia. Tachycardia occurs in both.', 'Shock & Haemorrhage', '⚡'),
(184, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Causes of the apparent decrease in blood volume in septic shock include the following EXCEPT:', '["Blood loss", "Venous pooling", "Interstitial \"third-space\" loss", "Insensible loss"]'::jsonb, 0, 'In sepsis the effective blood volume falls from venous pooling (vasodilation), capillary leak ("third-space" loss) and insensible losses, not from actual blood loss.', 'Shock & Haemorrhage', '⚡'),
(185, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'All are clinical features of pulmonary oedema EXCEPT:', '["Cough with pink, frothy sputum", "Extreme dyspnoea", "Inspiratory and expiratory wheezing", "Syncope"]'::jsonb, 3, 'Pulmonary oedema causes severe dyspnoea, pink frothy sputum, crackles and wheeze ("cardiac asthma"). Syncope is not typical.', 'Cardiovascular', '🫀'),
(186, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Drug therapy for pulmonary oedema includes the following EXCEPT:', '["Haematinics", "Diuretics", "Morphine", "Digitalis"]'::jsonb, 0, 'Pulmonary oedema drugs include diuretics (furosemide), nitrates, morphine and sometimes digoxin or inotropes. Haematinics (iron) have no role.', 'Cardiovascular', '🫀'),
(187, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'A mass that travels through the blood vessels (veins or arteries) and lodges elsewhere is called:', '["An embolus", "A thromboembolin", "A thrombus", "An amniotic embolism"]'::jsonb, 0, 'An embolus is any mass (clot, fat, air, amniotic fluid) carried in the bloodstream that lodges in a vessel. A thrombus is a clot fixed at the site where it formed.', 'Cardiovascular', '🫀'),
(188, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'The three factors that predispose to vascular thrombosis (Virchow''s triad) are:', '["Bed rest, immobility and surgery", "Reduced blood flow, damage to the vessel wall and increased blood coagulability", "Obesity, oral contraceptives and oestrogen replacement", "Trauma, burns and previous venous thrombosis"]'::jsonb, 1, 'Virchow''s triad: venous stasis (reduced flow), vessel wall injury and hypercoagulability.', 'Cardiovascular', '🫀'),
(189, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'The commonest source of pulmonary emboli is:', '["Drugs", "Oxygen", "Deep veins of the lower extremities", "Carbon dioxide"]'::jsonb, 2, 'Most pulmonary emboli come from deep vein thrombosis of the legs and pelvis.', 'Cardiovascular', '🫀'),
(190, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Which of the following is a thrombolytic agent?', '["Streptokinase", "Heparin", "Clexane (enoxaparin)", "Warfarin sodium"]'::jsonb, 0, 'Streptokinase (like alteplase) is a thrombolytic that dissolves clots. Heparin, enoxaparin (Clexane) and warfarin are anticoagulants that only stop clots growing.', 'ICU Pharmacology', '💊'),
(191, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Which nursing measure helps prevent deep vein thrombosis?', '["Early mobilisation", "Prolonged bed rest", "Restricting oral fluids", "Placing pillows under the knees"]'::jsonb, 0, 'Early mobilisation, leg exercises, compression stockings and prophylactic anticoagulation prevent DVT.', 'Cardiovascular', '🫀'),
(192, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'In status asthmaticus, oxygen is given to keep the patient''s SpO2 at:', '["75%", "88%", "Greater than 92%", "Exactly 90%"]'::jsonb, 2, 'In acute severe asthma, give controlled oxygen to keep SpO2 about 92–98% (BTS target 94–98%). Hypoxaemia kills.', 'Respiratory', '🫁'),
(193, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Respiratory failure is defined as:', '["PaO2 >60 mmHg or PaCO2 <50 mmHg", "PaO2 <60 mmHg and/or PaCO2 >50 mmHg", "PaO2 exactly 60 mmHg or PaCO2 exactly 50 mmHg", "PaO2 >60 mmHg and PaCO2 >60 mmHg"]'::jsonb, 1, 'Respiratory failure is PaO2 <60 mmHg (8 kPa) on room air, with or without PaCO2 >50 mmHg (6.5 kPa).', 'Respiratory', '🫁'),
(194, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Type I respiratory failure is also known as:', '["Ventilatory failure", "Hypercapnic failure", "Hypoxaemic failure", "Septicaemic failure"]'::jsonb, 2, 'Type I respiratory failure is hypoxaemic (low PaO2, normal or low PaCO2). Type II is hypercapnic (ventilatory) failure.', 'Respiratory', '🫁'),
(195, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Based on onset, respiratory failure can be classified as:', '["Acute, chronic, and acute-on-chronic", "Mild, moderate and severe", "Sudden, weak and strong", "Mild, acute and chronic"]'::jsonb, 0, 'By onset, respiratory failure is acute, chronic, or acute-on-chronic.', 'Respiratory', '🫁'),
(196, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Accumulation of air within the pleural space is called:', '["Haemothorax", "Haemopneumothorax", "Tension pneumothorax", "Pneumothorax"]'::jsonb, 3, 'Pneumothorax is air in the pleural space. Blood is a haemothorax.', 'Respiratory', '🫁'),
(197, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Which of the following are types of pneumothorax?', '["Spontaneous", "Traumatic", "Tension", "All of the above"]'::jsonb, 3, 'Pneumothorax may be spontaneous (primary or secondary), traumatic (including iatrogenic) or tension.', 'Respiratory', '🫁'),
(198, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Pulmonary hypertension is classically defined as a mean pulmonary arterial pressure of:', '["Greater than 30 mmHg on exercise only", "Less than 25 mmHg at rest", "Greater than 25 mmHg at rest", "Less than 25 mmHg at rest or 40 mmHg on exercise"]'::jsonb, 2, 'Pulmonary hypertension is classically mean pulmonary arterial pressure >25 mmHg at rest (lowered to >20 mmHg in 2022 guidelines).', 'Cardiovascular', '🫀'),
(199, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'The onset of delirium is usually rapid, within:', '["30 minutes to 1 hour", "Hours to a few days", "Weeks to months", "Months to years"]'::jsonb, 1, 'Delirium starts acutely, over hours to a few days, and fluctuates. Dementia develops over months to years.', 'Neurology', '🧠'),
(200, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'The validated clinical tools used in ICU for detecting delirium are:', '["RASS and GCS", "CAM-ICU and ICDSC", "MMSE and AVPU", "Braden and Waterlow scales"]'::jsonb, 1, 'CAM-ICU and the ICDSC (Intensive Care Delirium Screening Checklist) are the validated ICU delirium tools. RASS measures sedation level.', 'Neurology', '🧠'),
(201, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'An ICDSC (Intensive Care Delirium Screening Checklist) score of ___ or more indicates delirium.', '["4", "2", "8", "1"]'::jsonb, 0, 'On the 8-point ICDSC, a score of 4 or more indicates delirium.', 'Neurology', '🧠'),
(202, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Non-pharmacological management of delirium focuses on risk factors such as:', '["Dehydration, constipation and sleep deprivation", "Reorientation, clear communication and immobility", "Pain control, nutrition and early removal of catheters", "All of the above"]'::jsonb, 3, 'Non-drug delirium prevention targets dehydration, constipation, sleep loss, immobility, pain, poor nutrition and lines/catheters, with reorientation and clear communication.', 'Neurology', '🧠'),
(203, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'How many motor subtypes of delirium are there?', '["6", "2", "7", "3"]'::jsonb, 3, 'Delirium has three motor subtypes: hyperactive, hypoactive and mixed.', 'Neurology', '🧠'),
(204, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'International guidelines recommend that ICU patients are screened for delirium:', '["Every hour", "Twice a week", "At least daily (every shift)", "Once a week"]'::jsonb, 2, 'Guidelines (PADIS) advise screening every ICU patient for delirium at least daily, ideally every shift, with CAM-ICU or ICDSC.', 'Neurology', '🧠'),
(205, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Which statement about delirium and dementia is TRUE?', '["Delirium is usually reversible, while dementia is progressive", "Delirium is never reversible", "Dementia has an acute onset over hours", "Delirium and dementia are the same condition"]'::jsonb, 0, 'Delirium is acute, fluctuating and usually reversible once the cause is treated. Dementia is chronic and progressive.', 'Neurology', '🧠'),
(206, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'What is the full meaning of TEN?', '["Toxic epidermal necrosis", "Toxic epidermis necrosis syndrome", "Toxic epidermal necrolysis", "Total epidermal neuritis"]'::jsonb, 2, 'TEN is toxic epidermal necrolysis, a severe drug-induced mucocutaneous reaction with widespread epidermal detachment.', 'Burns & Trauma', '🔥'),
(207, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'SJS and TEN involve the same process. They are distinguished by the extent of skin detachment:', '["SJS <10% of body surface; TEN >30% (10–30% is overlap)", "SJS >30%; TEN <10%", "SJS and TEN always involve exactly 50%", "There is no difference in extent"]'::jsonb, 0, 'SJS and TEN are one disease spectrum: SJS <10% BSA detachment, SJS/TEN overlap 10–30%, TEN >30%.', 'Burns & Trauma', '🔥'),
(208, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'The following increase the risk of SJS/TEN EXCEPT:', '["Chronic alcoholism", "HIV infection", "Cancer", "Family history of SJS/TEN"]'::jsonb, 0, 'HIV infection, cancer, genetic factors (HLA types, family history) and certain drugs raise the risk of SJS/TEN. Chronic alcoholism is not a recognised risk factor.', 'Burns & Trauma', '🔥'),
(209, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Early and continuous enteral nutrition in TEN:', '["Reduces the risk of stress ulcers", "Reduces bacterial translocation and enterogenic infection", "Allows earlier removal of venous lines", "All of the above"]'::jsonb, 3, 'Early continuous enteral nutrition protects the gut: it reduces stress ulcers and bacterial translocation and lets lines be removed sooner.', 'Burns & Trauma', '🔥'),
(210, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'TEN patients are nursed in a heated environment to reduce heat loss and enhance:', '["Epithelialisation", "Re-vitalisation", "Re-epithelialisation", "Vitalisation"]'::jsonb, 2, 'A warm environment (about 30–32 °C) cuts heat loss from denuded skin and supports re-epithelialisation, as in burns.', 'Burns & Trauma', '🔥'),
(211, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Hydroxyzine may be used in TEN to relieve intense:', '["Pain", "Pruritus", "Bleeding", "Secretions"]'::jsonb, 1, 'Hydroxyzine, a sedating antihistamine, relieves the intense itch (pruritus) of healing TEN skin.', 'Burns & Trauma', '🔥'),
(212, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Other causes of pulmonary oedema include:', '["Circulatory overload", "Drug hypersensitivity, allergy or poisoning", "Other heart disease leading to left ventricular failure", "All of the above"]'::jsonb, 3, 'Pulmonary oedema can also follow circulatory overload, drug reactions, allergy or poisoning, and other heart disease causing LV failure.', 'Cardiovascular', '🫀'),
(213, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Which of the following is NOT routinely tested as a transfusion-transmissible infection in the blood bank?', '["Hepatitis A", "Malaria", "Hepatitis B", "HIV"]'::jsonb, 0, 'Donor blood is screened for HIV, hepatitis B, hepatitis C and syphilis (and malaria in endemic areas). Hepatitis A is not routinely tested.', 'Laboratory Sciences & Haematology', '🔬'),
(214, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'The most common anticoagulant used in blood bank donor bags is:', '["EDTA", "Heparin", "Tri-sodium citrate", "Double oxalate"]'::jsonb, 2, 'Citrate (tri-sodium citrate, as in CPDA-1) is the blood-bank anticoagulant. It binds calcium.', 'Laboratory Sciences & Haematology', '🔬'),
(215, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Advantages of blood donation to the donor include:', '["Free health check-up", "Reduced body iron stores", "Possibly reduced risk of heart disease", "All of the above"]'::jsonb, 3, 'Donors get a free health screen and lower iron stores, which may reduce cardiovascular risk.', 'Laboratory Sciences & Haematology', '🔬'),
(216, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Which person should be deferred if the event happened within the previous 24 hours?', '["A person who drank alcohol", "A person who had a cholesterol check", "A person who ate breakfast", "A person who slept 8 hours"]'::jsonb, 0, 'Anyone who has drunk alcohol in the previous 24 hours should not donate blood.', 'Laboratory Sciences & Haematology', '🔬'),
(217, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Blood for grouping and cross-matching should be collected before giving which plasma expander?', '["Hydroxyethyl starch", "Dextran", "Mannitol", "Haemaccel"]'::jsonb, 1, 'Dextran coats red cells and causes rouleaux, which interferes with grouping and cross-matching. Take the cross-match sample before giving it.', 'Laboratory Sciences & Haematology', '🔬'),
(218, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Febrile non-haemolytic transfusion reaction (FNHTR) occurs due to:', '["Alloimmunisation to red cell antigens", "Antibodies against donor leucocytes and HLA antigens", "IgE-mediated allergy", "Anaphylaxis from IgA deficiency"]'::jsonb, 1, 'FNHTR is caused by recipient antibodies against donor leucocyte/HLA antigens and cytokines in stored blood. Leucodepletion reduces it.', 'Laboratory Sciences & Haematology', '🔬'),
(219, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Massive blood transfusion is defined as:', '["350 mL in 5 minutes", "500 mL in 5 minutes", "1 litre in 5 minutes", "Replacement of the patient''s total blood volume within 24 hours"]'::jsonb, 3, 'Massive transfusion is replacing one total blood volume within 24 hours, or about 10 units of red cells.', 'Laboratory Sciences & Haematology', '🔬'),
(220, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'One unit of blood raises the haemoglobin concentration by about:', '["0.1 g/dL", "1 g/dL", "2 g/dL", "2.2 g/dL"]'::jsonb, 1, 'One unit of whole blood or packed red cells raises Hb by about 1 g/dL in an average adult.', 'Laboratory Sciences & Haematology', '🔬'),
(221, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Which pH finding would be consistent with respiratory alkalosis?', '["7.49", "7.35", "7.45", "7.29"]'::jsonb, 0, 'Respiratory alkalosis comes from hyperventilation (low PaCO2), so the pH is above 7.45.', 'ABG & Electrolytes', '🩸'),
(222, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'After a chest injury, ABGs show pH 7.26, PaCO2 52 mmHg, HCO3 25 mmol/L. This is:', '["Metabolic acidosis", "Respiratory acidosis", "Metabolic alkalosis", "Respiratory alkalosis"]'::jsonb, 1, 'Low pH (acidosis), high PaCO2 (respiratory cause) and normal HCO3 (not yet compensated): acute respiratory acidosis.', 'ABG & Electrolytes', '🩸'),
(223, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'A client with asthma is taking a theophylline bronchodilator. Which breakfast item should the nurse discuss with the client?', '["Coffee", "Eggs", "Toast", "Bananas"]'::jsonb, 0, 'Caffeine, like theophylline, is a methylxanthine. Coffee can add to theophylline''s stimulant and toxic effects (tachycardia, tremor).', 'ICU Pharmacology', '💊'),
(224, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'An emergency tracheostomy involves:', '["A tube passed through the mouth and larynx", "A tube passed through the nose into the trachea", "A surgical incision into the trachea", "A puncture through the cricothyroid cartilage"]'::jsonb, 2, 'A tracheostomy is a surgical opening (incision) into the trachea. A cricothyroidotomy goes through the cricothyroid membrane.', 'Respiratory', '🫁'),
(225, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'During evaluation you find two client goals have not been met. What is the best action?', '["Stop working on these goals, as evaluation is the last step", "Assess only the client''s motivation", "Reassess the problem, review the care plan and revise as needed", "Discharge the client"]'::jsonb, 2, 'When goals are not met, the nurse reassesses, finds out why, and revises the care plan. The nursing process is cyclical.', 'Research & Nursing Process', '📊'),
(226, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'All of the following are levels of impaired consciousness EXCEPT:', '["Alertness", "Stupor", "Delirium", "Coma"]'::jsonb, 0, 'Altered consciousness ranges from confusion and delirium through stupor to coma. Alertness is normal consciousness.', 'Neurology', '🧠'),
(227, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'The following are causes of respiratory acidosis EXCEPT:', '["COPD", "Severe asthma", "Hyperventilation", "Head injury"]'::jsonb, 2, 'Respiratory acidosis comes from hypoventilation (COPD, severe asthma, head injury, sedatives). Hyperventilation causes respiratory alkalosis.', 'ABG & Electrolytes', '🩸'),
(228, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Tachycardia (HR >100 bpm) can be caused by the following EXCEPT:', '["Hypothermia", "Hyperthermia", "Stress", "Anxiety"]'::jsonb, 0, 'Tachycardia is caused by fever, stress, anxiety, pain, hypovolaemia and hypoxia. Hypothermia causes bradycardia.', 'Cardiovascular', '🫀'),
(229, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Which of the following cells are in almost constant mitosis?', '["Nerve cells", "Gastric epithelial cells", "Skeletal muscle cells", "Renal cells"]'::jsonb, 1, 'Epithelial lining cells, such as gastric and intestinal mucosa, renew constantly by mitosis. Neurons and cardiac and skeletal muscle rarely divide.', 'Anatomy & Physiology', '🧬'),
(230, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Neonatal jaundice is usually clinically visible when serum bilirubin exceeds:', '["5 mg/dL", "15 mg/dL", "25 mg/dL", "50 mg/dL"]'::jsonb, 0, 'Jaundice becomes visible in neonates at serum bilirubin above about 5 mg/dL (85 µmol/L).', 'Obstetric & Neonatal', '🤱'),
(231, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'A neonate is an infant in the first:', '["20 days of life", "28 days of life", "30 days of life", "38 days of life"]'::jsonb, 1, 'The neonatal period is the first 28 days of life.', 'Obstetric & Neonatal', '🤱'),
(232, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'The most widely used effective treatment for neonatal jaundice is:', '["Blood transfusion", "Antibiotics", "Phototherapy", "Liver transplant"]'::jsonb, 2, 'Phototherapy is the most widely used, effective treatment for neonatal jaundice. Exchange transfusion is kept for severe or rapidly rising levels.', 'Obstetric & Neonatal', '🤱'),
(233, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Ipratropium bromide is used in the management of:', '["Acute gastroenteritis", "Acute peptic ulcer disease", "Acute bronchopneumonia", "Acute asthmatic attack"]'::jsonb, 3, 'Ipratropium bromide is an inhaled anticholinergic bronchodilator, added to salbutamol in acute severe asthma and used in COPD.', 'ICU Pharmacology', '💊'),
(234, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'The environmental theory of nursing ("cleanliness is next to godliness") was put forward by:', '["Abraham Maslow", "Isaac Newton", "Florence Nightingale", "Virginia Henderson"]'::jsonb, 2, 'Florence Nightingale''s environmental theory stresses cleanliness, ventilation, light, warmth and quiet for healing.', 'Research & Nursing Process', '📊'),
(235, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Brainstem death is diagnosed by the following signs EXCEPT:', '["Raised blood pressure", "Absent pupillary reaction", "Absent motor response to pain in the cranial nerve distribution", "Absent corneal reflex"]'::jsonb, 0, 'Brainstem death testing shows absent pupillary, corneal, gag/cough, oculovestibular and pain responses and apnoea. Raised BP is not a criterion.', 'Neurology', '🧠'),
(236, 'UMTH Pre-Professional Paper II, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper II, August 2023 (uploaded)', 'Transitional epithelium of the urinary bladder is best described as:', '["Changing from cuboidal to columnar", "A single, non-stratified layer", "Containing a special elastic substance", "Changing shape depending on bladder fullness"]'::jsonb, 3, 'Transitional epithelium (urothelium) is stratified and changes shape, from dome-shaped to flattened, as the bladder fills and stretches.', 'Anatomy & Physiology', '🧬'),
(237, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which of the following is NOT a high-risk factor for life-threatening injury in trauma?', '["GCS ≤13", "A fall of 2 m", "Two or more proximal long-bone fractures", "Age <5 or >55 years"]'::jsonb, 1, 'Field triage high-risk criteria include GCS ≤13, two or more proximal long-bone fractures, and age extremes. For falls, the threshold is over 6 m (20 ft) in adults; 2 m is not a high-risk height.', 'Burns & Trauma', '🔥'),
(238, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which of the following is NOT a standard mechanism-of-injury predictor of life-threatening trauma?', '["Estimated bleeding of more than 500 mL", "High-speed collision (>60 km/h)", "Rollover of the vehicle", "Prolonged extrication (>20–30 min)"]'::jsonb, 0, 'Mechanism-of-injury predictors include high-speed collision, vehicle rollover and prolonged extrication. A reported blood loss of "more than 500 mL" is not a standard triage predictor.', 'Burns & Trauma', '🔥'),
(239, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'A 25-year-old man has a stab wound to the left side of the neck. All of the following indicate a need for aggressive airway management EXCEPT:', '["Massive subcutaneous emphysema of the neck", "Trachea in the midline", "Expanding neck haematoma", "Stridor and hoarseness"]'::jsonb, 1, 'Massive subcutaneous emphysema, an expanding haematoma, stridor or tracheal deviation call for early definitive airway control. A midline trachea is reassuring.', 'Burns & Trauma', '🔥'),
(240, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'A 30-year-old man with a stab wound to the neck is alert but bleeding actively in the resuscitation bay. You should first:', '["Place two large-bore IV cannulae and give O-negative blood", "Apply direct pressure to the site", "Clamp the bleeding vessels blindly", "Locally explore the wound to find the bleeding point"]'::jsonb, 1, 'Control external haemorrhage from a neck wound with direct pressure. Never clamp blindly or probe the wound in the resuscitation bay; the patient needs surgical exploration.', 'Burns & Trauma', '🔥'),
(241, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Where are platelets formed?', '["In the kidneys", "In the blood vessels", "In the bone marrow", "In the liver"]'::jsonb, 2, 'Platelets come from megakaryocytes in the bone marrow.', 'Laboratory Sciences & Haematology', '🔬'),
(242, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which of the following is true of disseminated intravascular coagulation (DIC)?', '["It can cause both blood clots and bleeding", "It is an inherited disease", "It is contagious", "It is never associated with an underlying condition"]'::jsonb, 0, 'DIC causes widespread microthrombi and, by consuming platelets and clotting factors, bleeding. It is always secondary to an underlying condition.', 'Laboratory Sciences & Haematology', '🔬'),
(243, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Both clotting and bleeding occur in DIC because:', '["Bleeding uses up clotting factors faster than they are replaced", "The intrinsic pathway releases excess clotting factors", "Only clotting occurs in DIC", "Excess thrombin uses up clotting factors faster than they can be replaced"]'::jsonb, 3, 'Excess thrombin generation forms clots throughout the microcirculation and uses up clotting factors and platelets faster than they can be replaced, so bleeding follows.', 'Laboratory Sciences & Haematology', '🔬'),
(244, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'A client with full-thickness burns may be developing DIC. Which finding supports this?', '["Oozing of blood from the IV catheter site", "Sudden chest pain and frothy sputum", "Foul-smelling concentrated urine", "A reddened central line site"]'::jsonb, 0, 'Oozing from venepuncture or IV sites, petechiae and mucosal bleeding are classic signs of DIC.', 'Laboratory Sciences & Haematology', '🔬'),
(245, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which client is most at risk of developing DIC?', '["A 35-year-old pregnant client with placenta praevia", "A 42-year-old client with a pulmonary embolus", "A 60-year-old client on haemodialysis three times a week", "A 78-year-old client with septicaemia"]'::jsonb, 3, 'Sepsis, especially Gram-negative septicaemia, is the commonest cause of DIC.', 'Laboratory Sciences & Haematology', '🔬'),
(246, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which laboratory result would the nurse expect in DIC?', '["A decreased prothrombin time (PT)", "A low fibrinogen level", "An increased platelet count", "An increased white cell count"]'::jsonb, 1, 'DIC consumes fibrinogen and platelets, so fibrinogen is low, platelets are low, PT/aPTT are prolonged and D-dimer is raised.', 'Laboratory Sciences & Haematology', '🔬'),
(247, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which collaborative treatment would the nurse anticipate in DIC?', '["Oral anticoagulants", "Plasmapheresis", "Fresh frozen plasma", "Calculating intake and output only"]'::jsonb, 2, 'DIC is treated by treating the cause and replacing what has been consumed: FFP, platelets and cryoprecipitate.', 'Laboratory Sciences & Haematology', '🔬'),
(248, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'For "risk for fluid volume deficit related to bleeding" in DIC, which is an appropriate goal?', '["Clot formation will resolve in two days", "Dressing saturation will be documented", "The client will use lemon-glycerine swabs", "Urine output will be more than 30 mL per hour"]'::jsonb, 3, 'Adequate urine output (over 30 mL/h, or 0.5 mL/kg/h) is a measurable goal showing enough circulating volume.', 'Laboratory Sciences & Haematology', '🔬'),
(249, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'A patient with severe sepsis is suspected of having DIC. Which finding helps confirm this?', '["Petechiae", "Polyuria", "Clear breath sounds", "Bradycardia"]'::jsonb, 0, 'Petechiae, purpura and oozing show the consumption coagulopathy of DIC.', 'Laboratory Sciences & Haematology', '🔬'),
(250, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which client is at greatest risk of acute DIC?', '["Aortic aneurysm", "Gunshot wound to the distal arm", "Third-degree burns with septic shock", "Bacterial pneumonia on antibiotics"]'::jsonb, 2, 'Extensive burns with septic shock bring massive tissue factor release and endothelial injury, a very high risk for acute DIC.', 'Laboratory Sciences & Haematology', '🔬'),
(251, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which device is most useful for continuous, immediate monitoring of oxygen saturation because of its simplicity?', '["Pulse oximeter", "Ear oximeter", "Skin reflectance oximeter", "Intravascular oximeter"]'::jsonb, 0, 'The finger pulse oximeter is simple, non-invasive and gives continuous, immediate SpO2 readings.', 'Respiratory', '🫁'),
(252, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'During a blood transfusion, the patient''s RR is 24 and BP 90/60. The nurse''s priority is to:', '["Slow the infusion rate", "Flush the line with normal saline through the same giving set", "Stop the transfusion immediately", "Notify the doctor and continue"]'::jsonb, 2, 'Tachypnoea and hypotension during a transfusion suggest a serious reaction. Stop the transfusion at once, keep the line open with saline via new tubing, and call the doctor.', 'Laboratory Sciences & Haematology', '🔬'),
(253, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'All are true about perfusion index (PI) EXCEPT:', '["It is the ratio between the pulsatile and non-pulsatile components of the pulse oximetry signal", "It changes with local vasoconstriction and vasodilatation", "A low PI means the oxygen saturation is falling", "It can be used to choose the site for probe placement"]'::jsonb, 2, 'Perfusion index is pulsatile ÷ non-pulsatile signal. It shows local perfusion (falling with vasoconstriction) and helps choose the probe site. A low PI does not mean SpO2 is falling.', 'Respiratory', '🫁'),
(254, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'The equipment needed for nasotracheal intubation includes the following EXCEPT:', '["Magill forceps", "Laryngoscope", "Endotracheal tube", "Chromic 2/0 suture"]'::jsonb, 3, 'Nasotracheal intubation needs Magill forceps, a laryngoscope, an ETT and lubricant. Chromic 2/0 is a suture.', 'Anaesthesia & Perioperative Care', '💉'),
(255, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which statement about the unconscious patient is NOT correct?', '["Respiratory failure can cause unconsciousness", "Poor conscious levels are often accompanied by altered breathing patterns", "A saturation monitor provides all the information needed to assess respiratory function", "Airway protection is a nursing priority"]'::jsonb, 2, 'Monitors help, but full respiratory assessment of an unconscious patient needs clinical observation and ABGs. SpO2 says nothing about ventilation (CO2).', 'Neurology', '🧠'),
(256, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'What is the recommended maximum suction pressure for children?', '["130 mmHg", "140 mmHg", "120 mmHg", "150 mmHg"]'::jsonb, 2, 'Recommended suction pressures: adults 100–150 mmHg, children 80–120 mmHg, infants 60–100 mmHg.', 'Respiratory', '🫁'),
(257, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which wave is used to differentiate sinus rhythm from a supraventricular rhythm?', '["P wave", "QRS complex", "T wave", "R wave"]'::jsonb, 0, 'A P wave before each QRS separates sinus rhythm from supraventricular rhythms, where P waves are absent, abnormal or hidden.', 'Cardiovascular', '🫀'),
(258, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'After treatment for severe asthma, which finding indicates that the client''s respiratory status has worsened?', '["Diminished breath sounds", "Wheezing during inhalation", "Wheezing during exhalation", "Wheezing throughout the lung fields"]'::jsonb, 0, 'Diminished or absent breath sounds ("silent chest") in asthma mean very little air movement, a sign of deterioration.', 'Respiratory', '🫁'),
(259, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'During CPR, how does the nurse let the AED assess the client''s cardiac rhythm?', '["Hold paddles firmly against the chest", "Apply the adhesive pad electrodes and move away from the client", "Apply standard ECG leads and observe", "Connect to a transtelephonic monitor"]'::jsonb, 1, 'Apply the AED''s adhesive pads and stand clear so it can analyse the rhythm without movement artefact.', 'Cardiovascular', '🫀'),
(260, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which statement about pulse oximetry is most appropriate?', '["Carbon monoxide, nail varnish and IV dyes cannot interfere", "Saturation is estimated by transmission of light through a pulsatile vascular bed", "The light transmitted depends on only one factor", "The beep pitch only signals heart rate"]'::jsonb, 1, 'Oximeters estimate SaO2 from the differential absorption of red and infrared light through a pulsatile vascular bed. Carbon monoxide, nail varnish and dyes all interfere.', 'Respiratory', '🫁'),
(261, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'All are true of implanted (injection) ports EXCEPT:', '["The septum is designed to withstand hundreds of punctures", "They carry a reduced risk of catheter-related bloodstream infection", "They are suited to long-term intermittent access", "They are often inserted for urgent, short-term venous access"]'::jsonb, 3, 'Implanted ports are long-term devices placed electively. Their septum withstands many punctures and infection risk is lower. They are not for urgent short-term access.', 'Mixed Revision', '📚'),
(262, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which mode lets the patient breathe spontaneously, at their own rate and depth, between ventilator breaths?', '["Controlled mandatory ventilation", "Synchronised intermittent mandatory ventilation (SIMV)", "Assist-control mode", "Pressure-control mode"]'::jsonb, 1, 'SIMV gives mandatory breaths synchronised with the patient''s effort, and the patient breathes spontaneously between them.', 'Respiratory', '🫁'),
(263, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'A risk of high PEEP is:', '["Hypotension", "Hypertension", "Hyperthermia", "Hypothermia"]'::jsonb, 0, 'High PEEP raises intrathoracic pressure, reduces venous return and cardiac output, and causes hypotension. It also risks barotrauma.', 'Respiratory', '🫁'),
(264, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which is NOT a cause of a high airway pressure alarm?', '["Attempts to speak/cough", "Disconnected ventilator circuit", "Patient biting on the tube", "Secretions blocking the bronchi or tube"]'::jsonb, 1, 'High airway pressure comes from coughing or attempts to speak, biting the tube, secretions, bronchospasm or pneumothorax. A disconnected circuit causes a LOW pressure alarm.', 'Respiratory', '🫁'),
(265, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which is NOT a way to improve oxygenation on a ventilator?', '["Increasing FiO2", "Increasing PEEP", "Increasing inspiratory time", "Increasing respiratory rate"]'::jsonb, 3, 'Oxygenation improves with FiO2, PEEP and longer inspiratory time (mean airway pressure). Respiratory rate mainly controls CO2.', 'Respiratory', '🫁'),
(266, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Injury from overdistension of alveoli by excessive tidal volume is called:', '["Barotrauma", "Volutrauma", "Atelectotrauma", "Biotrauma"]'::jsonb, 1, 'Volutrauma is alveolar overdistension from excessive tidal volume. Barotrauma is from high pressure, atelectotrauma from repeated opening and collapse, and biotrauma is the inflammatory response.', 'Respiratory', '🫁'),
(267, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'A patient taking ibuprofen 400 mg twice daily for chronic back pain develops leg oedema. This is most likely caused by:', '["A decrease in renal function", "A low creatinine level", "An increased glomerular filtration rate", "An increase in plasma proteins"]'::jsonb, 0, 'NSAIDs block renal prostaglandins, reducing renal blood flow and GFR and causing sodium and water retention and oedema.', 'ICU Pharmacology', '💊'),
(268, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'When starting a patient on opioids, the recommended protocol for preventing constipation is to:', '["Add bulk fibre to the diet", "Give enemas as needed", "Increase fluids and exercise only", "Use a bowel stimulant and a stool softener"]'::jsonb, 3, 'Opioid-induced constipation is prevented with a stimulant laxative plus a stool softener from the start. Fibre alone may worsen it.', 'ICU Pharmacology', '💊'),
(269, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'The initial analgesic of choice for a patient with severe fracture pain (9/10) is:', '["IV paracetamol", "Rectal NSAID", "Oral codeine", "IV opiate"]'::jsonb, 3, 'Severe acute pain (9/10) needs a titrated IV opioid. Splinting and paracetamol are adjuncts.', 'ICU Pharmacology', '💊'),
(270, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which history requires caution when giving paracetamol (acetaminophen)?', '["Hepatitis B", "Occasional alcohol use", "Allergy to aspirin", "Gastric irritation with bleeding"]'::jsonb, 0, 'Paracetamol is metabolised by the liver and is hepatotoxic. Use it with caution in liver disease such as hepatitis B.', 'ICU Pharmacology', '💊'),
(271, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Before giving morphine 4 mg IV for incisional pain, the nurse should:', '["Assess the incision", "Clarify the order with the prescriber", "Assess the patient''s respiratory status", "Monitor the heart rate only"]'::jsonb, 2, 'Opioids depress respiration, so check respiratory rate and sedation before giving IV morphine.', 'ICU Pharmacology', '💊'),
(272, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'When preparing patient-controlled analgesia (PCA) for a postoperative patient, the nurse should:', '["Tell the patient to limit button presses", "Ask another nurse to double-check the setup before use", "Tell the patient to dose only when in severe pain", "Give dosing instructions to a cognitively impaired patient"]'::jsonb, 1, 'PCA pumps are high-alert. An independent double-check of the drug, concentration and settings prevents fatal programming errors.', 'ICU Pharmacology', '💊'),
(273, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which does NOT need to be excluded before testing for brain death?', '["Limb fractures", "Electrolyte imbalances", "Hypothermia", "Drug intoxication"]'::jsonb, 0, 'Before brainstem testing, exclude reversible causes: drugs and sedatives, hypothermia, and metabolic or electrolyte disturbances. Fractures do not affect the tests.', 'Neurology', '🧠'),
(274, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'What does the brainstem control?', '["Feelings", "Balance", "Emotions", "Breathing"]'::jsonb, 3, 'The brainstem (medulla and pons) contains the respiratory and cardiovascular centres and controls breathing.', 'Neurology', '🧠'),
(275, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'At what Glasgow Coma Scale score does an unconscious patient typically lose the ability to maintain the airway?', '["3", "8", "10", "15"]'::jsonb, 1, 'At GCS ≤8 airway reflexes are usually lost: "GCS 8, intubate".', 'Neurology', '🧠'),
(276, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which oxygen delivery device delivers the highest FiO2?', '["Nasal cannula", "Simple face mask", "Non-rebreathing face mask", "Venturi mask"]'::jsonb, 2, 'A non-rebreather (reservoir) mask gives the highest FiO2 of these devices, about 60–90%. Nasal cannula gives 24–44% and Venturi masks fixed 24–60%.', 'Respiratory', '🫁'),
(277, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'A middle-aged man collapses in the market. What is your first step?', '["Commence high-quality CPR", "Check airway patency", "Check the safety of the environment", "Call emergency services"]'::jsonb, 2, 'In the DRSABC approach, Danger (scene safety) comes first, then response, shouting for help, airway and breathing.', 'Cardiovascular', '🫀'),
(278, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which drug is NOT used to treat hypotension in ICU?', '["Dopamine", "Noradrenaline", "Hydralazine", "Dobutamine"]'::jsonb, 2, 'Dopamine, noradrenaline and dobutamine raise BP or cardiac output. Hydralazine is a vasodilator that lowers BP.', 'ICU Pharmacology', '💊'),
(279, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'The brainstem consists of:', '["Midbrain, hindbrain and forebrain", "Hindbrain, ventricle and pons", "Midbrain, pons and forebrain", "Midbrain, pons and medulla"]'::jsonb, 3, 'The brainstem consists of the midbrain, pons and medulla oblongata.', 'Anatomy & Physiology', '🧬'),
(280, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'The main function of the medulla oblongata is:', '["Parasympathetic control", "Endocrine control", "Renal control", "Cardiorespiratory control"]'::jsonb, 3, 'The medulla holds the cardiac, vasomotor and respiratory centres.', 'Anatomy & Physiology', '🧬'),
(281, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'The brain uses about what percentage of the body''s oxygen consumption?', '["5%", "10%", "15%", "20%"]'::jsonb, 3, 'The brain is about 2% of body weight but uses about 20% of the body''s oxygen.', 'Anatomy & Physiology', '🧬'),
(282, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'What proportion of resting cardiac output goes to the brain?', '["5%", "10%", "15%", "20%"]'::jsonb, 2, 'The brain receives about 15% of resting cardiac output (about 750 mL/min).', 'Anatomy & Physiology', '🧬'),
(283, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which is NOT an ancillary investigation for brainstem death?', '["Cerebral angiography", "Transcranial Doppler", "Electroencephalography", "Electromyography"]'::jsonb, 3, 'Ancillary tests for brain death are cerebral angiography, transcranial Doppler, EEG and perfusion scans. EMG tests muscle and nerve, not the brain.', 'Neurology', '🧠'),
(284, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'The pupillary light reflex tests cranial nerves:', '["I and II", "IV and V", "IV and VI", "II and III"]'::jsonb, 3, 'The pupillary light reflex has an afferent limb, the optic nerve (CN II), and an efferent limb, the oculomotor nerve (CN III).', 'Neurology', '🧠'),
(285, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which assessment covers past medical history, family history, reason for admission, current medications, psychosocial and complete physical assessment?', '["Initial assessment", "Focused assessment", "Emergency assessment", "Ongoing assessment"]'::jsonb, 0, 'The initial (admission) assessment is comprehensive: history, family history, medications, psychosocial and full physical assessment.', 'Research & Nursing Process', '📊'),
(286, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'At which step of the nursing process is the PES statement written?', '["Planning", "Implementation", "Assessment", "Diagnosis"]'::jsonb, 3, 'The PES format (Problem, Etiology, Signs/Symptoms) is used to write the nursing diagnosis.', 'Research & Nursing Process', '📊'),
(287, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'The self-care deficit theory was proposed by:', '["Virginia Henderson", "Betty Neuman", "Imogene King", "Dorothea Orem"]'::jsonb, 3, 'Dorothea Orem proposed the self-care deficit theory.', 'Research & Nursing Process', '📊'),
(288, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'When nurses help clients explore lifestyle habits and health behaviours to identify health risks, they are using which model?', '["Medical model", "Wellness model", "Psychosocial model", "Physiological model"]'::jsonb, 1, 'Wellness models look at lifestyle and health behaviours to identify risks and promote health.', 'Research & Nursing Process', '📊'),
(289, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which of the following is essential for developing critical thinking?', '["Blind faith", "Prejudice", "A questioning attitude", "None of these"]'::jsonb, 2, 'Critical thinking starts with a questioning, open-minded attitude rather than blind acceptance.', 'Research & Nursing Process', '📊'),
(290, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Critical thinking is mainly concerned with:', '["Opinion", "Egocentrism", "Argument and evidence", "Personal interest"]'::jsonb, 2, 'Critical thinking weighs arguments and evidence, not opinions or self-interest.', 'Research & Nursing Process', '📊'),
(291, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'A nurse repositions a patient who complains of difficulty breathing. This is which phase of the nursing process?', '["Implementation", "Assessment", "Evaluation", "Outcome identification"]'::jsonb, 0, 'Repositioning the patient to ease breathing is carrying out a nursing action: implementation.', 'Research & Nursing Process', '📊'),
(292, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'The first component of a nursing diagnosis statement is the:', '["Etiology", "Problem", "Signs and symptoms", "Related factors"]'::jsonb, 1, 'A nursing diagnosis statement begins with the Problem (diagnostic label), then the Etiology and the Signs/Symptoms (PES).', 'Research & Nursing Process', '📊'),
(293, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Cells of which layer of the epidermis are keratinised and dead?', '["Stratum spinosum", "Stratum basale", "Stratum corneum", "Stratum granulosum"]'::jsonb, 2, 'The stratum corneum, the outermost layer, is made of dead keratinised cells.', 'Anatomy & Physiology', '🧬'),
(294, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which term is least related to the others?', '["Subcutaneous fat", "Adipose tissue", "Reticular layer", "Hypodermis"]'::jsonb, 2, 'Subcutaneous fat, adipose tissue and the hypodermis all describe the layer beneath the skin. The reticular layer is part of the dermis.', 'Anatomy & Physiology', '🧬'),
(295, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which skin cells alert the immune system to pathogens?', '["Melanocytes", "Keratinocytes", "Dendritic (Langerhans) cells", "Tactile (Merkel) cells"]'::jsonb, 2, 'Dendritic (Langerhans) cells in the epidermis capture antigens and alert the immune system.', 'Anatomy & Physiology', '🧬'),
(296, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Antibodies belong to which class of plasma proteins?', '["Albumins", "Gamma globulins", "Alpha globulins", "Agglutinins"]'::jsonb, 1, 'Antibodies (immunoglobulins) are gamma globulins.', 'Anatomy & Physiology', '🧬'),
(297, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Serum is blood plasma minus its:', '["Sodium ions", "Calcium ions", "Fibrinogen", "Albumin"]'::jsonb, 2, 'Serum is plasma with the clotting proteins, chiefly fibrinogen, removed.', 'Anatomy & Physiology', '🧬'),
(298, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Heparin and histamine are secreted by:', '["Plasma cells", "Basophils", "B lymphocytes", "Neutrophils"]'::jsonb, 1, 'Basophils, like mast cells, secrete heparin and histamine.', 'Anatomy & Physiology', '🧬'),
(299, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Oxygen binds to which part of the haemoglobin molecule?', '["Valine", "Fe²⁺ (ferrous iron) of haem", "Globin chains", "Spectrin"]'::jsonb, 1, 'Oxygen binds reversibly to the ferrous iron (Fe²⁺) in each haem group of haemoglobin.', 'Anatomy & Physiology', '🧬'),
(300, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which of these is a granulocyte?', '["A lymphocyte", "A macrophage", "An eosinophil", "An erythrocyte"]'::jsonb, 2, 'Granulocytes are neutrophils, eosinophils and basophils. Lymphocytes and monocytes/macrophages are agranulocytes.', 'Anatomy & Physiology', '🧬'),
(301, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Blood flows from the right atrium to the right ventricle through which valve?', '["Pulmonary", "Tricuspid", "Bicuspid (mitral)", "Aortic"]'::jsonb, 1, 'The right atrioventricular valve is the tricuspid valve. The left is the mitral (bicuspid).', 'Anatomy & Physiology', '🧬'),
(302, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'How many pulmonary veins empty into the right atrium?', '["None", "One", "Two", "Four"]'::jsonb, 0, 'The four pulmonary veins drain oxygenated blood into the LEFT atrium. None enter the right atrium.', 'Anatomy & Physiology', '🧬'),
(303, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'The outermost layer of the heart wall is known as:', '["The pericardial sac", "The epicardium", "The visceral pericardium", "Both the epicardium and the visceral pericardium (the same layer)"]'::jsonb, 3, 'The outermost layer of the heart wall is the epicardium, which is the visceral layer of serous pericardium.', 'Anatomy & Physiology', '🧬'),
(304, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'A deficiency of pulmonary surfactant is most likely to cause:', '["COPD", "Atelectasis", "Pneumothorax", "Chronic bronchitis"]'::jsonb, 1, 'Surfactant lowers alveolar surface tension. Without it, alveoli collapse (atelectasis), as in neonatal respiratory distress syndrome.', 'Anatomy & Physiology', '🧬'),
(305, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'The source of pulmonary surfactant is:', '["The visceral pleura", "Tracheal glands", "Alveolar capillaries", "Great alveolar (type II) cells"]'::jsonb, 3, 'Surfactant is secreted by great alveolar (type II) cells.', 'Anatomy & Physiology', '🧬'),
(306, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Respiratory arrest would most likely result from a tumour of the:', '["Pons", "Midbrain", "Thalamus", "Medulla oblongata"]'::jsonb, 3, 'The medulla oblongata contains the respiratory rhythm centre, so a tumour there is most likely to cause respiratory arrest.', 'Anatomy & Physiology', '🧬'),
(307, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'The rhythm of breathing is set by neurons in the:', '["Medulla oblongata", "Pons", "Midbrain", "Hypothalamus"]'::jsonb, 0, 'The basic rhythm of breathing is generated by medullary neurons (pre-Bötzinger complex). The pons modifies it.', 'Anatomy & Physiology', '🧬'),
(308, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which muscle aids deep (forced) expiration?', '["Scalenes", "Sternocleidomastoid", "Rectus abdominis", "External intercostals"]'::jsonb, 2, 'Forced (deep) expiration uses the abdominal muscles, such as rectus abdominis, and the internal intercostals. Scalenes, SCM and external intercostals are inspiratory.', 'Anatomy & Physiology', '🧬'),
(309, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'A glomerulus and glomerular capsule together make up one:', '["Renal capsule", "Renal corpuscle", "Kidney lobule", "Nephron"]'::jsonb, 1, 'The glomerulus and Bowman''s (glomerular) capsule together form the renal corpuscle.', 'Anatomy & Physiology', '🧬'),
(310, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'The kidney has more of which structure than any of the others listed?', '["Arcuate arteries", "Minor calyces", "Medullary pyramids", "Afferent arterioles"]'::jsonb, 3, 'Each kidney has about a million nephrons, each with its own afferent arteriole, far more than its calyces, pyramids or arcuate arteries.', 'Anatomy & Physiology', '🧬'),
(311, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Water reabsorbed by the collecting duct enters the:', '["Nephron loop", "Minor calyx", "Ureter", "Vasa recta"]'::jsonb, 3, 'Water reabsorbed from the collecting duct passes into the medullary interstitium and is carried away by the vasa recta.', 'Anatomy & Physiology', '🧬'),
(312, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which endocrine gland is most directly involved in immune function?', '["Pancreas", "Thymus", "Adenohypophysis", "Adrenal glands"]'::jsonb, 1, 'The thymus is where T lymphocytes mature (thymosin). It is the endocrine gland most involved in immunity.', 'Anatomy & Physiology', '🧬'),
(313, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which organs are both involved in the synthesis of calcitriol and erythropoietin?', '["Anterior and posterior pituitary", "Thyroid and thymus", "Liver and kidneys", "Parathyroids and pancreatic islets"]'::jsonb, 2, 'The liver (25-hydroxylation) and kidney (1-hydroxylation) both make calcitriol. Both also produce erythropoietin, mainly the kidney.', 'Anatomy & Physiology', '🧬'),
(314, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which of the following is NOT a hormone?', '["Prolactin", "Thymosin", "Renin", "Atrial natriuretic peptide"]'::jsonb, 2, 'Renin is an enzyme that converts angiotensinogen to angiotensin I. Prolactin, thymosin and ANP are hormones.', 'Anatomy & Physiology', '🧬'),
(315, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which hormone increases osteoclast activity and raises blood calcium?', '["Parathyroid hormone", "Calcitonin", "Calcitriol", "Aldosterone"]'::jsonb, 0, 'PTH increases osteoclast activity, renal calcium reabsorption and calcitriol production, raising blood calcium. Calcitonin does the opposite.', 'Anatomy & Physiology', '🧬'),
(316, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'The largest air passages that take part in gas exchange are the:', '["Respiratory bronchioles", "Terminal bronchioles", "Primary bronchi", "Alveolar ducts"]'::jsonb, 0, 'Respiratory bronchioles are the first, and largest, airways with alveoli in their walls, where gas exchange begins.', 'Anatomy & Physiology', '🧬'),
(317, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which of the following are fewest in number but largest in diameter?', '["Alveoli", "Terminal bronchioles", "Alveolar ducts", "Tertiary bronchi"]'::jsonb, 3, 'Tertiary (segmental) bronchi are the widest and fewest of these. The airways get narrower and more numerous towards the alveoli.', 'Anatomy & Physiology', '🧬'),
(318, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'What is the correct sequence of electrical conduction in the heart?', '["SA node, internodal pathways, AV node, bundle of His, bundle branches, Purkinje fibres", "AV node, internodal pathways, SA node, bundle of His, bundle branches, Purkinje fibres", "SA node, internodal pathways, AV node, Purkinje fibres, bundle branches, bundle of His", "None of the options"]'::jsonb, 0, 'Conduction runs SA node → internodal pathways → AV node → bundle of His → right and left bundle branches → Purkinje fibres.', 'Cardiovascular', '🫀'),
(319, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'The SA node fires at a rate of:', '["80–90 bpm", "40–60 bpm", "60–100 bpm", "60–80 bpm"]'::jsonb, 2, 'The SA node, the natural pacemaker, fires at 60–100 bpm. The AV junction fires at 40–60 and the ventricles at 20–40.', 'Cardiovascular', '🫀'),
(320, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'On an ECG, the P wave reflects atrial depolarisation initiated by the:', '["Left bundle branch", "AV node", "Bachmann''s bundle", "SA node"]'::jsonb, 3, 'The P wave is atrial depolarisation, which the SA node initiates.', 'Cardiovascular', '🫀'),
(321, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which part of the heart''s conduction system is known as the "gatekeeper"?', '["AV node", "Gap junction", "Bundle of His", "SA node"]'::jsonb, 0, 'The AV node is the "gatekeeper": it delays conduction so the ventricles can fill and limits how fast impulses reach the ventricles.', 'Cardiovascular', '🫀'),
(322, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which part of the conduction system forms the PR segment on the ECG?', '["Purkinje fibres", "AV node, bundle of His and bundle branches", "Apex of the heart", "SA node"]'::jsonb, 1, 'The PR segment (end of P to start of QRS) is the delay as the impulse passes through the AV node, bundle of His and bundle branches.', 'Cardiovascular', '🫀'),
(323, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Drawing conclusions without bias or value judgement is called:', '["Objectivity", "Specificity", "Values", "Facts"]'::jsonb, 0, 'Objectivity means drawing conclusions from evidence without bias or value judgement.', 'Research & Nursing Process', '📊'),
(324, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Research undertaken for the sake of knowledge is:', '["Pure research", "Action research", "A pilot study", "A survey"]'::jsonb, 0, 'Pure (basic, fundamental) research seeks knowledge for its own sake. Applied and action research solve practical problems.', 'Research & Nursing Process', '📊'),
(325, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'An example of a fact-finding study is:', '["Pure research", "A survey", "Action research", "Long-term research"]'::jsonb, 1, 'A survey is a fact-finding (descriptive) study that collects information about a population as it is.', 'Research & Nursing Process', '📊'),
(326, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Research conducted to find a solution to an immediate problem is:', '["Fundamental research", "Analytical research", "A survey", "Action research"]'::jsonb, 3, 'Action research is done to find a solution to an immediate, practical problem in a setting.', 'Research & Nursing Process', '📊'),
(327, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Fundamental research is otherwise called:', '["Action research", "Survey", "Pilot study", "Pure research"]'::jsonb, 3, 'Fundamental research is also called pure or basic research.', 'Research & Nursing Process', '📊'),
(328, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'The research method is a part of:', '["The problem", "The experiment", "Research techniques", "Research methodology"]'::jsonb, 3, 'Research methods (the techniques) are part of the broader research methodology, which is the science of how research is done.', 'Research & Nursing Process', '📊'),
(329, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Converting a question into a researchable problem is called:', '["Solution", "Examination", "Problem formulation", "Problem solving"]'::jsonb, 2, 'Problem formulation turns a broad question into a specific, researchable problem.', 'Research & Nursing Process', '📊'),
(330, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'When selecting a research problem, which type of problem is NOT chosen?', '["A very common problem", "An overdone problem", "An easy problem", "A rare problem"]'::jsonb, 1, 'Avoid problems that are overdone (already well researched) unless there is a new angle.', 'Research & Nursing Process', '📊'),
(331, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which is a quality of a good researcher?', '["Scientific temper", "Age", "Money", "Time"]'::jsonb, 0, 'A good researcher has a scientific temper: curiosity, objectivity, rationality and persistence.', 'Research & Nursing Process', '📊'),
(332, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'A tentative proposition that is subject to testing is a:', '["Variable", "Hypothesis", "Datum", "Concept"]'::jsonb, 1, 'A hypothesis is a tentative statement about the relationship between variables, to be tested.', 'Research & Nursing Process', '📊'),
(333, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'A hypothesis that describes a relationship between two variables is:', '["Causal", "Relational", "Descriptive", "Tentative"]'::jsonb, 1, 'A relational (associative) hypothesis states that two variables are related, without claiming cause.', 'Research & Nursing Process', '📊'),
(334, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'In statistics, "null" (as in null hypothesis) means:', '["One", "Many", "Zero/no difference", "None of these"]'::jsonb, 2, '"Null" means zero or none: the null hypothesis states no difference or relationship.', 'Research & Nursing Process', '📊'),
(335, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'A survey is mainly a ______ study.', '["Descriptive", "Experimental", "Laboratory", "Historical"]'::jsonb, 0, 'A survey is a descriptive study.', 'Research & Nursing Process', '📊'),
(336, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'A survey is always a ______ study.', '["Field", "Laboratory", "Office", "Classroom"]'::jsonb, 0, 'Surveys are done in the field, among people in their real settings, not in a laboratory.', 'Research & Nursing Process', '📊'),
(337, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'The first page of a research report is the:', '["Appendix", "Bibliography", "Index", "Title page"]'::jsonb, 3, 'The title page is the first page of a research report.', 'Research & Nursing Process', '📊'),
(338, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Failure to acknowledge borrowed material (using others'' work as one''s own) is called:', '["Acknowledgement", "Footnote", "Index", "Plagiarism"]'::jsonb, 3, 'Plagiarism is presenting someone else''s work or ideas as your own without acknowledgement.', 'Research & Nursing Process', '📊'),
(339, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'The blueprint of a research work is called the:', '["Research problem", "Research design", "Research tools", "Research methods"]'::jsonb, 1, 'The research design is the blueprint or plan of the whole study.', 'Research & Nursing Process', '📊'),
(340, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'The independent variable refers to:', '["The aim of an experiment", "The variable manipulated or varied by the researcher", "A variable used only in the control group", "The variable that shows the effect of the manipulation"]'::jsonb, 1, 'The independent variable is the one the researcher manipulates. The dependent variable shows its effect.', 'Research & Nursing Process', '📊'),
(341, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which of the following is a non-probability sampling method?', '["Snowball", "Simple random", "Cluster", "Stratified"]'::jsonb, 0, 'Snowball sampling (participants recruit others) is non-probability. Random, cluster and stratified sampling are probability methods.', 'Research & Nursing Process', '📊'),
(342, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'A Type I error occurs if:', '["The null hypothesis is rejected even though it is true", "The null hypothesis is accepted even though it is false", "Both null and alternative hypotheses are rejected", "None of the above"]'::jsonb, 0, 'A Type I error (alpha, false positive) is rejecting a null hypothesis that is actually true. Type II is accepting a false null.', 'Research & Nursing Process', '📊'),
(343, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which of the following is NOT a characteristic of research?', '["Research is systematic", "Research is active, not passive", "Research is not a process", "Research is problem-oriented"]'::jsonb, 2, 'Research is a systematic, active, problem-oriented process, so "research is not a process" is false.', 'Research & Nursing Process', '📊'),
(344, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Books and records are the primary sources of data in:', '["Clinical research", "Historical research", "Laboratory research", "Participatory research"]'::jsonb, 1, 'Historical research relies on primary documents and records such as books, archives and letters.', 'Research & Nursing Process', '📊'),
(345, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'The first step of research is:', '["Finding a solution", "Selecting a design", "Collecting data", "Identifying a problem"]'::jsonb, 3, 'The research process begins with identifying a problem.', 'Research & Nursing Process', '📊'),
(346, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'A control group condition is applied in:', '["Survey research", "Historical research", "Descriptive research", "Experimental research"]'::jsonb, 3, 'Experimental research uses a control group to compare against the group receiving the intervention.', 'Research & Nursing Process', '📊'),
(347, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which of the following is a research (data-collection) tool?', '["Graph", "Diagram", "Illustration", "Questionnaire"]'::jsonb, 3, 'A questionnaire is a data-collection tool. Graphs and diagrams present data.', 'Research & Nursing Process', '📊'),
(348, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'The best nutritional management for a severely obese client is a:', '["Very high-calorie diet", "Very low-calorie diet (supervised)", "Very high-carbohydrate diet", "Very high-fat diet"]'::jsonb, 1, 'Severe obesity is managed with calorie restriction, sometimes a supervised very-low-calorie diet, plus activity and behavioural change.', 'GI, Endocrine & Metabolic', '🍽️'),
(349, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which IV solution provides free water and intracellular hydration?', '["Ringer''s lactate", "5% dextrose in water", "3% saline", "5% dextrose in normal saline"]'::jsonb, 1, '5% dextrose in water is isotonic in the bag, but the glucose is metabolised, leaving free water that hydrates the cells.', 'Renal & Fluid Balance', '💧'),
(350, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which symptom usually first brings a client with pernicious anaemia to seek medical attention?', '["Dark stools", "Sudden weight loss", "Tendency to bleed easily", "Feeling unusually fatigued"]'::jsonb, 3, 'Pernicious anaemia (B12 deficiency) usually presents with gradually increasing tiredness and weakness.', 'Laboratory Sciences & Haematology', '🔬'),
(351, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which element is used in diarrhoea treatment to reduce stool output and severity?', '["Oral iron", "Oral sodium", "Oral potassium", "Oral zinc"]'::jsonb, 3, 'Oral zinc (10–20 mg daily for 10–14 days) with ORS shortens diarrhoea and reduces stool output and severity in children (WHO).', 'GI, Endocrine & Metabolic', '🍽️'),
(352, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'A normal body mass index (BMI) should not exceed:', '["20", "25", "30", "35"]'::jsonb, 1, 'Normal BMI is 18.5–24.9 kg/m², so it should not exceed about 25. 25–29.9 is overweight.', 'GI, Endocrine & Metabolic', '🍽️'),
(353, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'The process by which water and diffusible substances move together across a membrane in response to fluid pressure is:', '["Osmosis", "Diffusion", "Filtration", "Active transport"]'::jsonb, 2, 'Filtration moves water and small solutes together across a membrane under hydrostatic (fluid) pressure, as at the glomerulus.', 'Anatomy & Physiology', '🧬'),
(354, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'A bone marrow condition in which all formed elements of the blood are simultaneously reduced is:', '["Thalassaemia", "Iron-deficiency anaemia", "Aplastic anaemia", "Haemolytic anaemia"]'::jsonb, 2, 'Aplastic anaemia is bone marrow failure with pancytopenia, a reduction in all three cell lines at once.', 'Laboratory Sciences & Haematology', '🔬'),
(355, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which eating disorder is characterised by low body weight, body-image distortion and an obsessive fear of gaining weight?', '["Pica", "Bulimia nervosa", "Anorexia nervosa", "Binge-eating disorder"]'::jsonb, 2, 'Anorexia nervosa: low body weight, distorted body image and intense fear of weight gain.', 'Mixed Revision', '📚'),
(356, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'An eating disorder in which a person eats substances with no nutritional value is:', '["Pica", "Bulimia nervosa", "Anorexia nervosa", "Binge-eating disorder"]'::jsonb, 0, 'Pica is persistently eating non-nutritive substances such as clay, chalk or ice.', 'Mixed Revision', '📚'),
(357, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'A condition with recurrent binge eating followed by intentional purging is:', '["Pica", "Bulimia nervosa", "Anorexia nervosa", "Binge-eating disorder"]'::jsonb, 1, 'Bulimia nervosa: recurrent binge eating followed by compensatory purging (vomiting, laxatives).', 'Mixed Revision', '📚'),
(358, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'A BMI between 25 and 29.9 is classified as:', '["Obesity", "Overweight", "Severe obesity", "Normal weight"]'::jsonb, 1, 'BMI 25–29.9 is overweight. Obesity is 30 or more.', 'GI, Endocrine & Metabolic', '🍽️'),
(359, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'The following are goals of nutrition in the ICU EXCEPT:', '["To preserve lean body mass", "To maintain immune function", "To avoid metabolic complications", "To treat and prevent worm infestation"]'::jsonb, 3, 'ICU nutrition aims to preserve lean body mass, support immune function and avoid metabolic complications. Treating worm infestation is not one of its goals.', 'GI, Endocrine & Metabolic', '🍽️'),
(360, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'The relationship between drug concentration and time is studied in:', '["Pharmacokinetics", "Pharmacodynamics", "Pharmacogenomics", "Pharmacovigilance"]'::jsonb, 0, 'Pharmacokinetics is what the body does to the drug (absorption, distribution, metabolism, excretion), i.e. drug concentration over time.', 'ICU Pharmacology', '💊'),
(361, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which statement correctly explains why antibiotics do not treat viral infections?', '["Viruses are non-living but interact with antibodies", "Taking antibiotics cures viral infections", "Viruses lack the metabolic pathways antibiotics act on, whereas bacteria have them", "Viruses have acquired resistance to all antibiotics"]'::jsonb, 2, 'Antibiotics target bacterial structures and metabolic pathways (cell wall, ribosomes). Viruses lack these, so antibiotics do not work on them.', 'ICU Pharmacology', '💊'),
(362, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which antibiotic acts as a protein synthesis inhibitor?', '["Penicillin", "Tetracycline", "Cefotaxime", "Trimethoprim"]'::jsonb, 1, 'Tetracyclines bind the 30S ribosomal subunit and block protein synthesis. Penicillins and cephalosporins act on the cell wall; trimethoprim blocks folate.', 'ICU Pharmacology', '💊'),
(363, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which drug is effective in treating oral candidiasis?', '["Nystatin", "Bacitracin", "Tetracycline", "Griseofulvin"]'::jsonb, 0, 'Nystatin is a polyene antifungal used topically and orally for oral candidiasis (thrush).', 'ICU Pharmacology', '💊'),
(364, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Benzylpenicillin is the chemical name for:', '["Penicillin V", "Penicillin F", "Penicillin G", "Phenethicillin"]'::jsonb, 2, 'Benzylpenicillin is penicillin G. Penicillin V is phenoxymethylpenicillin.', 'ICU Pharmacology', '💊'),
(365, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Streptomycin is produced by which organism?', '["Streptomyces noursei", "Streptomyces nodosus", "Streptomyces fradiae", "Streptomyces griseus"]'::jsonb, 3, 'Streptomycin was isolated from Streptomyces griseus (Waksman, 1943).', 'ICU Pharmacology', '💊'),
(366, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'A key challenge of using electronic nursing records in a Nigerian setting is:', '["ICT is less reliable than paper by nature", "Lack of adequate training and of the recommended ICT facilities", "ICT is always slower at retrieving information", "Electronic work can never be backed up"]'::jsonb, 1, 'The main barriers to EHRs in Nigeria are inadequate staff training and a shortage of reliable ICT facilities (power, computers, connectivity).', 'Nursing Informatics & ICT', '💻'),
(367, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'EHRs can enhance nurses'' decision-making by:', '["Supplying access to client health information", "Allowing structured data entry", "Offering electronic access to scientific knowledge", "All of the options"]'::jsonb, 3, 'EHRs support decisions by giving access to client information, structured data entry and electronic access to scientific knowledge.', 'Nursing Informatics & ICT', '💻'),
(368, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'The four main functional components of a standard computer are:', '["Input, process, output and memory (storage)", "Keyboard, mouse, monitor and CPU", "Hardware, software, system apps and applications", "Laptop, desktop, tablet and hand-held"]'::jsonb, 0, 'A computer''s four main functional components are input, processing, output and storage (memory).', 'Nursing Informatics & ICT', '💻'),
(369, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Why will computer-based patient records benefit clients more than paper records?', '["Easy retrieval of case files across facilities", "Backed-up storage protects data against loss (e.g. fire)", "Less time spent retrieving case files", "All of the options"]'::jsonb, 3, 'Computerised records are easy to retrieve, protected by backups and save time compared with paper files.', 'Nursing Informatics & ICT', '💻'),
(370, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'The process of storing, protecting and analysing data pulled from diverse sources is called:', '["Data standard", "Data management", "Data base", "Data entry"]'::jsonb, 1, 'Data management is storing, protecting, organising and analysing data from diverse sources.', 'Nursing Informatics & ICT', '💻'),
(371, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which one is application software?', '["Microsoft Word", "Avast Antivirus", "Windows XP", "Android 11"]'::jsonb, 0, 'Microsoft Word is application software. Windows and Android are operating systems; antivirus is utility software.', 'Nursing Informatics & ICT', '💻'),
(372, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'According to size, computers are classified as:', '["Super, mainframe, mini and micro computers", "Large, ultra-large, small and compact", "Big-scale and small-scale", "Laptop, desktop and hand-held"]'::jsonb, 0, 'By size, computers are classified as super, mainframe, mini and micro computers.', 'Nursing Informatics & ICT', '💻'),
(373, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Computer software is classified into:', '["System, application and utility software", "Word, PowerPoint and Excel", "Special, general and specific packages", "Personal and industrial software"]'::jsonb, 0, 'Software is broadly system software (including utilities) and application software.', 'Nursing Informatics & ICT', '💻'),
(374, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'According to function, computers are classified as:', '["Laptop, desktop and hand-held", "Electronic and battery-powered", "Analogue, digital and hybrid", "Automatic and manual"]'::jsonb, 2, 'By function (how they process data), computers are analogue, digital or hybrid.', 'Nursing Informatics & ICT', '💻'),
(375, 'UMTH Pre-Professional Paper I, Aug 2023', 'UMTH School of Post Basic Critical Care Nursing, Pre-professional exam Paper I, August 2023 (uploaded)', 'Which one is NOT an input device?', '["Mouse", "Keyboard", "Scanner", "Monitor"]'::jsonb, 3, 'A monitor is an output device. Mouse, keyboard and scanner are input devices.', 'Nursing Informatics & ICT', '💻'),
(376, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Concerning the ECG, all of the following are incorrect EXCEPT:', '["A waveform moving toward the top of the paper is a negative deflection", "A waveform moving toward the bottom of the paper is a positive deflection", "The ECG waveform shows the heart''s mechanical pumping force", "Time and rate are measured on the horizontal axis and voltage on the vertical axis"]'::jsonb, 3, 'On ECG paper, time (and so rate) runs along the horizontal axis and voltage up the vertical axis. Upward deflections are positive and downward ones negative.', 'Cardiovascular', '🫀'),
(377, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Which is correct about the P wave?', '["It represents atrial repolarisation", "It represents atrial depolarisation", "It represents ventricular repolarisation", "It represents ventricular depolarisation"]'::jsonb, 1, 'The P wave is atrial depolarisation. Atrial repolarisation is hidden in the QRS.', 'Cardiovascular', '🫀'),
(378, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Potassium is most abundant in which compartment?', '["Intracellular", "Extracellular", "Intravascular", "Interstitial"]'::jsonb, 0, 'About 98% of the body''s potassium is intracellular (about 140 mmol/L inside cells vs 3.5–5 outside).', 'ABG & Electrolytes', '🩸'),
(379, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'When investigating a newborn with hyperbilirubinaemia, which bilirubin fractions should be measured?', '["Conjugated bilirubin only", "Total bilirubin only", "Total and unconjugated bilirubin", "Total and conjugated bilirubin"]'::jsonb, 3, 'Measure total AND conjugated (direct) bilirubin. A raised conjugated fraction points to cholestasis or biliary atresia and changes management.', 'Obstetric & Neonatal', '🤱'),
(380, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'The approximate total body water content of an adult woman is:', '["80%", "70%", "60%", "50%"]'::jsonb, 3, 'Total body water is about 60% of body weight in adult men and about 50–55% in women, who have more body fat.', 'Anatomy & Physiology', '🧬'),
(381, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'How many distinct steps are there in the nursing process?', '["4", "5", "6", "7"]'::jsonb, 1, 'The nursing process has 5 steps: assessment, diagnosis, planning, implementation and evaluation (ADPIE).', 'Research & Nursing Process', '📊'),
(382, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'The approximate daily volume of glomerular filtrate in an adult is:', '["50 L in males and 90 L in females", "120 L in males and 130 L in females", "180 L in males and about 150 L in females", "300 L in both sexes"]'::jsonb, 2, 'The kidneys filter about 180 L of plasma a day (GFR about 125 mL/min) in adult men, slightly less in women.', 'Anatomy & Physiology', '🧬'),
(383, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Orem identified three types of nursing systems. One of them is:', '["Team nursing", "Primary nursing", "Individualised client care", "Wholly compensatory"]'::jsonb, 3, 'Orem''s three nursing systems are wholly compensatory, partly compensatory and supportive-educative.', 'Research & Nursing Process', '📊'),
(384, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Which list contains Marjory Gordon''s functional health patterns?', '["Cardiovascular, neurological, gastrointestinal, integumentary", "Health maintenance, elimination, activity/exercise, self-perception/self-concept", "Role performance, independence, interdependence, physiology", "Universal, developmental, health deviation, therapeutic"]'::jsonb, 1, 'Gordon''s 11 functional health patterns include health perception–management, nutrition–metabolic, elimination, activity–exercise, self-perception–self-concept and others.', 'Research & Nursing Process', '📊'),
(385, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'The steps assessment, planning, implementation and evaluation of the nursing process were described by:', '["WICHE", "Yura and Walsh", "Orlando", "Knowles"]'::jsonb, 1, 'Yura and Walsh (1967) described the four-step nursing process: assessment, planning, implementation and evaluation. Diagnosis was added later.', 'Research & Nursing Process', '📊'),
(386, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'A directive interview is said to be:', '["Structured", "Unstructured", "Semi-structured", "Liberal"]'::jsonb, 0, 'A directive interview is structured: the nurse controls the questions to get specific information.', 'Research & Nursing Process', '📊'),
(387, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'The most effective interview style is:', '["Directive", "Non-directive", "Semi-structured only", "A combination of directive and non-directive"]'::jsonb, 3, 'Combining directive (structured) and non-directive (open) styles gets specific facts and the patient''s own concerns.', 'Research & Nursing Process', '📊'),
(388, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'The assessment approach in which the cardiovascular system is assessed before the genito-urinary system is the:', '["Cephalocaudal approach", "Systematic approach", "Body systems approach", "Approach by order of priority"]'::jsonb, 2, 'The body systems approach assesses one system at a time, e.g. cardiovascular before genito-urinary.', 'Research & Nursing Process', '📊'),
(389, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Mr Zee says his heart pounds and he is short of breath on the stairs. The nurse then auscultates the heart and checks the pulse. The nurse is:', '["Collecting data", "Organising data", "Validating data", "Processing data into information"]'::jsonb, 2, 'Checking pulse and heart sounds to confirm a subjective complaint (palpitations, breathlessness) is validating data.', 'Research & Nursing Process', '📊'),
(390, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'COLDSPA pain assessment falls under which functional health pattern?', '["Self-perception and self-concept", "Cognition and perception", "Activity and exercise", "Sleep and rest"]'::jsonb, 1, 'COLDSPA (Character, Onset, Location, Duration, Severity, Pattern, Associated factors) assesses pain, part of Gordon''s cognitive–perceptual pattern.', 'Research & Nursing Process', '📊'),
(391, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'A patient''s choices, preferences and decisions are assessed under:', '["Cognition and perception", "Values and beliefs", "Self-perception and self-concept", "Nutrition and metabolism"]'::jsonb, 1, 'The values–beliefs pattern covers the patient''s values, goals, choices and spiritual beliefs that guide decisions.', 'Research & Nursing Process', '📊'),
(392, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Which activity best describes the evaluation phase?', '["Interpret data and identify client problems", "Establish short- and long-term goals", "Reassess and compare outcomes with the set objectives", "Carry out nursing procedures and document"]'::jsonb, 2, 'Evaluation means reassessing the patient and comparing outcomes against the set goals.', 'Research & Nursing Process', '📊'),
(393, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'A nurse made Mr Kay''s care plan on admission on Tuesday, then made another care plan for him on Wednesday''s shift. Wednesday''s plan is a(n):', '["Initial plan", "Ongoing plan", "Reviewed plan", "Discharge plan"]'::jsonb, 1, 'The initial plan is made on admission. Plans updated on later shifts as the patient''s status changes are ongoing plans.', 'Research & Nursing Process', '📊'),
(394, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'The nursing process is:', '["An abstract phenomenon in nursing", "A systematic and rational method of providing nursing care", "A collaborative method of caring for patients", "A procedure that ensures documentation"]'::jsonb, 1, 'The nursing process is a systematic, rational, problem-solving method of planning and giving individualised care.', 'Research & Nursing Process', '📊'),
(395, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Which framework helps the nurse organise data collected from the patient?', '["Gordon''s functional health patterns", "Roy''s adaptation model", "Nightingale''s environmental theory", "Maslow''s hierarchy"]'::jsonb, 0, 'Gordon''s functional health patterns give a framework for organising assessment data.', 'Research & Nursing Process', '📊'),
(396, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'NANDA stands for:', '["National Assessment Nursing Diagnosis Association", "North American Nursing Diagnosis Association", "Non-American Nursing Diagnosis Association", "New American Nursing Diagnosis Association"]'::jsonb, 1, 'NANDA was the North American Nursing Diagnosis Association, now NANDA International (NANDA-I).', 'Research & Nursing Process', '📊'),
(397, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Which is necessary for making a nursing diagnosis?', '["Clustering of cues", "Validating the plan", "Performing activities", "Designing the care plan"]'::jsonb, 0, 'Grouping related assessment cues (clustering) shows the patterns that support a nursing diagnosis.', 'Research & Nursing Process', '📊'),
(398, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Haemostasis is the:', '["Physiological process by which internal systems are kept in equilibrium", "Collection of blood within the vessels", "Stoppage of bleeding", "Sluggishness of the general circulation"]'::jsonb, 2, 'Haemostasis is the stopping of bleeding (vasoconstriction, platelet plug, coagulation). Homeostasis is internal equilibrium.', 'Laboratory Sciences & Haematology', '🔬'),
(399, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'The immediate haemostatic response to a damaged vessel is:', '["Platelet adhesion", "Platelet aggregation", "Viscous metamorphosis of platelets", "Vasoconstriction"]'::jsonb, 3, 'The first response to vessel injury is reflex vasoconstriction, followed by platelet adhesion, aggregation and coagulation.', 'Laboratory Sciences & Haematology', '🔬'),
(400, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'In-text citations from different groups of authors are usually ordered by:', '["Chronology", "Consideration", "Participation", "Impact factor"]'::jsonb, 0, 'Citations from different author groups are usually ordered chronologically (by year) in the text, or alphabetically in the reference list.', 'Research & Nursing Process', '📊'),
(401, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Research control means holding constant other influences that might affect the:', '["Independent variable", "Dependent variable", "Antecedent variable", "Conditioned variable"]'::jsonb, 1, 'Research control holds extraneous influences constant so that changes in the dependent variable can be put down to the independent variable.', 'Research & Nursing Process', '📊'),
(402, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Common electronic databases for nurse researchers include all EXCEPT:', '["CINAHL", "PubMed", "MEDLINE", "American Nurses Association"]'::jsonb, 3, 'CINAHL, PubMed and MEDLINE are bibliographic databases. The ANA is a professional organisation.', 'Research & Nursing Process', '📊'),
(403, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Which document is submitted to the Institutional Review Board for ethical clearance?', '["Research report", "Research grant", "Research proposal", "Research results"]'::jsonb, 2, 'A research proposal goes to the Institutional Review Board (ethics committee) for ethical clearance before data collection.', 'Research & Nursing Process', '📊'),
(404, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Which is a characteristic of quantitative research?', '["There are multiple subjective realities", "Data are reported in a literary style", "No generalisation is made from the findings", "A large sample is emphasised"]'::jsonb, 3, 'Quantitative research stresses large, representative samples and generalisation. Multiple subjective realities and literary reporting are qualitative features.', 'Research & Nursing Process', '📊'),
(405, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Cause-and-effect relationships are best studied using which design?', '["Quasi-experimental design", "Experimental design", "Non-experimental design", "Prospective design"]'::jsonb, 1, 'True experimental designs (manipulation, control, randomisation) are best for testing cause-and-effect.', 'Research & Nursing Process', '📊'),
(406, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'In experimental research, which group is the basis for determining the effect of the intervention?', '["Control group", "Experimental group", "Sample group", "Whole population"]'::jsonb, 0, 'The control group gives the baseline for judging the effect of the intervention.', 'Research & Nursing Process', '📊'),
(407, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'The difference between experimental and quasi-experimental designs is that:', '["Experimental designs lack a control group", "Quasi-experimental designs have randomisation and experimental designs do not", "Experimental designs have control but quasi-experiments have randomisation", "Quasi-experimental designs lack randomisation while experimental designs have it"]'::jsonb, 3, 'Quasi-experiments manipulate an independent variable but lack randomisation, and sometimes a control group. True experiments have both.', 'Research & Nursing Process', '📊'),
(408, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'A correlational design differs from a true experimental design by:', '["Studying associations between phenomena", "Studying cause-and-effect relationships", "Studying variables in an atypical setting", "Using a multidirectional approach"]'::jsonb, 0, 'Correlational designs look for associations between variables without manipulating them, so they cannot prove causation.', 'Research & Nursing Process', '📊'),
(409, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'A researcher studying a present phenomenon and linking it to past antecedent factors should use a:', '["Non-experimental prospective design", "Quasi-experimental randomised design", "Non-experimental retrospective design", "Quasi-experimental controlled design"]'::jsonb, 2, 'A retrospective (ex post facto) design starts with a present outcome and looks back for causes in the past.', 'Research & Nursing Process', '📊'),
(410, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'In defining the scope of a study, which is NOT necessarily indicated?', '["The period of study", "The population of study", "The setting of the study", "The significance of the study"]'::jsonb, 3, 'The scope (delimitations) states the period, population and setting. The study''s significance is a separate section.', 'Research & Nursing Process', '📊'),
(411, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Which statement about the operational definition of terms is correct?', '["It is universally accepted for all studies", "It is the same as the dictionary/conceptual definition", "It is the conceptual definition used in the conceptual phase", "It is a concise working definition of the variables and terms used in the study"]'::jsonb, 3, 'An operational definition is the concise working definition of how variables and terms will be measured in that particular study.', 'Research & Nursing Process', '📊'),
(412, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Descriptive research aims at:', '["Judging the impact of a treatment", "Investigating relationships among variables", "Categorising and defining phenomena", "Monitoring interrelationships among phenomena"]'::jsonb, 2, 'Descriptive research observes, describes, classifies and defines phenomena as they exist.', 'Research & Nursing Process', '📊'),
(413, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'When the purpose of a study is to explain the underlying causes of phenomena, the study is:', '["Descriptive", "Explanatory", "Predictive", "Developmental"]'::jsonb, 1, 'Explanatory research seeks to understand the underlying causes of, or reasons for, phenomena.', 'Research & Nursing Process', '📊'),
(414, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'The characteristic of scientific research that roots findings in objective reality is:', '["Empiricism", "Generalisation", "Systematisation", "Control"]'::jsonb, 0, 'Empiricism means knowledge is grounded in objective observation, evidence gathered through the senses.', 'Research & Nursing Process', '📊'),
(415, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Of 400 ICU admissions over 5 years, 80 had myocardial infarction. Expressed per 1,000, the prevalence is:', '["20 per 1,000", "200 per 1,000", "80 per 500", "40 per 250"]'::jsonb, 1, 'Prevalence = 80 ÷ 400 = 0.2, which is 200 per 1,000.', 'Research & Nursing Process', '📊'),
(416, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Which statement about a sample is NOT true?', '["It is the same as the accessible population", "It is a subset of the units in the population", "The study is limited to the elements in the sample", "It comprises the basic units about which information is collected"]'::jsonb, 0, 'A sample is a subset of the population, not the same as the whole accessible population.', 'Research & Nursing Process', '📊'),
(417, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'The less variation an instrument produces in repeated measurements of an attribute, the higher its:', '["Relativity", "Reliability", "Validity", "Sensitivity"]'::jsonb, 1, 'Reliability is consistency: less variation on repeated measurement means higher reliability.', 'Research & Nursing Process', '📊'),
(418, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'For a patient with Crohn''s disease, the nurse recommends a diet that is:', '["High in fibre, low in protein and calories", "High in potassium", "Low in fibre, high in protein and calories", "Low in potassium"]'::jsonb, 2, 'Crohn''s disease: a low-residue (low-fibre) diet during flares, high in protein and calories to correct malnutrition and promote healing.', 'GI, Endocrine & Metabolic', '🍽️'),
(419, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Which physiological response is commonly associated with surgical stress?', '["Bronchial constriction", "Decreased cortisol levels", "Peripheral vasodilation", "Sodium and water retention"]'::jsonb, 3, 'The surgical stress response releases ADH, aldosterone and cortisol, so the body retains sodium and water.', 'Anaesthesia & Perioperative Care', '💉'),
(420, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'The main goal of treatment for acute glomerulonephritis is to:', '["Encourage activity", "Encourage a high-protein intake", "Maintain fluid balance", "Teach intermittent catheterisation"]'::jsonb, 2, 'Acute glomerulonephritis care centres on fluid balance: monitor weights, restrict fluid and sodium, and control BP and oedema.', 'Renal & Fluid Balance', '💧'),
(421, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Nursing diagnoses differ from medical diagnoses mainly in that they are:', '["Dependent on the medical diagnosis for direction", "Concerned with caring while medical diagnoses are concerned with curing", "Concerned with human responses while medical diagnoses are concerned with pathology", "Concerned with psychosocial parameters only"]'::jsonb, 2, 'Nursing diagnoses describe human responses to health problems. Medical diagnoses identify disease or pathology.', 'Research & Nursing Process', '📊'),
(422, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'The most common preventable complication of abdominal surgery is:', '["Atelectasis", "Fluid and electrolyte imbalance", "Thrombophlebitis", "Urinary retention"]'::jsonb, 0, 'Atelectasis is the commonest preventable complication after abdominal surgery (pain-limited breathing). Prevent it with deep breathing, incentive spirometry and early mobilisation.', 'Anaesthesia & Perioperative Care', '💉'),
(423, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', '24 hours after a head injury, a patient develops slurred speech and disorientation. The nurse''s initial action is to:', '["Continue hourly neurological assessments", "Inform the neurosurgeon of the patient''s status", "Prepare the patient for emergency surgery", "Recheck neurological status in 15 minutes"]'::jsonb, 1, 'New slurred speech and disorientation 24 h after a head injury mean neurological deterioration, possibly an expanding haematoma. Inform the neurosurgeon at once.', 'Neurology', '🧠'),
(424, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'A family that does not know the patient''s end-of-life wishes assumes they know what is best for the patient. This reflects:', '["Justice", "Paternalism", "Pragmatism", "Veracity"]'::jsonb, 1, 'Paternalism is others deciding what is "best" for a patient without knowing or respecting the patient''s own wishes.', 'Ethics, Law & Management', '⚖️'),
(425, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'For an MI patient with "activity intolerance", which is a correctly written outcome criterion?', '["Agrees to stop smoking", "Ambulates 50 feet without experiencing dyspnoea", "Experiences no dyspnoea on exertion", "Tolerates activity well"]'::jsonb, 1, 'Outcome criteria must be specific and measurable, e.g. "ambulates 50 feet without dyspnoea".', 'Cardiovascular', '🫀'),
(426, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Feedback shows that caring is a key element of practice. Which theorist best supports this concept?', '["Erikson", "Maslow", "Rogers", "Watson"]'::jsonb, 3, 'Jean Watson''s Theory of Human Caring makes caring central to nursing.', 'Research & Nursing Process', '📊'),
(427, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'After the initial assessment of a patient with suspected stroke, the next immediate step is:', '["Administering tissue plasminogen activator", "Obtaining a non-contrast CT scan of the head", "Obtaining a neurosurgical consultation", "Preparing for carotid Doppler ultrasonography"]'::jsonb, 1, 'Suspected stroke needs an urgent non-contrast head CT to exclude haemorrhage before thrombolysis is considered.', 'Neurology', '🧠'),
(428, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Which symptom is most likely in a client with mitral regurgitation?', '["Exertional dyspnoea", "Altered level of consciousness", "Increased creatine kinase", "Chest pain"]'::jsonb, 0, 'Mitral regurgitation backs blood up into the left atrium and pulmonary veins, causing exertional dyspnoea, fatigue and palpitations.', 'Cardiovascular', '🫀'),
(429, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'To determine whether a client''s urinary frequency and burning are of renal origin, the nurse assesses for pain in the:', '["Urinary meatus", "Labia", "Suprapubic area", "Right or left costovertebral angle"]'::jsonb, 3, 'Costovertebral angle (flank) tenderness suggests kidney involvement (pyelonephritis). Suprapubic pain suggests cystitis.', 'Renal & Fluid Balance', '💧'),
(430, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'A patient has a seizure with uncontrollable rhythmic jerking movements. This is documented as a:', '["Tonic seizure", "Absence seizure", "Myoclonic seizure", "Clonic seizure"]'::jsonb, 3, 'Clonic seizures are rhythmic, jerking contractions. Tonic is stiffening, myoclonic is brief shock-like jerks, and absence is brief staring spells.', 'Neurology', '🧠'),
(431, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Excessive bubbling is seen in the water-seal chamber of a chest drain on suction. The nurse should:', '["Strip the chest tube", "Check the system for air leaks", "Recognise that the system is working correctly", "Decrease the suction pressure"]'::jsonb, 1, 'Continuous or excessive bubbling in the water-seal chamber means an air leak. Check the system from the patient down.', 'Respiratory', '🫁'),
(432, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'A client with cirrhosis is taught about thiamine-rich foods. Which food shows the best understanding?', '["Pork", "Milk", "Chicken", "Broccoli"]'::jsonb, 0, 'Pork is one of the richest food sources of thiamine (vitamin B1), which is often deficient in liver and alcohol-related disease.', 'GI, Endocrine & Metabolic', '🍽️'),
(433, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'To give medication through a nasogastric tube connected to suction, the nurse should:', '["Position the client supine", "Aspirate the tube after giving the medication", "Clamp the tube for 30 minutes after giving the medication", "Change to low intermittent suction for 30 minutes"]'::jsonb, 2, 'After giving medicine down an NG tube on suction, clamp the tube for about 30 minutes so the drug is absorbed rather than suctioned out.', 'GI, Endocrine & Metabolic', '🍽️'),
(434, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'The components of exercise prescription include the following EXCEPT:', '["Intensity", "Progression", "Gender", "Duration"]'::jsonb, 2, 'Exercise prescription uses FITT variables: frequency, intensity, time (duration), type and progression. Gender is not a prescription variable.', 'Rehabilitation & Mobilization', '🏃'),
(435, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'When designing an exercise programme, the therapist considers the following EXCEPT:', '["Pathology", "Age", "Ethnicity", "Occupation"]'::jsonb, 2, 'An exercise programme considers pathology, age, occupation, fitness and goals. Ethnicity is not a design factor.', 'Rehabilitation & Mobilization', '🏃'),
(436, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Which is NOT a barrier to early mobilisation in ICU?', '["Co-morbidities", "Physiological instability", "ICU environment", "Gender"]'::jsonb, 3, 'Barriers to ICU mobilisation include physiological instability, co-morbidities, sedation, lines and the ICU environment. Gender is not one.', 'Rehabilitation & Mobilization', '🏃'),
(437, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'A research project write-up typically comprises:', '["4 chapters", "5 chapters", "6 chapters", "7 chapters"]'::jsonb, 1, 'A typical research project has 5 chapters: introduction, literature review, methodology, results, and discussion/conclusion.', 'Research & Nursing Process', '📊'),
(438, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'The following are types of reliability EXCEPT:', '["Parallel-form reliability", "Split-half reliability", "Quintessential reliability", "Inter-rater reliability"]'::jsonb, 2, 'Recognised types include test–retest, parallel-forms, split-half (internal consistency) and inter-rater reliability. "Quintessential" is not one.', 'Research & Nursing Process', '📊'),
(439, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'The reliability index obtained from a test–retest procedure is the:', '["Coefficient of stability", "Coefficient of equivalence", "Coefficient of rater stability", "Coefficient of internal consistency"]'::jsonb, 0, 'Test–retest reliability gives the coefficient of stability. Parallel forms give equivalence; Cronbach''s alpha gives internal consistency.', 'Research & Nursing Process', '📊'),
(440, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Which method organises raw quantitative data to show general trends?', '["Frequency distribution", "Central tendency", "Standard deviation", "Standard formula"]'::jsonb, 0, 'A frequency distribution organises raw scores by how often each value or class occurs, revealing trends.', 'Research & Nursing Process', '📊'),
(441, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'A frequency polygon is drawn by:', '["Placing bars on class midpoints", "Placing columns whose width is the class interval", "Inserting a table in the corner of the graph", "Joining the plotted points with straight lines"]'::jsonb, 3, 'A frequency polygon plots class midpoints against frequency and joins the points with straight lines.', 'Research & Nursing Process', '📊'),
(442, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Interviews are best for capturing data on the following EXCEPT:', '["Feelings and attitudes", "Values and beliefs", "Opinions and reasons for them", "Actual behaviours and activities"]'::jsonb, 3, 'Interviews capture feelings, attitudes, beliefs and opinions well. Actual behaviour is better captured by observation.', 'Research & Nursing Process', '📊'),
(443, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Which scale of measurement captures data in mutually exclusive categories with no order?', '["Ratio", "Interval", "Ordinal", "Nominal"]'::jsonb, 3, 'The nominal scale puts data into mutually exclusive, unordered categories.', 'Research & Nursing Process', '📊'),
(444, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Which scale is used for gender, religion and marital status?', '["Ordinal", "Nominal", "Ratio", "Interval"]'::jsonb, 1, 'Gender, religion and marital status are unordered categories: nominal data.', 'Research & Nursing Process', '📊'),
(445, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'All arithmetic operations (add, subtract, multiply, divide) can be performed on which scale?', '["Interval", "Ordinal", "Ratio", "Nominal"]'::jsonb, 2, 'Only the ratio scale has a true zero, so all arithmetic, including ratios, is meaningful (e.g. weight, height).', 'Research & Nursing Process', '📊'),
(446, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'A (Celsius) thermometer typifies which scale?', '["Interval", "Ratio", "Ordinal", "Nominal"]'::jsonb, 0, 'Celsius and Fahrenheit thermometers are interval scales: equal intervals but no true zero.', 'Research & Nursing Process', '📊'),
(447, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'When a distribution is symmetrical and unimodal:', '["The mean is greater than the mode", "The mode is greater than the median", "The median is greater than the mean", "The mean, median and mode are the same"]'::jsonb, 3, 'In a symmetrical, unimodal (normal) distribution, the mean, median and mode are equal.', 'Research & Nursing Process', '📊'),
(448, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'A graph showing that most students scored above average in a test is:', '["Positively skewed", "Negatively skewed", "Symmetrical", "None of the above"]'::jsonb, 1, 'When most scores bunch at the high end, the tail points to the low end: negative skew.', 'Research & Nursing Process', '📊'),
(449, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'A perfect positive correlation is:', '["2.00", "1.00", "0.10", "0.00"]'::jsonb, 1, 'Correlation coefficients range from −1 to +1. A perfect positive correlation is +1.00.', 'Research & Nursing Process', '📊'),
(450, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'All are criteria for judging the acceptability of a quantitative instrument EXCEPT:', '["Validity", "Reliability", "Durability", "Specificity"]'::jsonb, 2, 'An instrument is judged on validity, reliability, sensitivity and specificity. Durability is irrelevant.', 'Research & Nursing Process', '📊'),
(451, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Which is NOT a measure of dispersion?', '["Standard deviation", "Variance", "Mean", "Range"]'::jsonb, 2, 'Range, variance and standard deviation measure dispersion. The mean measures central tendency.', 'Research & Nursing Process', '📊'),
(452, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'The mode, as a measure of central tendency, is:', '["The arithmetic average", "The most frequent value", "The middle value", "All the values in a distribution"]'::jsonb, 1, 'The mode is the most frequently occurring value.', 'Research & Nursing Process', '📊'),
(453, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'At the ratio level of measurement, the most appropriate index of central tendency is usually the:', '["Mode", "Median", "Mean", "Range"]'::jsonb, 2, 'For interval or ratio data that are roughly symmetrical, the mean is the most appropriate measure of central tendency.', 'Research & Nursing Process', '📊'),
(454, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Which statement about longitudinal research design is NOT true?', '["It suits time-related processes", "It allows comparisons over time", "Data are collected more than once", "Data are collected only once"]'::jsonb, 3, 'Longitudinal designs collect data at several points over time. Collecting data once is cross-sectional.', 'Research & Nursing Process', '📊'),
(455, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Which is NOT a characteristic of experimental design?', '["Variation", "Manipulation", "Randomisation", "Control"]'::jsonb, 0, 'True experiments have manipulation, control and randomisation.', 'Research & Nursing Process', '📊'),
(456, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'The principle of respect for human dignity in research includes:', '["Honouring all agreements with participants", "Fair, non-discriminatory selection of participants", "The individual''s right to self-determination", "Participants'' access to research personnel"]'::jsonb, 2, 'Respect for human dignity covers self-determination (voluntary participation, withdrawal) and full disclosure. Fair selection falls under justice.', 'Research & Nursing Process', '📊'),
(457, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Which is true about haemophilia C?', '["It is known as Christmas disease", "It is due to factor IX deficiency", "It is due to factor VIII deficiency", "It is due to factor XI deficiency"]'::jsonb, 3, 'Haemophilia A is factor VIII deficiency, B (Christmas disease) is factor IX, and C is factor XI deficiency.', 'Laboratory Sciences & Haematology', '🔬'),
(458, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'The objective of medical management of angina is to:', '["Increase myocardial oxygen demand and increase supply", "Increase demand and decrease supply", "Decrease myocardial oxygen demand and increase supply", "Maintain the general circulation"]'::jsonb, 2, 'Angina treatment aims to reduce myocardial oxygen demand (beta blockers, nitrates) and increase supply (coronary dilation, revascularisation).', 'Cardiovascular', '🫀'),
(459, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'The following are symptoms of bradycardia EXCEPT:', '["Shortness of breath", "Nervousness, insomnia and sweating from hyperthyroidism", "Extreme fatigue", "A drop in blood pressure"]'::jsonb, 1, 'Bradycardia causes fatigue, dyspnoea, dizziness and hypotension. Hyperthyroidism causes TACHYcardia, nervousness and sweating.', 'Cardiovascular', '🫀'),
(460, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Clinical manifestations of ischaemic heart disease include all EXCEPT:', '["Haemodynamic instability", "Inadequate cardiac output", "An increase in coronary blood supply", "Heart failure"]'::jsonb, 2, 'Ischaemic heart disease is caused by REDUCED coronary blood supply. It can cause instability, low output, heart failure and sudden cardiac death.', 'Cardiovascular', '🫀'),
(461, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Excessive anticoagulation with bleeding due to warfarin can be reversed by:', '["Diuretics", "Vitamin K", "Protamine sulphate", "Aspirin"]'::jsonb, 1, 'Warfarin is reversed with vitamin K (phytomenadione), plus prothrombin complex concentrate or FFP for major bleeding.', 'ICU Pharmacology', '💊'),
(462, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'What name is given to the mechanical contraction of the heart?', '["Repolarisation", "Depolarisation", "Systole", "Diastole"]'::jsonb, 2, 'Systole is the mechanical contraction phase of the heart. Depolarisation is the electrical event that triggers it.', 'Cardiovascular', '🫀'),
(463, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'The ECG change typical of myocardial ischaemia is:', '["Appearance of Q waves", "ST-segment depression", "Widened QRS complex", "Inverted U wave"]'::jsonb, 1, 'Myocardial ischaemia typically causes ST-segment depression or T-wave inversion. Pathological Q waves indicate established infarction.', 'Cardiovascular', '🫀'),
(464, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'The following are true about normal cardiac conduction EXCEPT:', '["The AV node slows the impulse", "The cells depolarise and the ventricles then relax", "Electrical stimulation of ventricular cells causes contraction", "The impulse travels quickly from the SA node through the atria to the AV node"]'::jsonb, 1, 'Ventricular depolarisation leads to contraction (systole), not relaxation.', 'Cardiovascular', '🫀'),
(465, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Which HbA1c value indicates prediabetes?', '["6.5–7%", "5.7–6.4%", "5–5.6%", ">5.6%"]'::jsonb, 1, 'HbA1c: normal below 5.7%, prediabetes 5.7–6.4%, diabetes 6.5% or more.', 'GI, Endocrine & Metabolic', '🍽️'),
(466, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'In assessing a patient with impaired peripheral arterial circulation, all are appropriate findings to look for EXCEPT:', '["Brown pigmentation of the lower legs", "Pallor of the lower extremities", "Blanching of the feet after elevating the legs for 60 seconds", "Increased pulse volume in the leg arteries"]'::jsonb, 3, 'Peripheral arterial insufficiency causes pallor, elevation pallor, brown pigmentation and DIMINISHED pulses, never increased pulse volume.', 'Cardiovascular', '🫀'),
(467, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'NPH insulin is given at 07:30. When will it reach its peak effect?', '["11:30–13:30", "13:30–19:30", "15:30–21:30", "17:30–23:30"]'::jsonb, 1, 'NPH (intermediate) insulin peaks about 6–12 hours after injection, so a 07:30 dose peaks around 13:30–19:30.', 'ICU Pharmacology', '💊'),
(468, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'After a burn, a client has BP 70/40, HR 140, RR 25, pallor and weak pedal pulses. The nurse''s first action is to:', '["Start intravenous fluids", "Check pulses with a Doppler", "Obtain a complete blood count", "Obtain an ECG"]'::jsonb, 0, 'Hypotension, tachycardia, pallor and weak pulses after a burn mean hypovolaemic (burn) shock. Start IV fluid resuscitation first.', 'Burns & Trauma', '🔥'),
(469, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Which statement about pre-eclampsia is correct?', '["MgSO4 is used to lower blood pressure in emergencies", "It is mainly a disease of primigravidae", "Oedema is required for diagnosis", "BP >140/110 defines severe disease"]'::jsonb, 1, 'Pre-eclampsia is mainly a disease of first pregnancies (primigravidae). Oedema is no longer diagnostic; MgSO4 prevents fits but does not treat BP.', 'Obstetric & Neonatal', '🤱'),
(470, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Which is true about breastfeeding and contraception?', '["All oral contraceptives are contraindicated", "An IUCD can be inserted just after delivery", "Breastfeeding is highly effective once menses return", "Breastfeeding remains effective even with regular formula top-ups"]'::jsonb, 1, 'A postplacental IUCD (within 10 minutes of placental delivery) is safe and suits breastfeeding women. Progestin-only methods are also fine.', 'Obstetric & Neonatal', '🤱'),
(471, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'The most common presentation of a pre-eclamptic patient is:', '["No symptoms", "Abdominal pain", "Dyspareunia", "Convulsions"]'::jsonb, 0, 'Most women with pre-eclampsia have no symptoms. It is found by routine BP and urine checks, which is why antenatal screening matters.', 'Obstetric & Neonatal', '🤱'),
(472, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Which statement about hypertensive disorders of pregnancy is true?', '["Placental pathology is implicated in the aetiology of pre-eclampsia", "Gestational hypertension means any BP ≥140/90 at any time in pregnancy", "The Korotkoff V sound marks systolic pressure", "Prolonged barrier contraception is protective"]'::jsonb, 0, 'Abnormal placentation (poor spiral artery remodelling) is central to the cause of pre-eclampsia.', 'Obstetric & Neonatal', '🤱'),
(473, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Critical management of a woman with severe bleeding just after delivery includes:', '["A continuous IV infusion of high-dose oxytocin", "Setting up dextrose water as the main fluid", "Stopping all uterotonics", "Filling the bladder to stop bleeding"]'::jsonb, 0, 'For PPH from atony, give a continuous IV oxytocin infusion, massage the uterus, keep the bladder empty and replace volume.', 'Obstetric & Neonatal', '🤱'),
(474, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Which is true about vomiting in pregnancy?', '["Only a few cases resolve by the second trimester", "90% resolve only at about 32 weeks", "When another cause is found it is called hyperemesis", "It may start as early as 6 weeks'' gestation"]'::jsonb, 3, 'Nausea and vomiting in pregnancy usually starts at 4–6 weeks, peaks at 8–12 weeks and settles by about 16–20 weeks.', 'Obstetric & Neonatal', '🤱'),
(475, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'The most critical period of the puerperium is:', '["The whole 6 weeks equally", "The early (immediate) period", "The postnatal family-planning visit", "Active management of the third stage"]'::jsonb, 1, 'The first 24 hours (early puerperium) carry the highest risk of PPH, eclampsia and other complications.', 'Obstetric & Neonatal', '🤱'),
(476, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Which may be life-saving in managing severe pre-eclampsia?', '["Paracetamol for frontal headache in moderate disease", "Outpatient care when hyperreflexia appears", "Delivery, even at a very early gestational age", "Conservative management of imminent eclampsia at 29 weeks"]'::jsonb, 2, 'Delivery is the definitive cure for pre-eclampsia. In severe disease it may be needed even at an early gestation to save the mother.', 'Obstetric & Neonatal', '🤱'),
(477, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Concerning convulsions in eclampsia, which is correct?', '["Diazepam is the first-line anticonvulsant", "Strict monitoring of respiratory rate and urine output is essential", "After MgSO4 at 34 weeks the pregnancy should continue to 40 weeks", "The total MgSO4 loading dose is 15 g"]'::jsonb, 1, 'Magnesium is excreted by the kidneys and toxicity depresses breathing. Monitor respiratory rate, reflexes and urine output closely.', 'Obstetric & Neonatal', '🤱'),
(478, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'In the Pritchard regimen of MgSO4, which is correct?', '["2 g/hour IV works faster", "5 g is the total loading dose", "The maintenance dose is 5 g IM 4-hourly", "It is the only accepted regimen"]'::jsonb, 2, 'Pritchard regimen: 4 g IV plus 10 g IM loading (5 g each buttock), then 5 g IM every 4 hours into alternate buttocks.', 'Obstetric & Neonatal', '🤱'),
(479, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Concerning antepartum haemorrhage, which is correct?', '["Bleeding in placenta praevia is mainly maternal in origin", "APH is any vaginal bleeding from conception to delivery", "A cervical polyp is a direct placental cause", "APH prevents DIC"]'::jsonb, 0, 'Bleeding in placenta praevia is mainly maternal, from the placental bed as the lower segment stretches.', 'Obstetric & Neonatal', '🤱'),
(480, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Which diagnostic picture is correct?', '["A high-riding fetal head with a soft uterus and live fetus suggests placenta praevia", "Abruption is always associated with contractions", "A heavy show is the leading cause of APH", "An abnormal lie helps diagnose abruption"]'::jsonb, 0, 'A high presenting part, soft non-tender uterus and live fetus with painless bleeding suggests placenta praevia. Never do a digital vaginal exam.', 'Obstetric & Neonatal', '🤱'),
(481, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Management of hyperemesis gravidarum involves:', '["Nil by mouth until discharge", "Dextrose water as the preferred fluid", "Mandatory IM analgin", "Vitamin B6 combined with doxylamine"]'::jsonb, 3, 'Pyridoxine (B6) with doxylamine is an effective first-line antiemetic in pregnancy. IV fluids should be saline-based with thiamine, not plain dextrose.', 'Obstetric & Neonatal', '🤱'),
(482, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Management of the puerperium without breastfeeding includes:', '["Regular nipple stimulation", "No need for analgesia", "Mandatory bromocriptine", "Wearing a firm, supportive bra"]'::jsonb, 3, 'To suppress lactation without breastfeeding: a firm, supportive (tight) bra, cold compresses, analgesia and avoiding nipple stimulation.', 'Obstetric & Neonatal', '🤱'),
(483, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Which is a risk factor for pre-eclampsia?', '["Age 25 years", "Second pregnancy", "Breech presentation", "More than 10 years since the last pregnancy"]'::jsonb, 3, 'Pre-eclampsia risk factors include first pregnancy, age over 40, an interval of more than 10 years since the last pregnancy, multiple pregnancy, obesity and chronic hypertension.', 'Obstetric & Neonatal', '🤱'),
(484, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Hypothermia is a core body temperature below ___ °C.', '["37", "35", "32", "40"]'::jsonb, 1, 'Hypothermia is a core temperature below 35 °C.', 'Mixed Revision', '📚'),
(485, 'Post Basic CCN School Questions', 'School of Post Basic Critical Care Nursing question set (uploaded)', 'Which action best prevents heat loss by evaporation in a newborn?', '["Warming the crib pad", "Closing the doors to the room", "Drying the infant with a warm blanket", "Turning on the overhead radiant warmer"]'::jsonb, 2, 'Evaporative heat loss comes from wet skin. Drying the baby immediately with a warm towel prevents it.', 'Obstetric & Neonatal', '🤱'),
(486, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'The seminal vesicle measures about ______ in length.', '["4 cm", "5 cm", "3 cm", "10 cm"]'::jsonb, 1, 'Each seminal vesicle is a coiled sac about 5 cm long, lying behind the bladder. It contributes about 60–70% of semen volume.', 'Anatomy & Physiology', '🧬'),
(487, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'Which female structure is homologous to the male penis?', '["Ovary", "Vagina", "Clitoris", "Urethra"]'::jsonb, 2, 'The clitoris develops from the same embryonic tissue (genital tubercle) as the penis.', 'Anatomy & Physiology', '🧬'),
(488, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'The levator ani muscle consists of how many muscles?', '["2", "3", "4", "5"]'::jsonb, 1, 'The levator ani has three parts: pubococcygeus, puborectalis and iliococcygeus.', 'Anatomy & Physiology', '🧬'),
(489, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'The 6th cranial nerve is the:', '["Abducent nerve", "Trigeminal nerve", "Facial nerve", "Oculomotor nerve"]'::jsonb, 0, 'Cranial nerve VI, the abducent (abducens) nerve, supplies the lateral rectus, which abducts the eye.', 'Anatomy & Physiology', '🧬'),
(490, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'The isthmus of the uterus measures about:', '["7 cm", "7 m", "7 mm", "70 mm"]'::jsonb, 2, 'The isthmus is the narrow junction between the uterine body and cervix, about 7 mm long. It becomes the lower uterine segment in pregnancy.', 'Obstetric & Neonatal', '🤱'),
(491, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'The portion of the cervix that protrudes into the vagina is covered by:', '["Squamous epithelium", "Columnar epithelium", "Cuboidal epithelium", "Transitional epithelium"]'::jsonb, 0, 'The ectocervix, the part protruding into the vagina, is covered by stratified squamous epithelium. The endocervical canal is lined by columnar epithelium.', 'Anatomy & Physiology', '🧬'),
(492, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'The epithelial cells lining the endocervical canal are:', '["Tall and cuboidal", "Tall and columnar", "Tall and squamous", "Flat and transitional"]'::jsonb, 1, 'The endocervical canal is lined by tall, mucus-secreting columnar epithelium.', 'Anatomy & Physiology', '🧬'),
(493, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'The openings located on either side of the vaginal orifice are the:', '["Hymenal ducts", "Skene''s ducts", "Bartholin''s ducts", "Urethral meatus"]'::jsonb, 2, 'Bartholin''s (greater vestibular) gland ducts open on either side of the vaginal orifice. Skene''s ducts open beside the urethra.', 'Anatomy & Physiology', '🧬'),
(494, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'A gravid uterus at term weighs about:', '["1000 g", "60 g", "100 g", "500 g"]'::jsonb, 0, 'The non-pregnant uterus weighs about 60 g. At term it weighs about 1,000 g (1 kg).', 'Obstetric & Neonatal', '🤱'),
(495, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'The system that controls the major movements of the body is the:', '["Endocrine system", "Nervous system", "Skeletal system", "Digestive system"]'::jsonb, 1, 'The nervous system directs body movements through motor nerves to skeletal muscles.', 'Anatomy & Physiology', '🧬'),
(496, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'Neurones are also known as:', '["Ganglia", "Nerve cells", "Axons", "Glial cells"]'::jsonb, 1, 'Neurones are nerve cells, the functional units of the nervous system.', 'Anatomy & Physiology', '🧬'),
(497, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'The nervous system can inhibit or stimulate other systems in order to maintain:', '["Integration", "Mental balance", "Homeostasis", "Growth"]'::jsonb, 2, 'By stimulating or inhibiting other systems, the nervous system helps maintain homeostasis.', 'Anatomy & Physiology', '🧬'),
(498, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'The following are types of neurons EXCEPT:', '["Tripolar neurons", "Unipolar neurons", "Multipolar neurons", "Bipolar neurons"]'::jsonb, 0, 'Neurons are multipolar, bipolar or unipolar (pseudounipolar). There are no "tripolar" neurons.', 'Anatomy & Physiology', '🧬'),
(499, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'Most neurones in the CNS are:', '["Multipolar neurones", "Bipolar neurones", "Unipolar neurones", "Pseudounipolar neurones"]'::jsonb, 0, 'Most CNS neurons, including motor neurons and interneurons, are multipolar: one axon and many dendrites.', 'Anatomy & Physiology', '🧬'),
(500, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'Which statement best describes Schwann cells?', '["Small mobile cells", "Single cells surrounding (myelinating) axons", "Star-shaped cells", "Cells lining the ventricles"]'::jsonb, 1, 'A Schwann cell wraps around a single segment of one peripheral axon to form myelin. Astrocytes are the star-shaped cells.', 'Anatomy & Physiology', '🧬'),
(501, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'The part of the CNS housed within the cranial vault is the:', '["Brain", "Brainstem only", "Medulla oblongata only", "Spinal cord"]'::jsonb, 0, 'The brain lies within the cranial vault. The spinal cord lies in the vertebral canal.', 'Anatomy & Physiology', '🧬'),
(502, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'The most inferior portion of the brainstem is the:', '["Medulla oblongata", "Spinal cord", "Pons", "Midbrain"]'::jsonb, 0, 'The brainstem runs midbrain, pons, medulla (top to bottom). The medulla is the most inferior part and continues as the spinal cord.', 'Anatomy & Physiology', '🧬'),
(503, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'The olfactory nerve is responsible for:', '["Vision", "Smell", "Hearing", "Taste"]'::jsonb, 1, 'The olfactory nerve (CN I) carries the sense of smell.', 'Anatomy & Physiology', '🧬'),
(504, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'Which cranial nerve is the motor nerve to the tongue muscles?', '["Olfactory nerve", "Oculomotor nerve", "Hypoglossal nerve", "Glossopharyngeal nerve"]'::jsonb, 2, 'The hypoglossal nerve (CN XII) is the motor nerve to the tongue muscles.', 'Anatomy & Physiology', '🧬'),
(505, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'Which spinal nerves give rise to the cervical plexus?', '["C1–C4", "C5–T1", "C3–T3", "T1–T12"]'::jsonb, 0, 'The cervical plexus is formed by the anterior rami of C1–C4. C5–T1 form the brachial plexus.', 'Anatomy & Physiology', '🧬'),
(506, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'Which nerve innervates the diaphragm?', '["Radial nerve", "Median nerve", "Phrenic nerve", "Vagus nerve"]'::jsonb, 2, 'The phrenic nerve (C3–C5) supplies the diaphragm: "C3, 4, 5 keep the diaphragm alive".', 'Anatomy & Physiology', '🧬'),
(507, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'The olfactory tract terminates in which area of the brain?', '["Olfactory cortex", "Olfactory bulb", "Cribriform plate", "Visual cortex"]'::jsonb, 0, 'The olfactory tract carries impulses from the olfactory bulb to the primary olfactory cortex in the temporal lobe.', 'Anatomy & Physiology', '🧬'),
(508, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'Pallor can be checked from the:', '["Iris", "Conjunctiva", "Sclera", "Cornea"]'::jsonb, 1, 'Pallor is best checked in the palpebral conjunctiva, nail beds and palms.', 'Mixed Revision', '📚'),
(509, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'The part of the ear that functions in both hearing and balance is the:', '["Outer ear", "Middle ear", "Inner ear", "Eustachian tube"]'::jsonb, 2, 'The inner ear holds the cochlea (hearing) and the vestibular apparatus (balance).', 'Anatomy & Physiology', '🧬'),
(510, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'The bony labyrinth is found in the:', '["Auricle", "Inner ear", "Middle ear", "External auditory canal"]'::jsonb, 1, 'The bony labyrinth (cochlea, vestibule, semicircular canals) lies in the inner ear within the temporal bone.', 'Anatomy & Physiology', '🧬'),
(511, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'Gerontology is defined as:', '["A field of nursing practice", "Categorised care of patients", "The scientific study of the ageing process", "The treatment of diseases of old age"]'::jsonb, 2, 'Gerontology is the scientific study of ageing. Geriatrics is the medical care of older people.', 'Mixed Revision', '📚'),
(512, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'Abdominal thrusts are used in first aid for victims of:', '["Choking and airway blockage", "Gas poisoning", "Drowning", "Hypothermia"]'::jsonb, 0, 'Abdominal thrusts (Heimlich manoeuvre) relieve foreign-body airway obstruction (choking) in conscious adults and children over 1 year.', 'Mixed Revision', '📚'),
(513, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'Geriatric syndromes include all EXCEPT:', '["Abdominal distension", "Increased susceptibility to infection", "Impaired mobility", "Falls"]'::jsonb, 0, 'The geriatric syndromes are falls, impaired mobility, incontinence, delirium/confusion, pressure ulcers and infections. Abdominal distension is not one.', 'Mixed Revision', '📚'),
(514, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'The following are anti-anxiety agents EXCEPT:', '["Propranolol", "Trazodone", "Buspirone", "Diazepam"]'::jsonb, 1, 'Buspirone, benzodiazepines and propranolol (for physical symptoms) are used for anxiety. Trazodone is mainly an antidepressant and hypnotic.', 'ICU Pharmacology', '💊'),
(515, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'Nursing roles in psychiatric home care should be determined mainly by:', '["The nurse''s education, experience and ability", "The physician''s order only", "Organisational policies alone", "The family''s wishes alone"]'::jsonb, 0, 'The nurse''s role in psychiatric home care depends on their education, experience and ability, within agency policy.', 'Mixed Revision', '📚'),
(516, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'Metastasis of cancer cells occurs through the following routes EXCEPT:', '["Lymphatics", "Haematogenous routes", "Specific affinity", "Transcoelomic seeding"]'::jsonb, 2, 'Cancer spreads by lymphatics, the bloodstream (haematogenous) and transcoelomic seeding. "Specific affinity" is not a route of spread.', 'Mixed Revision', '📚'),
(517, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'A common procedure for destroying small basal and squamous cell skin cancers is:', '["Electrosurgery (electrodesiccation and curettage)", "Laser surgery only", "Radiofrequency ablation", "Systemic chemotherapy"]'::jsonb, 0, 'Small basal and squamous cell skin cancers are often destroyed by electrosurgery (electrodesiccation and curettage).', 'Mixed Revision', '📚'),
(518, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'The commonest complaints of a client with a female reproductive disorder include the following EXCEPT:', '["Discharge", "Tenesmus", "Bleeding", "Pelvic pain"]'::jsonb, 1, 'Female reproductive complaints are typically discharge, bleeding and pelvic pain. Tenesmus is a rectal symptom.', 'Obstetric & Neonatal', '🤱'),
(519, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'The drug of choice for intermittent preventive treatment of malaria in pregnancy is:', '["Artesunate", "Sulfadoxine–pyrimethamine", "Quinine", "Chloroquine"]'::jsonb, 1, 'Intermittent preventive treatment of malaria in pregnancy (IPTp) uses sulfadoxine–pyrimethamine from the second trimester.', 'Obstetric & Neonatal', '🤱'),
(520, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'Which of these is NOT a qualitative variable?', '["Age", "Sex", "Marital status", "Religion"]'::jsonb, 0, 'Age is a quantitative variable. Sex and marital status are qualitative (categorical).', 'Research & Nursing Process', '📊'),
(521, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'The lowest measurement scale in statistics is the:', '["Ordinal scale", "Nominal scale", "Ratio scale", "Interval scale"]'::jsonb, 1, 'The levels of measurement, lowest to highest, are nominal, ordinal, interval and ratio.', 'Research & Nursing Process', '📊'),
(522, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'A population that consists of an endless succession of values is:', '["Infinite", "Definitive", "Finite", "A sample"]'::jsonb, 0, 'A population with an endless (uncountable) succession of values is infinite.', 'Research & Nursing Process', '📊'),
(523, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'Assigning numbers to objects or events according to a set of rules is termed:', '["Numbering", "Measurement", "Observation", "Sampling"]'::jsonb, 1, 'Measurement is assigning numbers to objects or events according to rules.', 'Research & Nursing Process', '📊'),
(524, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'A test that shows positive when the true status is negative gives a:', '["True positive", "False negative", "False positive", "True negative"]'::jsonb, 2, 'A false positive is a positive test result when the true status is negative.', 'Research & Nursing Process', '📊'),
(525, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'A safe way to open the airway of a patient with suspected spinal injury is the:', '["Head-tilt chin-lift manoeuvre", "Jaw-thrust manoeuvre", "Heimlich manoeuvre", "Recovery position"]'::jsonb, 1, 'With suspected spinal injury, open the airway with a jaw thrust, which keeps the neck in line. Avoid head tilt.', 'Burns & Trauma', '🔥'),
(526, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'The additional cost of producing one extra unit of a good is the:', '["Marginal cost", "Opportunity cost", "Unit cost", "Fixed cost"]'::jsonb, 0, 'Marginal cost is the extra cost of producing or consuming one more unit.', 'Mixed Revision', '📚'),
(527, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'The satisfaction gained from consuming goods or services is termed:', '["Utility", "Fulfilment", "Contentment", "Demand"]'::jsonb, 0, 'In economics, utility is the satisfaction gained from consuming goods or services.', 'Mixed Revision', '📚'),
(528, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'Nigeria''s first case of COVID-19 was recorded on:', '["27 February 2020", "27 January 2020", "27 March 2020", "27 April 2020"]'::jsonb, 0, 'Nigeria''s first COVID-19 case (an Italian traveller in Lagos) was confirmed on 27 February 2020.', 'Infection Prevention', '🦠'),
(529, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'The disease COVID-19 was officially named on:', '["11 February 2020", "13 February 2020", "13 March 2020", "31 December 2019"]'::jsonb, 0, 'WHO named the disease "COVID-19" on 11 February 2020.', 'Infection Prevention', '🦠'),
(530, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'COVID-19 was declared a pandemic on:', '["13 March 2020", "11 March 2020", "27 March 2020", "30 January 2020"]'::jsonb, 1, 'WHO declared COVID-19 a pandemic on 11 March 2020, after declaring a PHEIC on 30 January 2020.', 'Infection Prevention', '🦠'),
(531, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'PHEIC means:', '["Public health education and international concern", "Public health emergency of international concern", "Public health and environmental inspection and communication", "Primary health emergency in an infected country"]'::jsonb, 1, 'PHEIC is a Public Health Emergency of International Concern, declared by WHO under the International Health Regulations.', 'Infection Prevention', '🦠'),
(532, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'The full meaning of GNP is:', '["Global national product", "Gross national product", "Grand national product", "General national price"]'::jsonb, 1, 'GNP is Gross National Product: the value of goods and services produced by a country''s residents, at home and abroad.', 'Mixed Revision', '📚'),
(533, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'The demand for health care is often described as:', '["Grand demand", "Derived demand", "Elastic demand", "Joint supply"]'::jsonb, 1, 'Demand for health care is a derived demand: people want health, and health care is the means to it.', 'Mixed Revision', '📚'),
(534, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'Flushing a wound with a large amount of sterile fluid is termed:', '["Wound dressing", "Wound cleansing", "Wound irrigation", "Debridement"]'::jsonb, 2, 'Wound irrigation flushes a wound with a large volume of sterile fluid to remove debris and bacteria.', 'Mixed Revision', '📚'),
(535, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'The composition and volume of body fluids are regulated primarily by the:', '["Lungs", "Heart", "Kidneys", "Skin"]'::jsonb, 2, 'The kidneys are the main regulators of body fluid volume and composition.', 'Renal & Fluid Balance', '💧'),
(536, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'Submerging a client''s perineal area in warm water is called a:', '["Suppository", "Sitz bath", "Perineal irrigation", "Hot compress"]'::jsonb, 1, 'A sitz bath means sitting with the perineum immersed in warm water to relieve pain and swelling and promote healing.', 'Mixed Revision', '📚'),
(537, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'The stage after death marked by stiffness of the muscles due to chemical changes is:', '["Algor mortis", "Livor mortis", "Rigor mortis", "Cessational stiffness"]'::jsonb, 2, 'Rigor mortis is post-mortem muscle stiffening from ATP depletion. Algor mortis is cooling and livor mortis is pooling of blood.', 'Mixed Revision', '📚'),
(538, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'The stimulus–response (classical conditioning) theory was propounded by:', '["Pavlov", "Bruner", "Piaget", "Maslow"]'::jsonb, 0, 'Ivan Pavlov''s classical conditioning is the basis of stimulus–response learning theory.', 'Research & Nursing Process', '📊'),
(539, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'Florence Nightingale was born on:', '["12 May 1820", "13 August 1910", "12 May 1810", "12 May 1830"]'::jsonb, 0, 'Florence Nightingale was born on 12 May 1820 in Florence, Italy. International Nurses Day is celebrated on her birthday.', 'Research & Nursing Process', '📊'),
(540, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'HMO means:', '["Health management organisation", "Health maintenance organisation", "Health and medical organisation", "Hospital management office"]'::jsonb, 1, 'An HMO (Health Maintenance Organisation) manages health insurance enrollees and pays providers, e.g. under the NHIS.', 'Mixed Revision', '📚'),
(541, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'At the base of Maslow''s hierarchy of needs are:', '["Physiological needs", "Safety and security", "Love and belonging", "Self-actualisation"]'::jsonb, 0, 'Physiological needs (air, food, water, sleep) form the base of Maslow''s pyramid.', 'Research & Nursing Process', '📊'),
(542, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'A demand schedule refers to:', '["A list of the quantities of a good demanded at particular prices", "The quantity consumers are willing to buy at a particular time", "A graph showing price against quantity demanded", "A list of suppliers"]'::jsonb, 0, 'A demand schedule is a table of the quantities of a good demanded at different prices.', 'Mixed Revision', '📚'),
(543, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'A fixed monthly payment from HMOs to providers for each NHIS enrollee is called:', '["Capitation", "Fee for service", "Per diem", "Co-payment"]'::jsonb, 0, 'Under capitation, HMOs pay providers a fixed amount per enrolled person per month, however many services are used.', 'Mixed Revision', '📚'),
(544, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'GDP means:', '["Grand domestic product", "Gross domestic product", "Government development programme", "General domestic price"]'::jsonb, 1, 'GDP (Gross Domestic Product) is the total value of goods and services produced within a country.', 'Mixed Revision', '📚'),
(545, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'Polycythaemia is best classified as:', '["Primary and secondary", "Acute and chronic", "Morbid and premorbid", "Benign and malignant"]'::jsonb, 0, 'Polycythaemia is primary (polycythaemia vera, a marrow disorder) or secondary (raised EPO from hypoxia, tumours). Relative polycythaemia is due to low plasma volume.', 'Laboratory Sciences & Haematology', '🔬'),
(546, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'Drugs that suppress or relieve coughing without necessarily treating the cause are:', '["Antibiotics", "Antitussive agents", "Expectorants", "Bronchodilators"]'::jsonb, 1, 'Antitussives suppress the cough reflex without treating the underlying cause.', 'ICU Pharmacology', '💊'),
(547, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'Types or stages of sleep include all EXCEPT:', '["Rapid eye movement (REM) sleep", "Non-eye-movement sleep", "Non-rapid eye movement (NREM) sleep", "Slow-wave sleep"]'::jsonb, 1, 'The two types of sleep are REM and non-REM (NREM). Slow-wave sleep is a stage of NREM. There is no "non-eye-movement sleep".', 'Anatomy & Physiology', '🧬'),
(548, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'Venous drainage of the heart is mainly through the:', '["Coronary arteries", "Cardiac veins draining into the coronary sinus", "Pulmonary veins", "Superior vena cava directly"]'::jsonb, 1, 'Most venous blood from the heart drains through the cardiac veins into the coronary sinus, which opens into the right atrium.', 'Anatomy & Physiology', '🧬'),
(549, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'Murophobia refers to fear of:', '["Humans", "Rats and mice", "Bats", "Heights"]'::jsonb, 1, 'Murophobia (musophobia) is fear of mice or rats.', 'Mixed Revision', '📚'),
(550, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'Chiroptophobia is fear of:', '["Bats", "Light", "Animals in general", "Dogs"]'::jsonb, 0, 'Chiroptophobia is fear of bats (the order Chiroptera).', 'Mixed Revision', '📚'),
(551, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'Who is called the father of scientific management?', '["Thomas Jefferson", "Frederick Taylor", "Ivan Pavlov", "Jean Piaget"]'::jsonb, 1, 'Frederick W. Taylor is called the father of scientific management. Fayol is the father of modern (administrative) management.', 'Ethics, Law & Management', '⚖️'),
(552, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'The first important activity of management is:', '["Organising", "Staffing", "Budgeting", "Planning"]'::jsonb, 3, 'Planning comes first: it sets objectives and how to reach them, and all other functions follow from it.', 'Ethics, Law & Management', '⚖️'),
(553, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'Which function involves designing the formal structure of authority among subdivisions and sections towards organisational goals?', '["Directing", "Planning", "Organising", "Budgeting"]'::jsonb, 2, 'Organising designs the formal structure of authority, roles and relationships among departments to achieve goals.', 'Ethics, Law & Management', '⚖️'),
(554, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'Harmonising the parts of the work and removing overlapping and conflicting activities is:', '["Planning", "Coordinating", "Organising", "Directing"]'::jsonb, 1, 'Coordination harmonises the various parts of the work and removes overlap and conflict.', 'Ethics, Law & Management', '⚖️'),
(555, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'Who advocated the fourteen principles of management?', '["Henri Fayol", "Frederick Taylor", "Max Weber", "Karl Marx"]'::jsonb, 0, 'Henri Fayol proposed the 14 principles of management.', 'Ethics, Law & Management', '⚖️'),
(556, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'According to Maslow''s hierarchy, the most basic needs are:', '["Safety and security needs", "Self-actualisation needs", "Physiological needs", "Social needs"]'::jsonb, 2, 'Physiological needs are the most basic in Maslow''s hierarchy.', 'Research & Nursing Process', '📊'),
(557, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'The highest need in Maslow''s hierarchy is:', '["Safety and security", "Self-actualisation", "Social needs", "Esteem needs"]'::jsonb, 1, 'Self-actualisation, reaching one''s full potential, is at the top of Maslow''s hierarchy.', 'Research & Nursing Process', '📊'),
(558, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'Bureaucracy as an organisational model was developed by:', '["Henri Fayol", "Karl Marx", "Max Weber", "Frederick Taylor"]'::jsonb, 2, 'Max Weber developed the bureaucratic model of organisation: hierarchy, rules, division of labour and impersonality.', 'Ethics, Law & Management', '⚖️'),
(559, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'Which is NOT one of Fayol''s 14 principles of management?', '["Subordination of individual interests", "Remuneration", "Decentralisation", "Scalar chain (clear line of authority)"]'::jsonb, 2, 'Fayol''s principles include subordination of individual interest, remuneration and the scalar chain (clear line of authority). His principle is centralisation, not decentralisation.', 'Ethics, Law & Management', '⚖️'),
(560, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'Entrusting part of a superior''s work to subordinates is called:', '["Transfer", "Delegation", "Supervision", "Directing"]'::jsonb, 1, 'Delegation is entrusting part of a superior''s work, with authority, to a subordinate. Accountability stays with the superior.', 'Ethics, Law & Management', '⚖️'),
(561, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'The major components of a lesson plan include the following EXCEPT:', '["Introduction", "Summary", "Presentation", "Denotation"]'::jsonb, 3, 'A lesson plan has an introduction, a presentation (development) and a summary/conclusion. "Denotation" is not a component.', 'Mixed Revision', '📚'),
(562, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'Which teaching method involves showing by example, proof, movement and experiments?', '["Discussion", "Demonstration", "Field trip", "Inquiry"]'::jsonb, 1, 'The demonstration method teaches by showing, through examples, procedures, experiments and explanation.', 'Mixed Revision', '📚'),
(563, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'The variable that the researcher manipulates (the cause or treatment) is the:', '["Dependent variable", "Extraneous variable", "Independent variable", "External variable"]'::jsonb, 2, 'The independent variable is manipulated by the researcher: the presumed cause, stimulus or treatment.', 'Research & Nursing Process', '📊'),
(564, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'Which variable is NOT manipulated by the researcher but measured as the outcome?', '["Extraneous variable", "Independent variable", "Dependent variable", "Internal variable"]'::jsonb, 2, 'The dependent variable is measured, not manipulated. It is the outcome or effect.', 'Research & Nursing Process', '📊'),
(565, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'A research question should have the following characteristics EXCEPT:', '["It contains one or more variables", "It is clear and specific", "It is realistic", "It is not interrogative and is stated in the present tense"]'::jsonb, 3, 'A research question should be clear, specific and realistic, include the variables, and be written as a question (interrogative).', 'Research & Nursing Process', '📊'),
(566, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'A way of organising available concepts and phenomena to explain or predict occurrences is the:', '["Theoretical framework", "Conceptual framework", "Research design", "Research framework"]'::jsonb, 1, 'A conceptual framework organises concepts and their relationships to explain or predict phenomena.', 'Research & Nursing Process', '📊'),
(567, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'Which is NOT a probability sampling method?', '["Simple random sampling", "Cluster sampling", "Stratified random sampling", "Convenience sampling"]'::jsonb, 3, 'Convenience sampling is non-probability. Simple random, cluster and stratified sampling give every unit a known chance of selection.', 'Research & Nursing Process', '📊'),
(568, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'Which is NOT a non-probability sampling method?', '["Simple random sampling", "Purposive sampling", "Quota sampling", "Convenience sampling"]'::jsonb, 0, 'Simple random sampling is a probability method. Purposive, quota and convenience sampling are non-probability.', 'Research & Nursing Process', '📊'),
(569, 'Nursing Mock Examination', 'Nursing Mock Examination (uploaded)', 'Which is NOT a type of validity?', '["Face validity", "Content validity", "Unpredictable validity", "Construct validity"]'::jsonb, 2, 'Types of validity include face, content, construct and criterion (predictive/concurrent). "Unpredictable validity" does not exist.', 'Research & Nursing Process', '📊'),
(570, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Which one of the following statements is not correct?', '["Management is a goal-oriented process.", "Management is a continuous process.", "Management is a dynamic process.", "Management is a rigid process."]'::jsonb, 3, 'Management is goal-oriented, continuous and dynamic: it adapts to change rather than being rigid.', 'Ethics, Law & Management', '⚖️'),
(571, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Which one of the following is not an importance of management?', '["Integrating various interest groups", "Developing society", "Disciplining employees", "Inculcating creativity"]'::jsonb, 2, 'Management integrates interest groups, helps develop society and encourages creativity. Disciplining employees is a narrow activity, not a broad importance.', 'Ethics, Law & Management', '⚖️'),
(572, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Management is not', '["an applied science.", "a pure science.", "an art.", "an art and science both."]'::jsonb, 1, 'Management is an applied (inexact) science and an art. It is not a pure science like physics.', 'Ethics, Law & Management', '⚖️'),
(573, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'In which category does management fall?', '["Well-established profession", "Semi-profession", "Emerging profession", "Marginal profession"]'::jsonb, 2, 'Management lacks some features of a full profession (such as compulsory licensing), so it is regarded as an emerging profession.', 'Ethics, Law & Management', '⚖️'),
(574, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Top management is concerned with formulation of', '["guidelines for supervisors.", "long-term plans.", "short-term plans.", "None of these."]'::jsonb, 1, 'Top management sets objectives and long-term plans and strategies.', 'Ethics, Law & Management', '⚖️'),
(575, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Coordination is', '["a management function.", "the essence of management.", "an objective of management.", "a social objective."]'::jsonb, 1, 'Coordination runs through every function, so it is called the essence of management.', 'Ethics, Law & Management', '⚖️'),
(576, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'The element that aims at integrating group efforts to achieve group objectives is called ___.', '["Cooperation", "Coordination", "Management", "Directing"]'::jsonb, 1, 'Coordination integrates group efforts so the group achieves its objectives.', 'Ethics, Law & Management', '⚖️'),
(577, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Managing Director is the position of ___ level of management in a large company.', '["Top", "Middle", "Lower", "Middle and Lower"]'::jsonb, 0, 'The Managing Director belongs to top-level management.', 'Ethics, Law & Management', '⚖️'),
(578, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Management is multidimensional because it has ___ dimension(s).', '["One", "Two", "Three", "Four"]'::jsonb, 2, 'Management has three dimensions: managing work, managing people and managing operations.', 'Ethics, Law & Management', '⚖️'),
(579, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Management is a ___ directed process as it aims at achieving specified goals.', '["Continuously", "Future", "Goal", "Deliberately"]'::jsonb, 2, 'Management is goal-directed: every activity aims at specified goals.', 'Ethics, Law & Management', '⚖️'),
(580, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', '___ is a systematised body of knowledge that explains certain general truths or operation of general laws.', '["Science", "Art", "Profession", "Art and Profession both"]'::jsonb, 0, 'Science is a systematised body of knowledge explaining general truths through cause-and-effect principles.', 'Ethics, Law & Management', '⚖️'),
(581, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Identify the feature of co-ordination being highlighted in the given statement: “Coordination is not a one time function, it begins at the planning stage and continue till controlling.”', '["Coordination ensures unity of action", "Coordination is an all pervasive function", "Coordination is a continuous process", "Coordination is a deliberate function"]'::jsonb, 2, 'Coordination is continuous: it starts at planning and runs through to controlling.', 'Ethics, Law & Management', '⚖️'),
(582, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Co-ordination is considered to be the essence of management because', '["It is a common thread that runs through all the activities within the organisation", "It is implicit and inherent in all functions of the organisation", "It is a force that binds all the functions of management", "All of the above"]'::jsonb, 3, 'Coordination is the common thread through all activities, is built into every function and binds them together.', 'Ethics, Law & Management', '⚖️'),
(583, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'This function of Management related to placing the right person at the right job is', '["Organising", "Staffing", "Planning", "Controlling"]'::jsonb, 1, 'Staffing places the right person in the right job: recruitment, selection, placement and training.', 'Ethics, Law & Management', '⚖️'),
(584, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'This function of management relating to laying down the foundation for carrying out the other functions of management successfully is', '["Organising", "Staffing", "Planning", "Controlling"]'::jsonb, 2, 'Planning lays the foundation for all the other management functions.', 'Ethics, Law & Management', '⚖️'),
(585, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Organising as a function of management involves deciding', '["What activities and resources are required", "Who will do a particular task", "Where will it be done", "All of the above"]'::jsonb, 3, 'Organising decides what is to be done, who does it, where, and with what resources.', 'Ethics, Law & Management', '⚖️'),
(586, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'The main task of this level of management is to determine the overall organisational objectives and strategies for their realisation.', '["Operational management", "Middle level management", "First line managers", "Top level management"]'::jsonb, 3, 'Top-level management sets overall objectives and strategies.', 'Ethics, Law & Management', '⚖️'),
(587, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Which of the following statements is not true for lower level management?', '["Analyse the business environment and its implications for the survival of the business.", "Ensure the quality of the output", "They strive to reduce the wastage of resources", "They ensure that the safety standards are maintained within the organisation."]'::jsonb, 0, 'Analysing the business environment is a top-management task. Lower-level managers ensure quality, cut waste and keep safety standards.', 'Ethics, Law & Management', '⚖️'),
(588, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Which of the following is a function of top level management?', '["Ensuring quality of output", "Assigning necessary duties and responsibilities to their departments", "Taking responsibility for all the activities of the business and its impact on the society", "Ensuring that the safety standards are maintained within the organisation."]'::jsonb, 2, 'Top management is responsible for all the activities of the business and its impact on society. Quality and safety on the floor belong to lower levels.', 'Ethics, Law & Management', '⚖️'),
(589, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Which of the following is not a designation related to middle level management?', '["Operations Head", "Sales Manager", "Chief Operating Officer", "Divisional Manager"]'::jsonb, 2, 'The COO is a top-level post. Operations heads, sales managers and divisional managers are middle level.', 'Ethics, Law & Management', '⚖️'),
(590, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Successful organisations do not achieve goals by chance but by following a deliberate process known as', '["Planning", "Co-ordination", "Controlling", "Management"]'::jsonb, 3, 'Organisations achieve goals through a deliberate process called management.', 'Ethics, Law & Management', '⚖️'),
(591, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Management is essential for the organisations which are', '["Non-profit organisations", "Service organisations", "Social organisations", "All of the above"]'::jsonb, 3, 'Every organisation needs management, whether profit, non-profit, service or social.', 'Ethics, Law & Management', '⚖️'),
(592, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'People in the organisations carry out diverse tasks with the aim to achieve.', '["Different objectives", "Common objectives", "Both of the above", "None of the above"]'::jsonb, 1, 'People in an organisation do different tasks towards common objectives.', 'Ethics, Law & Management', '⚖️'),
(593, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Successful management ensures that', '["Goals are achieved with least cost", "Timely achievement of goals", "Both of the above", "None of the above"]'::jsonb, 2, 'Successful management achieves goals on time and at the least cost.', 'Ethics, Law & Management', '⚖️'),
(594, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Efficiency is concerned with', '["Doing the right thing", "Doing things right", "Achieving end results", "None of the above"]'::jsonb, 1, 'Efficiency is doing things right: getting the best output for the least input.', 'Ethics, Law & Management', '⚖️'),
(595, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Management is said to be poor if it is', '["Efficient but ineffective", "Effective but inefficient", "Both inefficient and ineffective", "All of the above"]'::jsonb, 2, 'Management is poor when it is both inefficient (wastes resources) and ineffective (misses goals).', 'Ethics, Law & Management', '⚖️'),
(596, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Which one of the following is not an economic objective of the business:-', '["Social environment", "Survival", "Profit", "Growth"]'::jsonb, 0, 'Survival, profit and growth are economic objectives. The social environment relates to social objectives.', 'Ethics, Law & Management', '⚖️'),
(597, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Which factor doesn’t describe management as science:-', '["Systematized body of knowledge", "Universal validity", "Ethical code of conduct", "Principles based on experimentation"]'::jsonb, 2, 'Management as a science has a systematised body of knowledge, principles from experimentation and universal validity. An ethical code of conduct is a feature of a profession.', 'Ethics, Law & Management', '⚖️'),
(598, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Which of the following management functions are closely related?', '["planning and organizing", "staffing and control", "planning and control", "planning and staffing"]'::jsonb, 2, 'Planning and controlling are inseparable: plans set the standards that control measures against.', 'Ethics, Law & Management', '⚖️'),
(599, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'The last function in the sequence, which culminates in the attainment of organization objectives, is:', '["organizing", "coordinating", "controlling", "planning"]'::jsonb, 2, 'Controlling is the final function in the cycle; it checks whether objectives have been achieved.', 'Ethics, Law & Management', '⚖️'),
(600, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'In terms of the sequential relationship, the first function requiring managerial attention is:', '["planning", "coordinates", "directing", "controlling"]'::jsonb, 0, 'Planning is the first management function in sequence.', 'Ethics, Law & Management', '⚖️'),
(601, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Control function of management cannot be performed without:', '["planning", "organizing", "staffing", "motivation"]'::jsonb, 0, 'Control cannot work without planning, because plans supply the standards performance is measured against.', 'Ethics, Law & Management', '⚖️'),
(602, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Which level of management is responsible for establishing a vision for the organization, developing broad plans and strategies, and directing subordinate managers?', '["first level managers", "middle managers", "executive managers", "second level managers"]'::jsonb, 2, 'Top or executive managers set the vision and broad strategies and direct the managers below them.', 'Ethics, Law & Management', '⚖️'),
(603, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Which level of management is responsible for implementing programs that are intended to carry out the broader objectives of an organization set by executives?', '["supervisory managers", "middle managers", "first level managers", "chief financial managers"]'::jsonb, 1, 'Middle managers carry out programmes to achieve the broad objectives set by top executives.', 'Ethics, Law & Management', '⚖️'),
(604, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Which of the following characterize a manager as being efficient?', '["They use a minimum amount of resources for the amount of outputs produced.", "The devote a large amount of time to planning", "They achieve their goals.", "They interview, select, and train people who are most suitable to fill open jobs."]'::jsonb, 0, 'Efficiency means using the fewest resources for a given output.', 'Ethics, Law & Management', '⚖️'),
(605, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Which of the following characterize a manager as being effective?', '["They use a minimum amount of resources for the amount of outputs produced.", "They devote a large amount of time to planning.", "They achieve their goals.", "They interview, select, and train people who are most suitable to fill open jobs."]'::jsonb, 2, 'Effectiveness means achieving the goals.', 'Ethics, Law & Management', '⚖️'),
(606, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Which term best describes the process of obtaining, deploying, and utilizing a variety of essential resources to contribute to an organization’s success?', '["planning", "organizing", "staffing", "management"]'::jsonb, 3, 'Management is obtaining, deploying and using resources to achieve organisational goals.', 'Ethics, Law & Management', '⚖️'),
(607, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Find the odd one out', '["board of directors", "chief executive", "foremen", "shareholders"]'::jsonb, 2, 'Foremen are lower-level (supervisory) management. The others relate to the top level.', 'Ethics, Law & Management', '⚖️'),
(608, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Management is a -----Activity.', '["single", "group", "both group and single", "None"]'::jsonb, 1, 'Management is a group activity: it coordinates the efforts of many people.', 'Ethics, Law & Management', '⚖️'),
(609, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Under mechanism of scientific management, scientific task setting includes:', '["Time study", "Motion study", "Method study", "All of the above"]'::jsonb, 3, 'Taylor''s scientific task setting uses time, motion and method studies to fix a fair day''s work.', 'Ethics, Law & Management', '⚖️'),
(610, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Fedrick Winslow Taylor’s Mechanism of Scientific Management includes', '["Scientific task setting", "Planning the task", "Standardization of tools and equipments", "All of the above"]'::jsonb, 3, 'Taylor''s mechanism includes scientific task setting, work planning, standardisation of tools, scientific selection and training, and differential pay.', 'Ethics, Law & Management', '⚖️'),
(611, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Frederick Winslow Taylor is best known for the introduction of which approach to job design?', '["Behavioural approach", "Ergonomics", "Scientific management", "Division of labour"]'::jsonb, 2, 'F. W. Taylor introduced scientific management to job design.', 'Ethics, Law & Management', '⚖️'),
(612, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Scientific management is comprised of which of the following two elements?', '["Technology assessment and environmental design", "Method study and work measurement", "Method study and job design", "Work measurement and job design"]'::jsonb, 1, 'Scientific management (work study) is made up of method study and work measurement.', 'Ethics, Law & Management', '⚖️'),
(613, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'The ‘father’ of Scientific Management is:', '["Henry Gantt", "W. Edwards Deming", "Henry Ford", "Frederick W. Taylor"]'::jsonb, 3, 'Frederick W. Taylor is the father of scientific management.', 'Ethics, Law & Management', '⚖️'),
(614, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Who was the first to formalise the concept of the division of labour?', '["Edward Demming, 1950", "Adam Smith, 1776", "Fredrick Taylor, 1911", "Jay Forester, 1963"]'::jsonb, 1, 'Adam Smith formalised division of labour in The Wealth of Nations (1776), with his pin-factory example.', 'Ethics, Law & Management', '⚖️'),
(615, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Henry Fayol was a', '["Social scientists", "Mining engineer", "Accountant", "Production engineer"]'::jsonb, 1, 'Henri Fayol was a French mining engineer who became managing director of a mining company.', 'Ethics, Law & Management', '⚖️'),
(616, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Which of the following is a TECHNIQUE (not a principle) of Taylor''s scientific management?', '["Science, not rule of Thumb", "Functional foremanship", "Maximum ,not restricted output", "Harmony not discord"]'::jsonb, 1, 'Taylor''s principles are science not rule of thumb, harmony not discord, cooperation not individualism, and development of each person to greatest efficiency (maximum output). Functional foremanship is one of his techniques, not a principle.', 'Ethics, Law & Management', '⚖️'),
(617, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Management should find '' One best way '' to perform a task. Which technique of scientific management is defined in this sentence?', '["Time study", "Motion study", "Fatigue study", "Method study"]'::jsonb, 3, 'Method study finds the "one best way" of doing a job.', 'Ethics, Law & Management', '⚖️'),
(618, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Who is known as ''the Father of Modern Theory of Management’?', '["Harold Koontz.", "Henry Fayol", "F.W. Taylor", "Max Weber"]'::jsonb, 1, 'Henri Fayol is the father of modern (administrative) management theory.', 'Ethics, Law & Management', '⚖️'),
(619, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'The main aim of Taylor was to.................', '["improve labour relations", "improve productivity", "To attempt a general theory of management", "None of these"]'::jsonb, 1, 'Taylor''s main aim was higher productivity through scientific methods.', 'Ethics, Law & Management', '⚖️'),
(620, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Henry fayol is well known...........', '["As the father of modern management", "for formulating general principles of management", "for promoting trade unionism", "None of these"]'::jsonb, 0, 'Fayol is known as the father of modern management and for his 14 general principles.', 'Ethics, Law & Management', '⚖️'),
(621, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Unity of command implies', '["A subordinate should receive orders from all the superiors", "individuals must sacrifice in the larger interest", "be accountable to one and only one superior", "None of these"]'::jsonb, 2, 'Unity of command: each employee takes orders from, and is accountable to, only one superior.', 'Ethics, Law & Management', '⚖️'),
(622, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Purpose of time study is ...........', '["to remove wastage of time", "to give timely assistance", "to determine fair days work", "watching time"]'::jsonb, 2, 'Time study sets the standard time for a task and so determines a fair day''s work.', 'Ethics, Law & Management', '⚖️'),
(623, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'What is the full form of MBO?', '["Management By Opportunity", "Method By opportunity", "Management By Objectives", "Method By Objective"]'::jsonb, 2, 'MBO is Management By Objectives.', 'Ethics, Law & Management', '⚖️'),
(624, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Management by Objectives concept was developed by -------.', '["Peter.F.Drucker", "Fayol", "Chester Bernard", "None"]'::jsonb, 0, 'Peter F. Drucker introduced MBO in The Practice of Management (1954).', 'Ethics, Law & Management', '⚖️'),
(625, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'MBO offers the basis for assessing the -----------------.', '["Techniques", "Performance", "Authority", "Subject"]'::jsonb, 1, 'MBO gives a basis for appraising performance against agreed objectives.', 'Ethics, Law & Management', '⚖️'),
(626, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Principles of management are not', '["behavioural.", "absolute.", "universal.", "flexible."]'::jsonb, 1, 'Management principles are flexible guidelines, not absolute laws.', 'Ethics, Law & Management', '⚖️'),
(627, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Principles of management provide', '["readymade solutions to problems.", "general guidelines.", "methods and procedures.", "rules and regulations."]'::jsonb, 1, 'Management principles are general guidelines that must be adapted to the situation.', 'Ethics, Law & Management', '⚖️'),
(628, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Management principles differ from pure science principles because management principles are', '["vague.", "situation-bound.", "rigid.", "easy to learn."]'::jsonb, 1, 'Management principles are situation-bound (contingent), unlike the exact principles of pure science.', 'Ethics, Law & Management', '⚖️'),
(629, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Principles of management are significant because these result in___________.', '["taking initiative.", "adapting to new technology.", "employee satisfaction.", "optimum utilisation of resources."]'::jsonb, 3, 'Applying management principles makes the best use of human and material resources.', 'Ethics, Law & Management', '⚖️'),
(630, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Which one of the following is not a principle of scientific management?', '["Functional foremanship", "Development of personnel", "Harmony, not discord", "Maximum, not restricted output"]'::jsonb, 0, 'Functional foremanship is a technique of scientific management, not one of its principles.', 'Ethics, Law & Management', '⚖️'),
(631, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Unity of command is related to', '["superiors and subordinates.", "management and workers.", "planned actions.", "cooperation among employees."]'::jsonb, 0, 'Unity of command concerns the superior–subordinate relationship.', 'Ethics, Law & Management', '⚖️'),
(632, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Gang plank is related to', '["communication.", "motivation.", "supervision of workers.", "incentives to workers."]'::jsonb, 0, 'Fayol''s gang plank lets employees at the same level communicate directly in an emergency, bypassing the scalar chain.', 'Ethics, Law & Management', '⚖️'),
(633, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Management principles are flexible whereas ______________ principles are rigid.', '["Pure Science", "Employment", "Scientific Management", "Art"]'::jsonb, 0, 'Management principles are flexible, whereas pure science principles are rigid and exact.', 'Ethics, Law & Management', '⚖️'),
(634, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', '___________ denotes concentration of authority at the top level.', '["Decentralisation", "Centralisation", "Coordination", "Delegation"]'::jsonb, 1, 'Centralisation concentrates decision-making authority at the top.', 'Ethics, Law & Management', '⚖️'),
(635, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', '__________ is the technique in which each worker is supervised by eight supervisors.', '["Functional foremanship", "Unity of action", "Centralisation", "Simplification of work"]'::jsonb, 0, 'Taylor''s functional foremanship has each worker supervised by eight specialist foremen.', 'Ethics, Law & Management', '⚖️'),
(636, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', '_________ principle of management puts emphasis on judicious application of penalties by the management.', '["Esprit de corps", "Order", "Division of work", "Discipline"]'::jsonb, 3, 'Fayol''s discipline principle calls for obedience to rules and fair, judicious use of penalties.', 'Ethics, Law & Management', '⚖️'),
(637, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', '_________ principle of management states that there should be a place for everything and everything should be in its place.', '["Equity", "Discipline", "Order", "Esprit de corps"]'::jsonb, 2, 'The principle of order: a place for everything and everything in its place.', 'Ethics, Law & Management', '⚖️'),
(638, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', '__________ means one plan, one boss.', '["Unity of direction", "Unity of command", "Centralisation", "Gang Plank"]'::jsonb, 0, 'Unity of direction means one head and one plan for a group of activities with the same objective.', 'Ethics, Law & Management', '⚖️'),
(639, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', '__________ involves harmony and team spirit among employees.', '["Discipline", "Esprit de corps", "Order", "Standardisation"]'::jsonb, 1, 'Esprit de corps promotes team spirit and harmony.', 'Ethics, Law & Management', '⚖️'),
(640, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Which scholar''s definition on management is " Management is the art of getting things done through and with people in formally organised groups"?', '["Harold Koontz", "J.N. Schulze", "S. George", "Henry Fayol"]'::jsonb, 0, 'Harold Koontz defined management as "the art of getting things done through and with people in formally organised groups".', 'Ethics, Law & Management', '⚖️'),
(641, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Which of the following is not a Management Principle ?', '["Order", "Discipline", "Equity", "Cooperation"]'::jsonb, 3, 'Order, discipline and equity are Fayol principles. Cooperation is not on his list.', 'Ethics, Law & Management', '⚖️'),
(642, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'The term hierarchy implies.........', '["departmentalisation", "a definite ranking order", "specialisation", "None of these"]'::jsonb, 1, 'A hierarchy is a definite ranking order of authority.', 'Ethics, Law & Management', '⚖️'),
(643, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Scientific analysis of work under scientific management requires......', '["time study", "motion study", "Both a & b", "work study"]'::jsonb, 2, 'Scientific work analysis needs both time study and motion study.', 'Ethics, Law & Management', '⚖️'),
(644, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Which scholar introduced the functional type of organisation?', '["F.W. Taylor", "Chester Bernard", "Allen", "Max Weber"]'::jsonb, 0, 'F. W. Taylor introduced the functional type of organisation (functional foremanship).', 'Ethics, Law & Management', '⚖️'),
(645, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', '_________ is known as the founder of Human Relation School.', '["Henry Fayol", "Elton Mayo", "Peter Drucker", "F.W. Taylor"]'::jsonb, 1, 'Elton Mayo, of the Hawthorne studies, founded the human relations school.', 'Ethics, Law & Management', '⚖️'),
(646, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Pervasiveness of planning indicates that planning', '["is a top management function.", "extends throughout the organisation.", "is a future-oriented activity.", "is the first element of management process."]'::jsonb, 1, 'Planning is pervasive: it happens at every level and in every department.', 'Ethics, Law & Management', '⚖️'),
(647, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Which one of the following is an importance of planning?', '["Reducing uncertainty", "Identifying alternatives critically", "Developing leadership", "Selecting the most appropriate plan"]'::jsonb, 0, 'Planning reduces uncertainty by anticipating future events.', 'Ethics, Law & Management', '⚖️'),
(648, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Which one of the following is not a limitation of planning?', '["Dynamic environment", "Costly process", "Rigidity", "Top management approach"]'::jsonb, 3, 'Planning''s limitations include rigidity, cost, time and a changing environment. "Top management approach" is not a recognised limitation.', 'Ethics, Law & Management', '⚖️'),
(649, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Which one of the following is a step of planning?', '["Analysis of organisation structure", "Analysis of environment", "Analysis of employee behaviour", "Analysis of employee morale"]'::jsonb, 1, 'Planning involves analysing the environment (premising), setting objectives, weighing alternatives and choosing a course of action.', 'Ethics, Law & Management', '⚖️'),
(650, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'The basic role of strategy is to provide', '["setting procedures.", "direction for action.", "direction for motivation.", "direction for control."]'::jsonb, 1, 'A strategy gives overall direction for action.', 'Ethics, Law & Management', '⚖️'),
(651, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Which one of the following plans prescribes chronological steps for performing activities?', '["Procedure", "Rule", "Policy", "Method"]'::jsonb, 0, 'A procedure sets out the chronological steps for doing an activity.', 'Ethics, Law & Management', '⚖️'),
(652, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Which one of the following is a single-use plan?', '["Strategy", "Rule", "Budget", "Method"]'::jsonb, 2, 'A budget is a single-use plan for a specific period. Rules, methods and policies are standing plans.', 'Ethics, Law & Management', '⚖️'),
(653, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Organising process includes one of the following:', '["Grouping of activities", "Prescribing disciplinary action", "Determining objectives", "Prescribing work schedule"]'::jsonb, 0, 'Organising groups activities into departments and assigns duties and authority.', 'Ethics, Law & Management', '⚖️'),
(654, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'One of the following is not an importance of organising:', '["Role clarity", "Performance appraisal", "Adaptation to change", "Growth and expansion"]'::jsonb, 1, 'Organising brings role clarity, adaptability and growth. Performance appraisal belongs to staffing and control.', 'Ethics, Law & Management', '⚖️'),
(655, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Organisation structure establishes relationships between', '["organisation and environment.", "people, work and resources.", "organisation and society.", "suppliers and customers."]'::jsonb, 1, 'Organisation structure links people, work and resources.', 'Ethics, Law & Management', '⚖️'),
(656, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'One of the following is an advantage of functional structure:', '["Responsibility for end results", "Flexibility", "Personalised attention", "Easier employee learning"]'::jsonb, 3, 'A functional structure groups similar specialists together, which makes training and learning easier.', 'Ethics, Law & Management', '⚖️'),
(657, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Divisional structure leads to conflict in', '["resource allocation.", "marketing management.", "motivation.", "planning process."]'::jsonb, 0, 'Divisions compete for shared resources, so divisional structures can cause conflict over resource allocation.', 'Ethics, Law & Management', '⚖️'),
(658, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'In which respect does formal organisation differ from informal organisation?', '["Production process", "Structuring", "Financial procedure", "Purchasing"]'::jsonb, 1, 'Formal organisations have a deliberate structure with defined roles. Informal ones arise spontaneously from social relationships.', 'Ethics, Law & Management', '⚖️'),
(659, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Which one of the following does not follow scalar chain?', '["Informal organisation", "Functional structure", "Formal organisation", "Divisional structure"]'::jsonb, 0, 'An informal organisation does not follow the scalar chain; communication flows freely.', 'Ethics, Law & Management', '⚖️'),
(660, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Degree of decentralisation indicates', '["degree of authority delegation.", "degree of responsibility.", "degree of power delegation.", "degree of accountability."]'::jsonb, 0, 'The degree of decentralisation reflects how far authority is delegated down the hierarchy.', 'Ethics, Law & Management', '⚖️'),
(661, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'In staffing function, which one of the following groups of managers is involved?', '["Only top managers", "Only human resource managers", "Only middle managers", "All managers"]'::jsonb, 3, 'Every manager takes part in staffing: selecting, training and appraising their own staff.', 'Ethics, Law & Management', '⚖️'),
(662, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Which one of the following is not an importance of staffing?', '["Suitable division of work among employees", "Developing skills in employees", "Employee satisfaction", "Efficient use of human resources"]'::jsonb, 0, 'Staffing develops skills, satisfies employees and uses people efficiently. Dividing work is organising.', 'Ethics, Law & Management', '⚖️'),
(663, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'In staffing function, which combination of activities in sequential order is correct?', '["Recruitment, selection, training, placement", "Selection, training, recruitment, placement", "Recruitment, selection, placement, training", "Recruitment, training, selection, placement"]'::jsonb, 2, 'The staffing sequence is recruitment, selection, placement, then training.', 'Ethics, Law & Management', '⚖️'),
(664, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Which one of the following sources is most relevant to recruiting managerial personnel?', '["Direct recruitment", "Employment exchange", "Advertisement", "Casual callers"]'::jsonb, 2, 'Managerial vacancies are usually filled through advertisement, which reaches suitably qualified candidates.', 'Ethics, Law & Management', '⚖️'),
(665, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Which one of the following is an internal source of recruitment?', '["Transfer", "Employee recommendations", "Campus recruitment", "Personal contacts"]'::jsonb, 0, 'Transfer and promotion are internal sources of recruitment.', 'Ethics, Law & Management', '⚖️'),
(666, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Which type of learning is management development concerned with?', '["Specific job skill development", "Multi-skill development", "Manual skill development", "Inventory development"]'::jsonb, 1, 'Management development builds broad, multiple skills for managerial roles.', 'Ethics, Law & Management', '⚖️'),
(667, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'For which group of persons is vestibule training relevant?', '["Operatives", "Top management", "Middle management", "Supervisory management"]'::jsonb, 0, 'Vestibule training uses a simulated workplace for operatives who work on machines or equipment.', 'Ethics, Law & Management', '⚖️'),
(668, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Which one of the following is an element of directing?', '["Delegating authority", "Designing organisation structure", "Communication", "Designing control system"]'::jsonb, 2, 'Directing consists of supervision, motivation, leadership and communication.', 'Ethics, Law & Management', '⚖️'),
(669, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Motivation is not', '["a complex process.", "related to satisfaction.", "an easy process.", "a goal-directed behaviour."]'::jsonb, 2, 'Motivation is complex and goal-directed. It is not easy.', 'Ethics, Law & Management', '⚖️'),
(670, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Need hierarchy theory of motivation has been given by', '["Maslow.", "Fayol.", "Taylor.", "Koontz."]'::jsonb, 0, 'Abraham Maslow gave the need hierarchy theory of motivation.', 'Ethics, Law & Management', '⚖️'),
(671, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Which one of the following is not a financial incentive?', '["Bonus", "Provident Fund", "Co-partnership", "Challenging job"]'::jsonb, 3, 'A challenging job is a non-financial incentive. Bonus, provident fund and co-partnership are financial.', 'Ethics, Law & Management', '⚖️'),
(672, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Which one of the following is a non-financial incentive?', '["Recognition", "Perquisite", "Retirement benefit", "Stock option"]'::jsonb, 0, 'Recognition is a non-financial incentive.', 'Ethics, Law & Management', '⚖️'),
(673, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Leadership is based on a superior’s', '["authority.", "responsibility.", "accountability.", "persuasive communication."]'::jsonb, 3, 'Leadership rests on influence (persuasive communication) more than formal authority.', 'Ethics, Law & Management', '⚖️'),
(674, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Encoding is related to', '["converting message into symbols.", "converting symbols into message.", "transmitting message.", "receiving symbols."]'::jsonb, 0, 'Encoding converts a message into symbols such as words or gestures.', 'Ethics, Law & Management', '⚖️'),
(675, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Grapevine is a form of', '["formal communication.", "channel of communication.", "informal communication.", "barrier to communication."]'::jsonb, 2, 'The grapevine is informal communication.', 'Ethics, Law & Management', '⚖️'),
(676, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Which one of the following is a semantic barrier?', '["Organisational policy", "Lack of attention", "Technical jargon", "Status"]'::jsonb, 2, 'Semantic barriers come from language, e.g. technical jargon or faulty translation.', 'Ethics, Law & Management', '⚖️'),
(677, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Which one of the following is not a feature of controlling?', '["Continuous process", "Action-oriented", "Keeping employees busy", "Pervasive function"]'::jsonb, 2, 'Controlling is continuous, action-oriented and pervasive. Keeping employees busy is not its purpose.', 'Ethics, Law & Management', '⚖️'),
(678, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Which one of the following is not an importance of controlling?', '["Better coordination", "Better use of resources", "Better planning", "Better grievance handling"]'::jsonb, 3, 'Controlling improves coordination, resource use and planning. Grievance handling is not its purpose.', 'Ethics, Law & Management', '⚖️'),
(679, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Which one of the following is a step of controlling?', '["Assessing personnel required", "Taking corrective action", "Assessing environment", "Taking disciplinary action"]'::jsonb, 1, 'Controlling: set standards, measure performance, compare and analyse deviations, take corrective action.', 'Ethics, Law & Management', '⚖️'),
(680, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', '___________ is the process of ensuring that actual results are in accordance with planned results.', '["Controlling", "Coordinating", "Planning", "Directing"]'::jsonb, 0, 'Controlling makes sure actual results match planned results.', 'Ethics, Law & Management', '⚖️'),
(681, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', '_________ is the focus point for a manager while controlling, as controlling at every step is not possible.', '["Controlling", "Coordinating", "Critical point control", "Both a and b"]'::jsonb, 2, 'Critical point control focuses on key result areas, since controlling everything is impractical.', 'Ethics, Law & Management', '⚖️'),
(682, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Controlling is ________.', '["Forward looking", "Backward looking", "Continous process", "All of these"]'::jsonb, 3, 'Controlling is continuous and looks both backward (past performance) and forward (future improvement).', 'Ethics, Law & Management', '⚖️'),
(683, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Decision-making is the case of __________.', '["Planning", "Organising", "Staffing", "Directing"]'::jsonb, 0, 'Decision-making, choosing among alternatives, is the core of planning.', 'Ethics, Law & Management', '⚖️'),
(684, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', '__________ is a statement of expected results in numerical terms.', '["Forecast", "Budget", "Plan", "Estimate"]'::jsonb, 1, 'A budget states expected results in numerical (financial or quantitative) terms.', 'Ethics, Law & Management', '⚖️'),
(685, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', '__________ is a feature of planning also referred to as primacy of planning.', '["Pervasive", "Primary function of management", "Continuous", "Integrating"]'::jsonb, 1, 'Primacy of planning: planning is the primary function and precedes all others.', 'Ethics, Law & Management', '⚖️'),
(686, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', '__________ is a comprehensive plan for achieving its objectives.', '["Strategy", "Method", "Rule", "Policy"]'::jsonb, 0, 'A strategy is a comprehensive plan for achieving the organisation''s objectives.', 'Ethics, Law & Management', '⚖️'),
(687, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', '__________ are relevant to recurring activities.', '["Single-use plans", "Standing plans", "Objectives", "Programmes"]'::jsonb, 1, 'Standing plans (policies, procedures, rules) cover recurring activities.', 'Ethics, Law & Management', '⚖️'),
(688, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', '___________ involves giving authority and responsibility to subordinates.', '["Division of work", "Decentralisation", "Delegation", "Centralisation"]'::jsonb, 2, 'Delegation gives a subordinate authority and responsibility for part of the work.', 'Ethics, Law & Management', '⚖️'),
(689, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', '__________ is the process of grouting similar activities together and creating departments.', '["Division of work", "Departmentalisation", "Delegation", "Centralisation"]'::jsonb, 1, 'Departmentalisation groups similar activities to create departments.', 'Ethics, Law & Management', '⚖️'),
(690, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', '_________ is the right to command.', '["Authority", "Responsibility", "Accountability", "Both a and b"]'::jsonb, 0, 'Authority is the right to command and make decisions.', 'Ethics, Law & Management', '⚖️'),
(691, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', '____________ is a process of learning and growth.', '["Training", "Development", "Recruitment", "Both a and b"]'::jsonb, 1, 'Development is a broad, continuous process of learning and growth. Training targets specific job skills.', 'Ethics, Law & Management', '⚖️'),
(692, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', '___________ leads to optimum use of resources.', '["Recruitment", "Staffing", "Development", "Training"]'::jsonb, 1, 'Good staffing puts the right people in the right jobs, which makes the best use of resources.', 'Ethics, Law & Management', '⚖️'),
(693, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', '__________ is the “On the Job Training” method used to train electricians.', '["Web publishing", "Job rotation", "Coaching", "Apprenticeship"]'::jsonb, 3, 'Apprenticeship is on-the-job training for crafts and trades such as electricians and plumbers.', 'Ethics, Law & Management', '⚖️'),
(694, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Directing flows in ____________ direction.', '["Upward", "Downward", "Diagonal", "Both a and b"]'::jsonb, 1, 'Directing flows downward, from superiors to subordinates.', 'Ethics, Law & Management', '⚖️'),
(695, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', '____________ is the process of exchanging information and understanding between two or more persons.', '["Directing", "Leadership", "Communication", "Motivation"]'::jsonb, 2, 'Communication is exchanging information and understanding between two or more people.', 'Ethics, Law & Management', '⚖️'),
(696, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'What is the full form of TQM?', '["Total quality measurement", "Total quantity management", "Typical quality management", "Total quality management"]'::jsonb, 3, 'TQM is Total Quality Management: a continuous, organisation-wide, customer-focused approach to quality.', 'Ethics, Law & Management', '⚖️'),
(697, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'According to Kurt Lewin, which of the following is not a stage in the change process?', '["Unfreezing", "Changing", "Refreezing", "Restraining"]'::jsonb, 3, 'Lewin''s change model is unfreezing, changing (moving) and refreezing. Restraining forces belong to his force-field analysis.', 'Ethics, Law & Management', '⚖️'),
(698, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'A company that decides to decentralize its sales procedures is managing what change category?', '["Technology", "People", "Competitors", "Structure"]'::jsonb, 3, 'Decentralising procedures changes authority and reporting, which is a structural change.', 'Ethics, Law & Management', '⚖️'),
(699, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Which of the following statements is true', '["In small quantities, stress is good", "Too much stress is harmful", "All stress is bad", "Only a & b are right"]'::jsonb, 3, 'Moderate stress (eustress) can motivate. Too much stress is harmful.', 'Ethics, Law & Management', '⚖️'),
(700, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Total Quality Management (TQM) focuses on', '["Employee", "Customer", "Both a and b", "None of the above"]'::jsonb, 2, 'TQM focuses on both customers and employees (empowerment, teamwork).', 'Ethics, Law & Management', '⚖️'),
(701, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Which of the following is responsible for quality objective?', '["Top level Management", "Middle level Management", "Frontline Management", "All of the above"]'::jsonb, 0, 'Top management sets the quality policy and objectives.', 'Ethics, Law & Management', '⚖️'),
(702, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', '"Quality is defined by the customer" is', '["An unrealistic definition of quality", "A user-based definition of quality", "A manufacturing-based definition of quality", "A product-based definition of quality"]'::jsonb, 1, '"Quality is defined by the customer" is a user-based definition of quality.', 'Ethics, Law & Management', '⚖️'),
(703, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'What is quality assurance?', '["Quality assurance deals with activities which prove that products and services meet the required quality standard", "Quality assurance deals with activities which aim at customers satisfaction", "Quality assurance deals with controlling the quality of products by inspection", "All of the above"]'::jsonb, 0, 'Quality assurance is the planned, systematic activity that shows products or services meet the required standards.', 'Ethics, Law & Management', '⚖️'),
(704, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Which quality management program is related to the maintenance of plants and equipments?', '["Environmental management systems", "Fault tree analysis", "Failure mode effect analysis", "Total productive maintenance"]'::jsonb, 3, 'Total productive maintenance keeps plant and equipment in good condition to avoid breakdowns.', 'Ethics, Law & Management', '⚖️'),
(705, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'The aim of Just-In-Time manufacturing principle is to eliminate', '["time wastage", "labour wastage", "cost of excessive inventory", "All of the above"]'::jsonb, 3, 'Just-in-time aims to eliminate waste of time, labour and excess inventory.', 'Ethics, Law & Management', '⚖️'),
(706, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Stress management is about learning', '["How to avoid the pressures of life", "How to develop skills that would enhance our body’s adjustment when we are subjected to the pressures of life", "Both ‘a’ & ‘b’ are true", "None of the above"]'::jsonb, 1, 'Stress management builds skills that help the body and mind adjust to life''s pressures, since pressure cannot be avoided altogether.', 'Ethics, Law & Management', '⚖️'),
(707, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', 'Which of the following statements is true about stress management?', '["Stress management is learning about the connection between mind and body", "Stress management helps us control our health in a positive sense", "Stress management teaches us to avoid all kinds of stress", "Only ‘a’ & ‘b’ are right"]'::jsonb, 3, 'Stress management links mind and body and helps control health positively. Avoiding all stress is impossible and undesirable.', 'Ethics, Law & Management', '⚖️'),
(708, 'Principles of Management MCQs', 'Principles of Management MCQ bank (uploaded)', '____________ is an inevitable factor for achieving economic growth.', '["Stress", "TQM", "Change", "None of these"]'::jsonb, 2, 'Change is inevitable for economic growth and organisational survival.', 'Ethics, Law & Management', '⚖️'),
(709, 'Oxygen Delivery & Cardiac Function', 'Original questions written from uploaded ICU therapy notes (oxygen delivery & cardiac function)', 'Oxygen delivery (DO2) to the tissues is calculated as:', '["Cardiac output × arterial oxygen content", "Heart rate × stroke volume", "Haemoglobin × PaO2", "Minute ventilation × FiO2"]'::jsonb, 0, 'Oxygen delivery (DO2) = cardiac output × arterial oxygen content (CaO2). Both flow and the oxygen carried in the blood matter.', 'Cardiovascular', '🫀'),
(710, 'Oxygen Delivery & Cardiac Function', 'Original questions written from uploaded ICU therapy notes (oxygen delivery & cardiac function)', 'Most of the oxygen carried in arterial blood is:', '["Dissolved in plasma", "Bound to haemoglobin", "Carried as bicarbonate", "Bound to albumin"]'::jsonb, 1, 'CaO2 = (Hb × SaO2 × 1.34) + (PaO2 × 0.003 per mmHg). Almost all of it is the haemoglobin-bound part.', 'Respiratory', '🫁'),
(711, 'Oxygen Delivery & Cardiac Function', 'Original questions written from uploaded ICU therapy notes (oxygen delivery & cardiac function)', 'An arterial oxygen saturation of about 90% corresponds roughly to a PaO2 of:', '["30 mmHg", "40 mmHg", "60 mmHg", "100 mmHg"]'::jsonb, 2, 'Because of the sigmoid dissociation curve, SaO2 of about 90% (PaO2 about 60 mmHg) still gives near-normal oxygen content. Below this, saturation falls steeply.', 'Respiratory', '🫁'),
(712, 'Oxygen Delivery & Cardiac Function', 'Original questions written from uploaded ICU therapy notes (oxygen delivery & cardiac function)', 'With a normal CaO2 of about 200 mL/L and a cardiac output of 5 L/min, oxygen delivery is approximately:', '["250 mL/min", "500 mL/min", "1,000 mL/min", "5,000 mL/min"]'::jsonb, 2, 'Normal arterial blood carries about 200 mL O2 per litre. With a cardiac output of about 5 L/min, DO2 is about 1,000 mL/min.', 'Respiratory', '🫁'),
(713, 'Oxygen Delivery & Cardiac Function', 'Original questions written from uploaded ICU therapy notes (oxygen delivery & cardiac function)', 'At rest, the tissues normally extract about what percentage of the oxygen delivered?', '["5%", "25%", "60%", "90%"]'::jsonb, 1, 'Resting oxygen consumption (VO2) is about 250 mL/min, so tissues normally extract about 25% of the oxygen delivered.', 'Respiratory', '🫁'),
(714, 'Oxygen Delivery & Cardiac Function', 'Original questions written from uploaded ICU therapy notes (oxygen delivery & cardiac function)', 'The normal mixed venous oxygen saturation (SvO2) is approximately:', '["40–45%", "50–55%", "70–75%", "95–100%"]'::jsonb, 2, 'Mixed venous blood normally has PvO2 about 40 mmHg and SvO2 about 70–75%.', 'Respiratory', '🫁'),
(715, 'Oxygen Delivery & Cardiac Function', 'Original questions written from uploaded ICU therapy notes (oxygen delivery & cardiac function)', 'Which of the following DECREASES oxygen consumption?', '["Fever", "Shivering", "Sedation and neuromuscular paralysis", "Agitation"]'::jsonb, 2, 'Oxygen consumption rises with fever, exercise, shivering and agitation, and falls with sedation, paralysis and hypothermia.', 'Respiratory', '🫁'),
(716, 'Oxygen Delivery & Cardiac Function', 'Original questions written from uploaded ICU therapy notes (oxygen delivery & cardiac function)', 'A fall in venous oxygen saturation below 70% indicates:', '["Reduced oxygen extraction", "An oxygen supply–demand imbalance with increased extraction", "Hyperoxia", "Normal tissue perfusion"]'::jsonb, 1, 'A low SvO2 or ScvO2 means tissues are extracting more oxygen, from falling delivery (low CO, Hb or SaO2) or rising demand.', 'Shock & Haemorrhage', '⚡'),
(717, 'Oxygen Delivery & Cardiac Function', 'Original questions written from uploaded ICU therapy notes (oxygen delivery & cardiac function)', 'For monitoring global perfusion, venous oxygen saturation is NOT reliably measured from a:', '["Central venous catheter in the superior vena cava", "Pulmonary artery catheter", "Femoral venous catheter", "Continuous oximetric central catheter"]'::jsonb, 2, 'Femoral venous saturation reflects only the legs. Global ScvO2 is sampled from the SVC (central line) or pulmonary artery (SvO2).', 'Shock & Haemorrhage', '⚡'),
(718, 'Oxygen Delivery & Cardiac Function', 'Original questions written from uploaded ICU therapy notes (oxygen delivery & cardiac function)', 'In septic shock, a normal or high venous oxygen saturation:', '["Always means adequate tissue oxygenation", "May occur despite tissue hypoxia because of microvascular maldistribution of flow", "Proves the patient is hypovolaemic", "Means the catheter is in the wrong place"]'::jsonb, 1, 'In sepsis, maldistributed microvascular flow and impaired cellular oxygen use can give a normal or high SvO2 despite tissue hypoxia, often with a worse prognosis.', 'Shock & Haemorrhage', '⚡'),
(719, 'Oxygen Delivery & Cardiac Function', 'Original questions written from uploaded ICU therapy notes (oxygen delivery & cardiac function)', 'Serial blood lactate measurements are used in shock mainly to:', '["Assess renal function", "Monitor tissue hypoperfusion (anaerobic metabolism) and response to therapy", "Measure haemoglobin", "Estimate cardiac preload"]'::jsonb, 1, 'Lactate is a product of anaerobic metabolism. Serial levels track tissue hypoperfusion and response to resuscitation.', 'Shock & Haemorrhage', '⚡'),
(720, 'Oxygen Delivery & Cardiac Function', 'Original questions written from uploaded ICU therapy notes (oxygen delivery & cardiac function)', 'The normal cardiac index (CI) is:', '["0.5–1 L/min/m²", "1–2 L/min/m²", "2.5–4 L/min/m²", "6–8 L/min/m²"]'::jsonb, 2, 'Cardiac index = cardiac output ÷ body surface area. Normal is 2.5–4 L/min/m².', 'Cardiovascular', '🫀'),
(721, 'Oxygen Delivery & Cardiac Function', 'Original questions written from uploaded ICU therapy notes (oxygen delivery & cardiac function)', 'Cardiac output is the product of:', '["Stroke volume and heart rate", "Preload and afterload", "Blood pressure and heart rate", "Ejection fraction and end-diastolic volume"]'::jsonb, 0, 'Cardiac output = stroke volume × heart rate, about 70 mL × 70 bpm ≈ 5 L/min.', 'Cardiovascular', '🫀'),
(722, 'Oxygen Delivery & Cardiac Function', 'Original questions written from uploaded ICU therapy notes (oxygen delivery & cardiac function)', 'Stroke volume is determined by:', '["Preload, afterload and contractility", "Heart rate only", "Blood viscosity only", "Oxygen saturation"]'::jsonb, 0, 'Stroke volume is set by preload, afterload and contractility.', 'Cardiovascular', '🫀'),
(723, 'Oxygen Delivery & Cardiac Function', 'Original questions written from uploaded ICU therapy notes (oxygen delivery & cardiac function)', 'A normal left ventricular ejection fraction is about:', '["20–25%", "35–40%", "60–65%", "85–90%"]'::jsonb, 2, 'Ejection fraction = SV ÷ EDV, e.g. 70/120 mL ≈ 60%. Normal is about 60–65%.', 'Cardiovascular', '🫀'),
(724, 'Oxygen Delivery & Cardiac Function', 'Original questions written from uploaded ICU therapy notes (oxygen delivery & cardiac function)', 'Preload is best defined as:', '["The wall tension the ventricle develops during ejection", "The end-diastolic volume of the ventricle", "The intrinsic contractility of heart muscle", "The aortic diastolic pressure"]'::jsonb, 1, 'Preload is the ventricular end-diastolic volume (fibre stretch) before contraction.', 'Cardiovascular', '🫀'),
(725, 'Oxygen Delivery & Cardiac Function', 'Original questions written from uploaded ICU therapy notes (oxygen delivery & cardiac function)', 'A hypovolaemic patient becomes hypotensive after intubation and positive-pressure ventilation mainly because:', '["Contractility increases", "Increased intrathoracic pressure reduces venous return", "Afterload falls to zero", "Heart rate falls"]'::jsonb, 1, 'Positive-pressure ventilation and PEEP raise intrathoracic pressure, reduce venous return (preload) and may cause hypotension, especially after intubation in hypovolaemic patients.', 'Cardiovascular', '🫀'),
(726, 'Oxygen Delivery & Cardiac Function', 'Original questions written from uploaded ICU therapy notes (oxygen delivery & cardiac function)', 'The Frank–Starling relationship states that:', '["Increased preload (fibre stretch) increases stroke volume, within limits", "Increased heart rate always decreases cardiac output", "Afterload has no effect on stroke volume", "Contractility depends only on heart rate"]'::jsonb, 0, 'Frank–Starling law: within limits, greater fibre stretch (preload) gives a stronger contraction and larger stroke volume.', 'Cardiovascular', '🫀'),
(727, 'Oxygen Delivery & Cardiac Function', 'Original questions written from uploaded ICU therapy notes (oxygen delivery & cardiac function)', 'According to the law of Laplace, ventricular wall tension (afterload) INCREASES with:', '["Thicker ventricular wall", "Higher pressure and larger ventricular radius", "Lower blood pressure", "Smaller ventricular cavity"]'::jsonb, 1, 'Afterload is the wall stress needed to eject blood. Laplace: tension ∝ (pressure × radius) ÷ (2 × wall thickness).', 'Cardiovascular', '🫀'),
(728, 'Oxygen Delivery & Cardiac Function', 'Original questions written from uploaded ICU therapy notes (oxygen delivery & cardiac function)', 'Which condition increases RIGHT ventricular afterload?', '["Aortic stenosis", "Systemic hypertension", "Acute massive pulmonary embolism", "Mitral regurgitation"]'::jsonb, 2, 'Hypertension and aortic stenosis raise left ventricular afterload. Pulmonary hypertension and PE raise right ventricular afterload.', 'Cardiovascular', '🫀'),
(729, 'Oxygen Delivery & Cardiac Function', 'Original questions written from uploaded ICU therapy notes (oxygen delivery & cardiac function)', 'Which ventricle is most sensitive to an increase in afterload?', '["A normal ventricle", "A hypertrophied athletic ventricle", "A failing ventricle with poor contractility", "None, afterload never affects stroke volume"]'::jsonb, 2, 'A failing ventricle (reduced contractility) is very sensitive to afterload: small rises in afterload sharply cut stroke volume.', 'Cardiovascular', '🫀'),
(730, 'Oxygen Delivery & Cardiac Function', 'Original questions written from uploaded ICU therapy notes (oxygen delivery & cardiac function)', 'Ventricular compliance is defined as:', '["Change in pressure ÷ change in volume", "Change in volume ÷ change in pressure", "Stroke volume ÷ end-diastolic volume", "Cardiac output ÷ body surface area"]'::jsonb, 1, 'Compliance = change in volume ÷ change in pressure. A stiff (non-compliant) ventricle has higher filling pressure at the same volume.', 'Cardiovascular', '🫀'),
(731, 'Oxygen Delivery & Cardiac Function', 'Original questions written from uploaded ICU therapy notes (oxygen delivery & cardiac function)', 'CVP and pulmonary capillary wedge pressure:', '["Directly and accurately measure ventricular volume", "Measure filling pressures, which correlate imperfectly with preload volume", "Measure contractility", "Measure afterload"]'::jsonb, 1, 'CVP and PCWP are filling pressures. They correlate poorly with true volume because compliance and vascular tone vary.', 'Cardiovascular', '🫀'),
(732, 'Oxygen Delivery & Cardiac Function', 'Original questions written from uploaded ICU therapy notes (oxygen delivery & cardiac function)', 'A recognised adverse effect of inotropic infusions (e.g. dobutamine) is:', '["Bradycardia", "Reduced myocardial oxygen demand", "Tachyarrhythmias and myocardial ischaemia", "Hypoglycaemia"]'::jsonb, 2, 'Inotropes such as dobutamine, dopamine and adrenaline raise contractility but can cause tachycardia, arrhythmias and myocardial ischaemia by increasing oxygen demand.', 'ICU Pharmacology', '💊'),
(733, 'Oxygen Delivery & Cardiac Function', 'Original questions written from uploaded ICU therapy notes (oxygen delivery & cardiac function)', 'A disadvantage of a very fast heart rate is that it:', '["Increases diastolic filling time", "Shortens diastolic filling time and increases myocardial oxygen demand", "Reduces myocardial oxygen demand", "Always increases stroke volume"]'::jsonb, 1, 'Faster heart rates raise myocardial oxygen demand and shorten diastole, reducing ventricular filling (and coronary perfusion time).', 'Cardiovascular', '🫀'),
(734, 'Anaesthetic Agents', 'Original questions written from uploaded anaesthesia notes', 'The aims of premedication before anaesthesia include all EXCEPT:', '["Reducing anxiety", "Allowing a lower anaesthetic dose", "Providing pre-emptive analgesia", "Increasing airway secretions"]'::jsonb, 3, 'Premedication reduces anxiety, lowers the anaesthetic dose (and its side effects) and provides pre-emptive analgesia.', 'Anaesthesia & Perioperative Care', '💉'),
(735, 'Anaesthetic Agents', 'Original questions written from uploaded anaesthesia notes', 'Atropine or glycopyrrolate is given during anaesthesia mainly to:', '["Produce muscle relaxation", "Prevent bradycardia and reduce airway secretions", "Provide analgesia", "Reverse opioids"]'::jsonb, 1, 'Anticholinergics (atropine, glycopyrrolate) block muscarinic receptors, reducing secretions and vagal bradycardia during anaesthesia.', 'Anaesthesia & Perioperative Care', '💉'),
(736, 'Anaesthetic Agents', 'Original questions written from uploaded anaesthesia notes', 'Compared with atropine, glycopyrrolate:', '["Crosses the blood–brain barrier more readily", "Has a longer action with less tachycardia and fewer central effects", "Has no antisialagogue effect", "Is an opioid antagonist"]'::jsonb, 1, 'Glycopyrrolate does not cross the blood–brain barrier, so it causes less central effect and less tachycardia than atropine, and acts longer.', 'Anaesthesia & Perioperative Care', '💉'),
(737, 'Anaesthetic Agents', 'Original questions written from uploaded anaesthesia notes', 'Midazolam used as a premedicant provides:', '["Anxiolysis, sedation and amnesia but no analgesia", "Strong analgesia", "Neuromuscular blockade", "Increased respiratory secretions"]'::jsonb, 0, 'Benzodiazepines such as midazolam and diazepam are anxiolytic, sedative and amnesic, but they are not analgesic.', 'Anaesthesia & Perioperative Care', '💉'),
(738, 'Anaesthetic Agents', 'Original questions written from uploaded anaesthesia notes', 'A characteristic side effect of alpha-2 adrenergic agonists such as dexmedetomidine is:', '["Tachycardia", "Bradycardia and hypotension", "Malignant hyperthermia", "Severe bronchospasm"]'::jsonb, 1, 'Alpha-2 agonists (dexmedetomidine, clonidine, xylazine) give sedation with some analgesia but can cause bradycardia and hypotension.', 'Anaesthesia & Perioperative Care', '💉'),
(739, 'Anaesthetic Agents', 'Original questions written from uploaded anaesthesia notes', 'The most important adverse effect of opioids given around anaesthesia is:', '["Respiratory depression", "Hypertension", "Diarrhoea", "Mydriasis"]'::jsonb, 0, 'Opioids give analgesia and CNS depression, which reduces the anaesthetic dose. Respiratory depression is the main hazard.', 'Anaesthesia & Perioperative Care', '💉'),
(740, 'Anaesthetic Agents', 'Original questions written from uploaded anaesthesia notes', 'Chlorpromazine given as a tranquilliser may cause:', '["Hypertension", "Hypotension", "Hyperglycaemia", "Bronchodilation"]'::jsonb, 1, 'Phenothiazines such as chlorpromazine can cause marked hypotension through alpha-adrenergic blockade.', 'Anaesthesia & Perioperative Care', '💉'),
(741, 'Anaesthetic Agents', 'Original questions written from uploaded anaesthesia notes', 'Neuromuscular blocking drugs used as adjuncts to anaesthesia provide:', '["Analgesia", "Unconsciousness", "Skeletal muscle relaxation only", "Sedation and amnesia"]'::jsonb, 2, 'Neuromuscular blockers paralyse muscle but give NO analgesia or unconsciousness, so adequate anaesthesia must be ensured to prevent awareness.', 'Anaesthesia & Perioperative Care', '💉'),
(742, 'Anaesthetic Agents', 'Original questions written from uploaded anaesthesia notes', 'The key difference between local and general anaesthesia is that local anaesthesia:', '["Causes loss of consciousness", "Blocks sensation in a region without loss of consciousness", "Always needs intubation", "Lasts longer than general anaesthesia"]'::jsonb, 1, 'Local anaesthetics block sensation in a region without loss of consciousness. General anaesthetics produce reversible unconsciousness.', 'Anaesthesia & Perioperative Care', '💉'),
(743, 'Anaesthetic Agents', 'Original questions written from uploaded anaesthesia notes', 'An advantage of inhalational over injectable anaesthetics is that:', '["Depth of anaesthesia is easier to control and adjust", "They never cause respiratory depression", "No equipment is needed", "They have no cardiovascular effects"]'::jsonb, 0, 'Inhaled agents allow easier, faster control of depth (they are eliminated via the lungs) than injectable agents, which cannot be withdrawn once given.', 'Anaesthesia & Perioperative Care', '💉'),
(744, 'Anaesthetic Agents', 'Original questions written from uploaded anaesthesia notes', 'Minimum alveolar concentration (MAC) of an inhalational agent is a measure of its:', '["Potency", "Duration", "Toxicity", "Cost"]'::jsonb, 0, 'MAC is the alveolar concentration that prevents movement in 50% of subjects to a surgical stimulus. A lower MAC means a more potent agent.', 'Anaesthesia & Perioperative Care', '💉'),
(745, 'Anaesthetic Agents', 'Original questions written from uploaded anaesthesia notes', 'During recovery from general anaesthesia, the priority nursing care is:', '["Maintaining a patent airway and monitoring vital signs", "Early oral feeding", "Leaving the patient alone to rest", "Stopping all analgesia"]'::jsonb, 0, 'Recovery care needs airway monitoring, warmth (to prevent hypothermia), continued analgesia and observation of vital signs until protective reflexes return.', 'Anaesthesia & Perioperative Care', '💉')
) as v(n, topic, source, q, opts, ans_idx, exp, category, category_icon)
where not exists (
  select 1 from public.questions x
  where regexp_replace(lower(x.q), '[^a-z0-9]', '', 'g') = regexp_replace(lower(v.q), '[^a-z0-9]', '', 'g')
);

-- Answer-key fixes for existing questions (each only applies if the options are as expected).
update public.questions
   set ans_idx = 2,
       exp = 'A living will is the advance directive that lists the treatments a person chooses to refuse if they can no longer decide. A durable power of attorney names a proxy decision-maker instead.'
 where q ilike 'A document that lists the medical treatment a person chooses to refuse%'
   and opts->>2 ilike 'Living will%' and ans_idx = 3;

update public.questions
   set ans_idx = 3,
       exp = 'In sickle-cell trait (HbAS) the major haemoglobin is still HbA (about 60%). HbS makes up only about 35–40%.'
 where q ilike 'Which is the major Hgb found in the RBCs of patients with sickle cell trait%'
   and opts->>3 ilike 'Hgb A' and ans_idx = 0;

update public.questions
   set ans_idx = 2,
       exp = 'Asking for help, getting training and taking daily breaks are healthy caregiver strategies. Working ever harder to pay the bills adds to the stress.'
 where q ilike 'The following are Caregiver stress management in the family except%'
   and opts->>2 ilike 'Working hard to pay the family bills%' and ans_idx = 3;
